INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23093987378', 'Cabo de Áudio Ugreen 3.5mm para 2Rca Macho 1.5 Metro Preto', 'Cabo de Áudio Ugreen 3.5mm para 2Rca Macho 1.5 Metro Som Superior - Ideal para Conectar Smartphones Mp3 Tablets a Amplificadores ou AV Receivers - no Brasil Conectividade: O UGREEN 3.5mm Male para Cabo de 2RCA Male 1.5m (Preto) 10583 oferece aos usuários a conectividade com conectores padrão 3,5 mm com fones de ouvido, computadores de mesa e outros dispositivos compatíveis. O cabo pode conectar dispositivos com conectores RCA (Red - Right, White - Left). Possui 1,5 m de comprimento para garantir acesso conveniente à porta; Alta qualidade: O cabo UGREEN é fabricado com conectores chapados em ouro e cordão trançado de alta qualidade para proporcionar uma conexão confiável. Possui maior resistência a interferências externas, garantindo um som nítido e nítido, com pouco ruído; Aparência e design: O cabo possui bolso para o fone de ouvido de 3,5 mm, construção e aparência externa compacta, design duradouro, visual moderno e elegante, é prático e funcional; Compatibilidade: O UGREEN 3.5mm Male para Cabo de 2RCA Male 1.5m é compatível com fones de ouvido, computadores de mesa, amplificadores, leitores portáteis de música e vídeo, caixas de som, TVs, DVD players e outros dispositivos compatíveis com conexão de 3,5 mm em praticamente todos os dispositivos móveis; Durabilidade: Feito de materiais resistentes a arranhões e desgaste diário, o cabo garante durabilidade e operação ininterrupta. É resistente a choques, desgaste, raios UV, descargas elétricas e possíveis problemas de conexão. Garantia: 90 dias', 76.25, 76.25, NULL, 'Audio > Audio & Video Cables & Converters', 'https://cf.shopee.com.br/file/br-11134275-7r98o-m9yrqz55wa9u5f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1163157664%2F23093987378', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
