INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12975387047', 'Livro - Liga da justiça - Uma equipe de heróis', 'Certo dia, um bondoso homem chamado Noé recebeu um aviso dos céus: Eles deveria construir uma imensa arca. Qual será o motivo? Leia esta história para descobrir!_x000D_ _x000D_ Editora: Ciranda Cultural_x000D_ Edição: 1, 2020_x000D_ Autor: Paloma Blanca Alves Barbieri_x000D_ Idioma: Português_x000D_ Páginas: 10_x000D_ Dimensões: L 16.00 x A 19.90 x E 0.50_x000D_ ISBN: 9786555000122', 19.9, 19.9, NULL, 'Books & Magazines > Others', 'https://cf.shopee.com.br/file/dcb93ced222db6a037a4b34a7e9dbace', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F12975387047', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48109470385', 'Livro Livro mágico', 'ABRACADABRA! Além de aprender grandes truques de mágica, com este livro você vai surpreender a sua plateia! Separe a varinha, algumas cartas e moedas para começar o seu show de mágica! Basta folhear este livro para a magia começar! Editora: Ciranda Cultural Edição: 1, 2024 Autor: Ciranda Cultural Idioma: Português Páginas: 96 Dimensões: L 20.00 x A 27.00 x E 0.50 ISBN: 9786526116005 Coleção: Livro mágico Linha Editorial: Ciranda Cultural - Trade Faixa Etária: + 6 anos Assuntos (tags): Mágica, Magia, Objetos mágicos, Truques, Brincar, Diversão, Criatividade, Presente criativo, Presente, Brincadeira BISAC: Não Ficção Infantil / Não Ficção Infantil / Jogos e Atividades / Mágica Linha de Produto: Kit de mágica Encadernação: Brochura Acabamento: Laminação brilho Material: Papel', 19.9, 19.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-820mx-mng4u64402dd79', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F48109470385', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18097878062', 'Acabamento Registro Geral 50 mm Base Deca Padrão 16 Estrias Pressão 1''1/2 ou 1''1/4 Cromado Brilhante', 'ACABAMENTO DE REGISTRO 50 MM GAVETA OU PRESSÃO DE 1 1/2 OU 1 1/4 PARA BANHEIRO CHUVEIRO OU REGISTRO GERAL 16 ESTRIAS FIT CROMADO BRILHANTE. SOBRE O PRODUTO: O acabamento de registro tem a funcionabilidade de realizar a abertura e o fechamento do registro de pressão (chuveiros) e gaveta (geral de controle de fluxo de água). Além de nossos acabamentos serem referencia no mercado atualmente, eles vão levar elegância e sofisticação para seu banheiro. A peça chave que seu banheiro merece. ESPECIFICAÇÕES E COMPOSIÇÃO DO PRODUTO: 01- VOLANTE (MANOPLA) - METAL. 01- CANOPLA (BASE) - ABS. 01- APERTA CANOPLA - ABS. 01- CHAVE ALLEM - AÇO. 01- PARAFUSO ALLEM - AÇO. BITOLAS: 1 1/2" ou 1 1/4". MEDIDAS: VIDE FOTO. COMPATÍVEL COM REGISTROS: Deca, Hope Metais, Forusi, Bognar, Imperatriz, Leão Metais, Águia Metais, Pevilon Metais entre outros que seguem o mesmo padrão Deca de 16 estrias do pistão do registro. NÃO É COMPATÍVEL COM REGISTROS: Docol, Lorenzetti, Meber, Fabrimar ou qualquer outro fabricante que segue o mesmo padrão. DIFERECIAIS DO NOSSO PRODUTO: - O acabamento Nº 1 Do Brasil O MAIS VENDIDO! - Melhor acabamento do mercado. - Material resistente e de alta durabilidade. - Proporciona elegância ao seu ambiente. NOSSOS DIFERENCIAIS: - Preço de fábrica. - Envio mais rápido do Brasil. - Equipe com grande experiência para melhor atendê-los. - Produtos a pronta entrega. RECOMENDAÇÕES: - Limpe periodicamente os produtos utilizando um pano macio com sabão neutro. - Contrate um profissional para a instalação. - Nunca use produtos abrasivos como alcalinos, ácidos ou solventes nos produtos. Confira nossa lista, ou entre em contato conosco, temos peças de reposição à pronta entrega e atendimento a qualquer momento.', 49.9, 27.9, NULL, 'Home & Living > Bathrooms > Others', 'https://cf.shopee.com.br/file/br-11134207-820ly-mnacvctcd6v522', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F337531568%2F18097878062', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58258425581', 'Pincel marca texto Fluo''Peps Flex estojo 4 cores 740300 Maped', 'Marcadores de texto modernos com ponta flexível! Graças ao marcador de texto Maped Fluo Flex, você pode optar por um conforto excepcional ao destacar. A ponta flexível permite variar a espessura das linhas e realizar qualquer tipo de caligrafia. Ele pode destacar onde outros não conseguem, proporcionando uma sensação de deslize sem precedentes e conforto na escrita. Detalhes: - Ponta flexível - Espessura da linha varia entre 1, 2 e 5 mm - Ele pode permanecer aberto por até 4 horas sem secar. - Tinta à base de água', 45.77, 36.62, NULL, 'Stationery > Writing & Correction > Highlighters', 'https://cf.shopee.com.br/file/sg-11134201-81zw2-mmsy62lddqf56a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F916765392%2F58258425581', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23192824120', 'Sensor De Estacionamento Ré Visor Slim Gm Celta Prisma Todos', 'Sensor de Estacionamento 4 Pontos Cores Preto, Prata ou Branco Display LED Colorido Chega de sofrer na hora de fazer baliza, com esse Sensor de Estacionamento de 4 pontos você vai conseguir colocar seu carro até naquelas vagas mais apertadas, ou então deixar seu carro bem centralizado no estacionamento do prédio ou do shopping. Os sensores ficam super discretos no para-choque traseiro do seu carro e o produto já vai completo para instalação, incluindo chicotes, central, serra no tamanho ideal para realizar as furações e o display digital que vai ao painel do carro e alerta sobre o nível de proximidade dos obstáculos conforme eles se aproximam. Cor Disponível: - Prata - Preto - Branco OBS: As cores que não estiverem disponíveis não aparecerão no botão comprar do anúncio. Especificação Técnica: - Modelo Universal - Pode ser Pintado na Cor do seu Veículo (Não Realizamos Pinturas) - Sensores Ultrassônicos com Exata Precisão de Distância entre Veículos e Obstáculos - Confirmação de Instalação Adequada - Operam Normalmente com Quaisquer Condições Climáticas - Sistema Ativado Automaticamente Quando Acionada a Ré - Identificação de Obstrução ( Da Esquerda e da Direita) - Auto Inspeção de Função: o Display irá Mostrar Qual o Sensor está Quebrado, ou se um não Funciona Quando se Inicia - Tensão Nominal: 12V - Faixa de Voltagem Operacional: 10,5 ~200 mA - Distância de Detecção: 0,5 ~1,0 m - Frequência Ultrassônica: 40 KHz - Temperatura de Trabalho da Caixa de Comando: -30 ~+80°C - Medidas Aproximadas do Sensor (D. Int. x D. Ext.): 1,3x2,1 cm - Medidas Aproximadas do Display (CxA): 10x2 cm OBS: Em veículos com para-choque de ferro, é necessário isolar os sensores com uma leve camada de borracha para que não haja interferência. Conteúdo da Embalagem: - 4 Sensores - 1 Display Digital - 1 Central - Cabos para Instalação - Serra Copo Importante: - Valor do Kit. - Imagens Meramente Ilustrativas. - Recomendamos que a instalação seja feita por profissional especializado e não nos responsabilizamos pelo mau uso do produto.', 98.84, 98.84, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Parking Cameras and Sensors', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lr7tan9y9qg41f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F414508631%2F23192824120', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23494843046', 'Rack De Teto Bagageiro Corolla 2014 15 16 17 18 2019 Preto', 'Rack de Teto Bagageiro Suporte Fixação Porta para Corolla - VHIP Compatibilidade: ANOS: 2014, 2015, 2016, 2017, 2018, 2019 Quer mais espaço para VIAJAR, TRABALHAR ou levar seus equipamentos com SEGURANÇA? O Rack Teto Bagageiro Porta - VHIP é a escolha PERFEITA para quem busca praticidade, resistência, SEGURANÇA e visual moderno. Com capacidade para até 50 kg de carga, ele permite transportar malas, bicicletas, pranchas, caixas de ferramentas ou materiais de trabalho com total segurança e estabilidade, sem ocupar o espaço interno do veículo. Além disso a VHIP oferece a QUALIDADE atestada pela CERTIFICAÇÃO de Processo ISO 9001, FIQUE ATENTO antes de compra! POR QUE O RACK VHIP SEM DÚVIDAS É O MELHOR VENDIDO NO BRASIL: - Com Sistema antifurto exclusivo, que dificulta a remoção indevida e protege seu investimento. - Certificação ISO 9001 – segue padrões internacionais de qualidade e rastreabilidade. - Design esportivo com acabamento perfeito – visual moderno e elegante. - Parafusos em aço liga 12.9 – material de alta resistência e durabilidade. - Estrutura reforçada – suporta até 50 kg com segurança. - Pintura em poliéster – resistente à ferrugem e à corrosão, prolonga a vida útil. - Encaixe perfeito – instalação precisa, sem folgas (Seguir orientações do Manual de Instalação) - Não risca o carro – protege a pintura original (Seguir orientações do Manual de Instalação). - Não fura o teto – fixação inteligente sem necessidade de perfurações. - Altura ideal – evita contato e acidentes com o teto do veículo. - Haste de ajuste de pressão fixa – não solta, não trepida, garante estabilidade. - Produto novo e com garantia – segurança total na compra. VANTAGENS: - Mais segurança contra furtos graças ao sistema antifurto patenteado que dificulta a remoção. - Proteção contra ferrugem e intempéries com pintura automotiva de qualidade premium. - Instalação simples e sem danos ao veículo. - Durabilidade MUITO SUPERIOR aos racks comuns, por usar materiais de padrão industrial e seguindo normas ISO9001 no processo de produção - Estabilidade e silêncio durante o uso, sem trepidações. Ficha técnica: Peso suportado: até 50 kg Material Suporte: Aço Certificado com acabamento em pintura Poliéster Material Tubo : Aço Certificado Galvanizado Fixação: Na porta Cor: Preto fosco Instalação: Sistema de aperto rápido com proteção anti risco. Itens inclusos: 1 - Par de racks completos (2 barras) 1 - Kit de fixação com parafusos, arruelas e porcas 1 - Manual ilustrado para instalação Compre direto da nossa LOJA OFICIAL VHIP ACESSÓRIOS, atendemos todo Brasil com RAPIDEZ, QUALIDADE E TODO SUPORTE QUE VOCÊ MERECE! DUVIDAS SOBRE INSTALAÇÃO ? TEMOS EXCLUSIVO CANAL - CENTRO de APOIO TÉCNICO AGORA CLIQUE EM COMPRAR ou se tiver ALGUMA DÚVIDA FAÇA SUA PERGUNTA E RESPONDEREMOS RAPIDAMENTE : )', 294.88, 294.88, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Racks and Cargo Carrier', 'https://cf.shopee.com.br/file/sg-11134201-8259c-mqxs91b8djied0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1665097804%2F23494843046', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18738170636', 'Cola Silicone LOCTITE 598 Black Alta Temperatura 85g Loctite', 'Este anúncio contém: 1 (um) Cola silicone black alta temperatura 85g original da marca Loctite. Código do Fabricante: LOCTITE 598; Código Universal: 7891200016693. Vedante em pasta de silicone oximico vulcanizado à temperatura ambiente, preto, tixotrópico. LOCTITE® 598 é um vedante em pasta monocomponente, tixotrópico, de cor preto metálico, a base de silicone oximico, que vulcaniza a temperatura ambiente. Cura quando exposto à umidade do ar formando uma junta de borracha de silicone resistente e flexível. Resiste ao envelhecimento, intemperismo e ciclos térmicos sem endurecer, encolher ou rachar. Este produto é tipicamente usado em aplicações com temperatura de trabalho de -54 até +260°C. Excelente resistência à óleos de motor de automóveis. Melhora as características de suporte de carga e absorção de impacto da área de adesão. Aplicações típicas incluem cárter do óleo, transmissão, tampas de válvulas, válvulas e guias, tampas de engrenagem e tampas de diferenciais Dúvidas frequentes: 1 - Trabalhamos apenas com produtos novos, e com garantia; 2 - Produto a pronta entrega; 3 - Seus produtos serão enviados em até 24 horas úteis após a confirmação do pagamento. Sobre a empresa: Somos uma Auto Peças fundada em 1980, atuamos no mercado varejista de peças e acessórios, tendo como principais clientes oficinas mecânicas e consumidor final. Não achou o que procura? Ficou com alguma dúvida sobre o produto? Fale conosco através do campo de perguntas.', 90.83, 85.39, NULL, 'Home & Living > Tools & Home Improvement > Industrial Adhesives & Tapes', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m0d1w6wii0f42b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F519603839%2F18738170