INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23297995946', 'Porto Brasil Conjunto Com 4 Canecas Roma Branco 343Ml', 'O Conjunto com 4 Canecas Roma Branco 343ml combina praticidade e estética para o uso diário. Feito em faiança (cerâmica) feldspática com esmaltado vitrificado, mantém cor e brilho com cuidados simples. O design com aba e o relevo característico da linha Roma, inspirado na arquitetura clássica, valoriza a apresentação sem abrir mão da funcionalidade. Em Branco, atua como base neutra que harmoniza com diferentes composições. Para o café, chá ou cappuccino do dia a dia — robusta, com o charme do relevo clássico Roma. Compatível com micro-ondas e lava-louças. Variações leves de cor, peso e medidas são naturais do processo cerâmico. Para limpeza, use detergente neutro e esponja macia.', 118.9, 77.29, NULL, 'Home & Living > Dinnerware > Cups, Mugs & Glasses', 'https://cf.shopee.com.br/file/sg-11134201-7reqk-m1x91afb6gqwf7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1242213783%2F23297995946', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
