INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23692490410', 'Livro Pop-up Eu amo pets', 'Cãezinhos brincando com gravetos no parque, coelhos com focinhos fofos, hamsters correndo em sua roda Há tanto o que amar em nossos animaizinhos!Com texto rimado e pop-ups fantásticos, este livro vai encantar todos com os amigos pets, nas paginas repletas de cenas supercoloridas!_x000D_ _x000D_ Editora: Ciranda Cultural_x000D_ Edição: 1, 2023_x000D_ Autor: Ruth Redford_x000D_ Ilustrador: Louise Anglicas_x000D_ Idioma: Português_x000D_ Páginas: 10_x000D_ Dimensões: L 25.50 x A 22.50 x E 1.99_x000D_ ISBN: 9786526106754_x000D_ Coleção: Livro pop-up_x000D_ Linha Editorial: Ciranda Cultural - Não ficção_x000D_ Faixa Etária: + 4 anos_x000D_ Assuntos (tags): Animais de estimação , Animais, Bichos_x000D_ BISAC: Não Ficção Infantil / Animais / Animais de Estimação_x000D_ Linha de Produto: Pop-up_x000D_ Encadernação: Lombada quadrada_x000D_ Acabamento: Hot stamping_x000D_ Material: Papel', 64.9, 64.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rbmf-lmdo8fbgntolcf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F23692490410', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
