INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793228016', 'Cone Corneta Aluminio Hl 1425 Branco Boca P/ Driver Com Rosca 1 Polegada', 'CONE ALUMINIO 14-25 PARALELO - BRANCO Desenvolvido em alumínio rígido e resistente, este CONE CURTO impede a perda de volume ocasionada pela vibração do driver, apropriado para sistemas de som automotivo e profissional, desde caixas trio até P.A., além de sua funcionalidade, possui design moderno e durabilidade impressionante! Seu encaixe rosca o torna compatível com a maioria dos drivers de 1 polegada disponíveis no mercado, como por exemplo: JBL Selenium D200, D250X, D250TRIO, D220TI, Eros EFD-252, EFD-300, ETD-44, entre outros. INFORMAÇÕES BÁSICAS: - Modelo: 14-25 - Formato: Curto Redondo - Fixação: ROSCA ESPECIFICAÇÕES: - Material: Alumínio rígido - Bocal: Redondo - Garganta: 25mm (1 Polegada); - Dimensões Aproximadas (Largura x Altura x Profundidade): 15,5 cm x 17,5 cm x 15 cm CONTEÚDO DA EMBALAGEM: - 01 Cone Curto Redondo Branco Importante: - Valor da Unidade - Imagens Meramente Ilustrativas. - Recomendamos que a instalação seja feita por profissional especializado e não nos responsabilizamos pelo mau uso do produto.', 59.79, 59.79, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/br-11134207-820le-mq20hxz9c3y9c1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F414508631%2F23793228016', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58205855907', 'Tapete Antiderrapante com Ventosas para Banho Dino Buba', 'Tapete Antiderrapante com Ventosas para Banho Dino Buba Os tapetes de banho da Buba foram desenvolvidos para garantir a segurança na hora do banho. Com ele, você pode ficar despreocupado e curtir esse momento tão gostoso com seu pequeno. Com múltiplas ventosas que fixam o tapete no chão e sua superfície antiderrapante, previne os escorregamentos. A estampa lúdica estimula a criatividade e as brincadeiras garantindo um banho cheio de diversão! Tamanho do Tapete Aberto: 38cm x 70cm Ideal para evitar que a criança escorregue; muito mais segurança na hora do banho! Características Técnicas: - Conteúdo da Embalagem: 01 Tapete Para Banho Buba. - Dimensões Aproximadas do Produto: Tapete Aberto: 69cm x 39cm (Comprimento x Largura) - Dimensões Aproximadas da Embalagem: 47cm x 9cm x 6cm (Altura x Largura x Comprimento/Profundidade) - Material/Composição: 100% Policloreto de Vinila (PVC). - Marca: Buba Outras informações: As cores podem variar entre as imagens mostradas acima e o produto. Imagens meramente ilustrativas.', 56.39, 49.99, NULL, 'Mom & Baby > Bath & Body Care > Bathing Tools & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-82601-ml5i0kuytr0ia9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045085918%2F58205855907', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
