INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22399374569', 'Kit 2 Colheres de Treinamento Autoalimentação 6m+ Buba', 'Kit 2 Colheres de Treinamento Autoalimentação 6m+ Buba (As cores são sortidas) O Kit Colher de Treinamento da Buba Baby é ideal para estimular a autoalimentação e a coordenação motora do bebê. É só o bebê mergulhar a colher na comidinha e se deliciar. É Super prático e divertido. Contém 2 colheres para dois estágios, conforme descrição abaixo. Estágio 1: Além de massagear a gengiva do bebê, essa colher é ideal para iniciar a autoalimentação com papinhas menos consistentes. Estágio 2: A colher do estágio dois é indicada para alimentos mais consistentes. Composição: - Cabo 100% Polipropileno (PP); Ponta 100% Elastômero Termoplástico (TPE). Livre de BPA e ftalatos. - Produto 100% atóxico. - Idade: Acima de 6 meses Recomendações: Esse produto não pode ser esterilizado. Não pode ser fervido. Não pode ir ao micro-ondas e nem à lava louças.', 17.84, 15.79, NULL, 'Mom & Baby > Feeding Essentials > Utensils', 'https://cf.shopee.com.br/file/sg-11134201-82607-ml5h6tn2nhts99', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045085918%2F22399374569', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21298894323', 'Kit 9 Unidades Hidratante Labial Carmed Fini Dentaduras Efeito Gloss 10g', 'Carmed Fini Dentaduras é um hidratante labial com alto poder de hidratação e evita rachaduras, deixando os lábios macios e saudáveis. É Incolor e possui efeito gloss e aroma de Fini Dentaduras. Sua fórmula conta com manteiga de cacau e não contém parabenos, conservantes e teste em animais. Modo de Uso: Aplique o protetor labial Carmed diariamente sobre os lábios e reaplique sempre que sentir a necessidade de mais hidratação na região. Benefícios: -> Possui alto poder de hidratação e restauração. -> Mantém a umidade natural dos lábios. -> Auxilia no tratamento e na prevenção das rachaduras labiais. -> É incolor e possui efeito gloss. -> Não testado em animais. -> Sem parabenos e conservantes. Advertências: -> Não ingerir. -> Não usar em crianças menores de 3 anos. -> A partir de 3 anos: Deve ser aplicado exclusivamente por adulto. -> Para maiores de 5 anos: Usar sob supervisão de adulto. -> Não usar caso os lábios apresentem rachaduras, escamações ou ferimentos. -> Não deve ser utilizado em pessoas alérgicas aos componentes da fórmula. -> Em caso de irritação, suspender o uso e procurar orientação médica.', 192.09, 111.99, NULL, 'Beauty > Makeup > Lips', 'https://cf.shopee.com.br/file/sg-11134201-7rbk0-ll2qiqays7qp0d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045085918%2F21298894323', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
