INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15124677226', 'Pistola de ar para limpeza bico curto com corpo em alumínio - Stels', 'Produto: Pistola de ar para limpeza bico curto com corpo em alumínio Marca: Stels Descrição: A Pistola de ar para limpeza bico curto com corpo em alumínio da Stels, é uma ferramenta essencial para profissionais que buscam precisão e durabilidade em suas atividades de limpeza. Ideal para a limpeza de máquinas e equipamentos, esta pistola oferece um desempenho superior, graças ao seu design robusto e materiais de alta qualidade. A Pistola da Stels se destaca por seu bico curto, especialmente projetado para soprar pequenos furos e grandes superfícies com um jato eficaz de ar comprimido. Seu corpo em alumínio não apenas confere uma maior durabilidade, como também garante leveza, proporcionando maior conforto e reduzindo a fadiga durante o uso prolongado. Características: • Rosca de entrada de ar: 1/4" NPT, compatível com várias configurações de sistemas de ar comprimido. • Material: Corpo em alumínio, que oferece resistência contra corrosão e impactos. • Design: Bico curto para acesso facilitado em espaços reduzidos. Especificações: Rosca de entrada de ar: 1/4" NPT. Peso: 0.17 Kg', 44.61, 44.61, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-8259d-mr4oeldrmcjqb9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F489001115%2F15124677226', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
