INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19599325238', 'Colchão Casal Molas Maxspring Scotland Pillow Top (138x188x33) - Herval', 'COLCHÃO CASAL MOLAS MAXSPRING HERVAL MAXSPRING SCOTLAND ONE FACE EURO PILLOW 138X188X33 Marca: Herval Linha/Modelo: Molas Maxspring Scotland Dimensões(Cm): Colchão Molas Maxspring Scotland Comprimento(Profundidade): 188 cm Largura: 138 cm Altura: 33 cm Suporte de Peso: - 140 kg Espuma de Estofamento: - Alta Qualidade, AG, D20, D28 Nível de Firmeza do Colchão: - Firme Tipo de Espuma: - Espuma sem CFC Tipo de Mola: - Maxspring Tipo de Colchão: - Molas Benefícios Extras de Colchão: - Ecologicamente Correto, Reforço Polyframe nas bordas, Manta Acrílica Tecido com Tratamento: - Antiácaro e Antifungo Tipo do Bordado do Tecido: - Localizado Características do Tecido: - Malha 3D Tipo de Forração do Revestimento Inferior: - Antiderrapante Tecido da Faixa Lateral: - Malha, Bordado Ultrassom Tipo de Pillow: - Pillow Top Americano Modo de Utilização: - One Side Certificação de Qualidade: - INMETRO, Qualidade Costa Rica Tempo de Garantia: - 12 meses Imagens Meramente Ilustrativas. Não nos responsabilizamos pela montagem/instalação dos produtos. Todas as informações divulgadas são de responsabilidade exclusiva do fabricante/fornecedor. -Verifique com os fabricantes do produto e de seus componentes eventuais limitações à utilização de todos os recursos e funcionalidades - Confira as dimensões do produto e analise se irão passar normalmente por elevadores, portas, escadas e corredores, pois não nos responsabilizamos caso o produto necessite durante a entrega de: Desmontagem, subir escadas ou ser transportado por guincho, cordas para apartamentos. A entrega limita-se ao descarregamento em local que tenha e ofereça total facilidade de acesso normal; - Só fazemos entregas por transportes rodoviários. Não realizamos entregas por transportes fluviais, aéreos e outros diferente de rodoviário. Não realizamos entregas na região norte: Amapá, Amazonas, Pará, Roraima e Acre; - Temos áreas com restrição e dificuldades que os transportadores rodoviários não atendem. Área de difícil acesso, área de risco, área rural, áreas fluviais, estradas não pavimentadas; - Sendo assim, caso seu endereço esteja em área restrita de entrega, a retirada de sua compra deverá ser realizada no CD do transportador ou indicar no momento da compra um endereço entrega fora da área restrita; - Caso realize pedido com entregas em locais de difícil acesso ou áreas com restrição e dificuldades que os transportadores e proprio correios não atendem, a compra sera cancelada pela Costa Rica Colchões, com a devida comunicação e estorno do pagamento ao cliente.', 1775.91, 1687.12, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-825av-mq3sfqedojy83c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1235923910%2F19599325238', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
