INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23497705699', 'Kit p/ Porta Correr Trilho Alumínio 2,50m Natural - Dividido', 'Os kits de instalação para portas de correr suspensas da marca ALFER, é forma mais fácil e barata para se instalar uma porta de correr. Todos os produtos da marca são testados por profissionais para garantir o melhor resultado aos consumidores, visando a facilidade e praticidade para instalação sempre zelando a qualidade final. A ALFER já possui anos de experiência no mercado de ferragens e a ELETTRO é especialista em vendas online, prezando pelo melhor produto e atendimento para você fazer uma compra segura e de alta qualidade. OBS: - Kit NÃO acompanha porta, NÃO acompanha fechadura e nem batente. - Por questões de transporte, o trilho é embalado e enviado dividido. Não se preocupe, eles foram desenvolvidos para que na instalação se encaixam perfeitamente e a porta trabalhe normalmente. Características Gerais do Produto: • Cor: Alumínio Natural • Guia Inferior: Escova 5x7cm • Largura Indicada para Porta: 125cm • Marca: Al-Fer • Material Trilho: Alumínio • Medida Trilho Total: 2,50 metros • Peso Suportado: 60kg • Tipo Trilho: 35x35mm Acompanha o produto: • Trilho Alumínio Dividido • Suporte Emenda • Suportes para Fixar Trilho na Parede • 2 Roldanas • 2 Freios p/ Roldanas • 1 Guia Escova 5x7cm • Parafusos e Buchas para Aplicação • Manual de Instalação Garantia: • 3 meses', 186.9, 186.9, NULL, 'Home & Living > Tools & Home Improvement > Construction Materials', 'https://cf.shopee.com.br/file/sg-11134201-7rdyn-lywbiohf7zje82', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F429425876%2F23497705699', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
