INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23098391539', 'Calcinha Caleçon Laser Termofusionada Bege Zee Rucci', 'A Calcinha Caleçon Laser Termofusionada Bege garante invisibilidade sob a roupa, pois não enrola. Além disso, por não possuir elásticos são extremamente confortáveis. A modelagem caleçon sugere o uso para quem tem quadris mais largos ou quer ainda mais conforto.* Acabamento termofusionado.Destaque: *Este produto é confeccionado com a tecnologia seamless (sem costura). Diferente da confecção tradicional, esta tecnologia produz as peças inteiras em teares. A peça sai praticamente pronta, por isso, descarta a costura para montar diferentes partes das peças, utilizando estas interferências apenas em pequenos acabamentos, proporcionando máximo conforto, maior durabilidade e menos descartes têxteis na produção. Esta tecnologia evita que a peça marque o corpo durante o uso.Composição: 85%POLIAMIDA 15%ELASTANO FORRO: 100%ALGODÃOREF: ZR0208018 C122', 37.75, 37.75, NULL, 'Women Clothes > Lingerie & Underwear > Panties', 'https://cf.shopee.com.br/file/sg-11134201-7repg-m8gj0bfqk693d0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1267962009%2F23098391539', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
