INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22599456125', 'Filtro de Papel 103 Melitta', 'O filtro de papel Melitta 103 é ideal para preparar seu café com o melhor sabor e aroma. Sua tecnologia exclusiva de microfuros garante uma extração perfeita, realçando as nuances da sua bebida preferida. Contém 30 unidades. * Dobre o filtro de papel nas áreas indicadas e coloque-o no suporte para filtro 103 (grande). * Para preparar 20 xícaras de café de 50ml, coloque 4 colheres de sopa bem cheias (equivalente a 80g) de pó no filtro. * Sempre segurando a alça do suporte para filtro, acrescente 1 litro de água, lenta e continuamente.', 5.79, 5.79, NULL, 'Food & Beverages > Beverages > Others', 'https://cf.shopee.com.br/file/sg-11134201-8260a-mj72m3p04mpz81', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555041%2F22599456125', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
