INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250272033', 'Romeu e Julieta | Em Quadrinhos', 'Abela cidade de Verona é o cenário da maior e mais trágica história de amor de todos os tempos: a de Romeu e Julieta. Dois jovens apaixonados, cujas famílias, Montecchio e Capuleto, encontram-se dominadas por um ódio antigo. Juntos, eles vão desafiar o destino, renegando seus nomes, para provar que o amor é mais forte do que o ódio e do que a própria morte.80 páginas17x26 cm', 19.9, 13.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-821dl-mglp79tbbjt47b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F58250272033', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29993789833', 'Kit Escorrega Ball + Cubo Educa Mais | Chocalho + Peças de Encaixar | Brinquedo Educativo +12 Meses INMETRO | QUEEN SHOP', 'Kit Escorrega Ball + Cubo Educa Mais Um kit educativo, colorido e cheio de possibilidades para tornar a brincadeira ainda mais divertida! O Escorrega Ball e o Cubo Educa Mais ajudam a criança a explorar movimentos, cores e formas enquanto desenvolve importantes habilidades de maneira lúdica. No Escorrega Ball, a bolinha percorre as pistas circulares até chegar à base, estimulando a atenção, a percepção visual e a compreensão de causa e efeito. O Cubo Educa Mais possui diferentes aberturas geométricas para encaixar as peças correspondentes, auxiliando no reconhecimento de formas, na coordenação motora e no raciocínio. Benefícios do kit Estimula a coordenação motora; Auxilia no reconhecimento de cores e formas; Desenvolve a percepção visual e espacial; Trabalha a atenção e o raciocínio; Incentiva a curiosidade e a autonomia; Oferece diferentes maneiras de brincar. Conteúdo da embalagem 1 Escorrega Ball; 1 chocalho colorido; 1 Cubo Educa Mais; 6 peças geométricas de encaixar. Produzidos em plástico colorido e resistente, os brinquedos possuem formatos atrativos e peças fáceis de manusear pelas crianças. Uma excelente opção para presentear e proporcionar momentos de diversão, descoberta e aprendizado.', 69.9, 44.79, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/br-11134207-820lf-mqz8bkdo3n5w7e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1007842724%2F29993789833', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14625458183', 'Uma Garota Segundo o Coração de Deus | Elizabeth George', 'O livro Uma Garota Segundo o Coração de Deus, da autora Elizabeth George é um livro que despertará o desejo de ser alguém segundo o coração em toda menina que ler esse livro. No mundo que vivemos é muito fácil seguir padrões de comportamento, principalmente para meninas que ainda não possuem uma mente forte em seus princípios, esse livro ajudará a alinhar o coração, e os princípios, trazendo luz. Um livro dinâmico no qual você conseguirá interagir com a autora. 14X21CM 128 PÁGINAS', 28.9, 28.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/6f009c5db7b762f58f8b523903583e95', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F14625458183', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '24235727112', 'Unidade de estado sólido interna de alta velocidade SATA III de 2.5 "SSD 120 GB/256 GB/240 GB', 'Leia com atenção antes do pagamento. Suporte para compras em lote (contate o Serviço ao Cliente para obter descontos) Características e especificações Tipo: Disco rígido de estado sólido de 2,5 polegadas Aplicação: para desktops, laptops, mini-computadores, máquinas tudo em um e outros computadores comerciais Interface: SATA III (6Gb/s) Dimensão: 2.5" Tamanho: 100mm * 70mm * 7mm Estado do produto: Novo Temperatura de armazenamento: -45 ℃ -85 ℃ Temperatura de funcionamento: 0 ℃-70 ℃ Peso: 41g Esperança de vida: 1 milhão de horas mtbf Antes de usar, clique com o botão direito do mouse "Meu computador - Gestão - Gerenciador de dispositivos - unidade de disco" para encontrar o nosso SSD Capacidade atual 120GB=111GB 128GB=119GB 240GB=223GB 256GB=238GB 480GB=447GB 512GB=476GB Essa é a diferença de cálculo entre o fabricante e o computador. Seu computador mostra 1 GB = 10.737.418.24 bilhões de bytes, enquanto o mercado define 1 GB = 1 bilhão de bytes. Por favor, Google Capacidade SSD Capacidade Real "Compreender O pacote inclui: 1* unidade de estado sólido integrada (embalagem de varejo) 1* Cabo incorporado Garantia de qualidade 1. teste de qualidade será realizado antes do depósito do produto Se você tiver problemas de qualidade após receber o produto, você pode entrar em contato conosco primeiro. 🎉 Quaisquer perguntas e sugestões, são bem-vindos a entrar em contato! ♥ Aproveite as compras ♥', 145.0, 94.25, NULL, 'Computers & Accessories > Data Storage > SSD', 'https://cf.shopee.com.br/file/sg-11134201-8260m-mjxxu6aeb476e8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F993120827%2F24235727112', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8712552783', 'A Vida Cristã no Lar | Jay E. Adams', 'A família está em perigo. Edificar uma família sob bases cristãs, em nossos dias, é um enorme desafio. Lares cristãos estáveis têm se tornado cada vez mais incomuns. Vivemos tempos em que o casamento tem sido redefinido, a disciplina bíblica está sob pesado ataque e os valores familiares estão em cheque. O próprio conceito de família tem sido questionado. Neste livro, somos lembrados pelo experiente ministro e especialista em aconselhamento cristão, Jay E. Adams, que a família é a primeira instituição de Deus e que devemos seguir as orientações das Escrituras para estabelecermos famílias cristãs fortes, unidas e estáveis. Adams oferece nesta obra princípios bíblicos fundamentais sobre a família, além de diversos conselhos muito práticos sobre a dinâmica familiar. Um livro necessário para todo cristão! 213 páginas 16x12cm', 31.9, 29.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/fc241ddeec9a3d5df9552476f371c078', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F8712552783', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
