INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10462026765', 'O Homem que Deus usa - Diversos Autores', 'Preocupados com a nova geração dos que desejam servir ao Senhor e em encorajar os que já pegaram no arado, esta obra visa descortinar os bastidores do treinamento daqueles que tiveram ministérios ungidos e frutíferos. O Homem que Deus Usa é uma coletânea de tesouros espirituais que formam uma impressionante unidade. Sua leitura revela o caminho estreito a ser percorrido por aqueles que desejam conhecer ao Senhor em profundidade e serem usados por Ele, bem como os perigos e dificuldades que serão encontrados. Stephen Kaung, Charles Spurgeon, Watchman Nee, C. A. Coates, T. Austin-Sparks, Hebert L. Roush, A. W. Tozer e um Autor Desconhecido nos encorajarão a trilhar um nível mais alto do chamamento celestial, sob a tutoria do Espírito Santo. Ingressemos, por Sua graça e misericórdia, na escola do Crucificado. Afinal, “… só temos uma vida para viver, e nada poderia ser mais trágico do que chegar ao fim dela sabendo que o caminho que tomamos foi o errado” (Watchman Nee). Páginas: 160 Peso: 0.291 kg Dimensões: 15,5 x 23 cm', 31.9, 30.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/0799464b6f6eecf1a153bab976eb6518', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F10462026765', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
