INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23097480217', 'O Mapa do Tesouro | David Merkh | Editora Hagnos', 'O Mapa do Tesouro | David Merkh Embarque em uma jornada emocionante de descoberta espiritual com "O mapa do tesouro: Lições valiosas de Provérbios para o dia a dia", uma obra inspiradora do renomado autor Dr. David Merkh. Este livro é um guia prático e inspirador que convida os leitores a mergulharem nas profundezas do livro de Provérbios, explorando seu acervo rico em sabedoria para o dia a dia. Partindo da premissa essencial de que a vontade de Deus é uma revelação acessível a todos através das Escrituras, o Pr. David Merkh conduz os leitores a desenterrarem os tesouros escondidos nesse livro inspirado. Com uma abordagem prática, ele oferece orientações valiosas para a vida cotidiana, transformando os ensinamentos bíblicos em aplicativos relevantes para os desafios modernos. "O mapa do tesouro" é um farol orientador para aqueles que anseiam por clareza e direção divina. Fundamentado no poder transformador da Palavra de Deus, este livro oferece uma bússola confiável para toda a família, equipando filhos e pais com as ferramentas necessárias para proteger e desfrutar o inestimável legado da sabedoria divina contido em Provérbios. Prepare-se para embarcar em uma aventura espiritual rumo à descoberta do verdadeiro tesouro que carregaremos por toda a eternidade, inspirado pela promessa de Mateus 6:20: “onde a traça e a ferrugem não destroem, e onde os ladrões não arrombam nem furtam”. Não perca a oportunidade de explorar as lições valiosas de Provérbios e aplicá-las em seu dia a dia, transformando sua vida e guiando seus passos com sabedoria e discernimento divinos. Páginas: 302 Altura: 23 cm Largura: 16 cm Profundidade: 2,0 cm', 41.41, 41.41, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rd5s-luqew4qvvr041a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F23097480217', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23430824638', 'O Caminho de Deus para a Santidade | Horatius Bonar', 'O Caminho de Deus para a Santidade Este livro trata sobre santificação — o processo pelo qual o Espírito Santo conforma a vida de um crente à vontade de Deus. Horatius Bonar (1808-1889) analisa a nova vida no crente, que é o fundamento da santidade. Ele investiga a obra de Cristo por nós e do Espírito em nós e o que isso significa para a nossa santidade. Bonar explica que o caminho da paz, e o caminho da santidade, andam lado a lado. A paz pode ser experimentada em primeiro lugar, mas o Espírito de paz é o Espírito de santidade. Você não pode dizer que tem paz enquanto viver no pecado, assim como não pode dizer que tem santidade se não está conscientemente reconciliado com Deus e seus irmãos em Cristo. Neste livro clássico, Bonar lida com o novo nascimento e a habitação do Espírito, que é aquilo que nos dá força contra o pecado; discorre sobre o poder da cruz, o papel da lei, a influência do mundo e dedica uma seção especial ao capítulo sete de Romanos. Fomos salvos para a santidade e este livro é uma excelente ferramenta para nos encaminhar no caminho de Deus para a santidade. Título: O Caminho de Deus para a Santidade Autor: Horatius Bonar Capa: Capa Brochura Acabamento: Laminação Soft touch Páginas: 159 Miolo: Papel Pólen soft 80g/m² Dimensões: Altura: 21 cm Largura: 14 cm Profundidade: 1 cm Peso: 0,200 kg ISBN: 9786587860244 Editora: Monergismo', 31.15, 31.15, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134201-23030-q1q9lrdoihov05', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F23430824638', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
