INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21007531997', 'A Parábola do Filho Pródigo | John MacArthur', 'A Parábola do Filho PródigoVinte e dois versículos do Evangelho de Lucas guardam um dos maiores tesouros em forma de história a parábola do filho pródigo Repleto de cores sentimentos e detalhes este memorável e poderoso relato estimula a reflexão sobre o alcance e a profundidade da graça de Deus manifestada constantemente em relação ao pecador Com um análise cuidadosa de cada versículo John MacArthur um dos maiores teólogos da atualidade apresenta todos os personagens e as viradas de enredo A partir do ensinamento central da parábola ele depreende lições profundas e um convite para abraçar a fé cristã com honestidade e sem reservas Título A Parábola do Filho Pródigo Autor John MacArthur Páginas 224 Formato 22 x 14 x 1 cm Peso 0 449 kg ISBN 9788578607944 Editora Thomas Nelson', 35.81, 35.81, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/ffa58908b1040a29c5d12b2a7e14285d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F21007531997', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42200786289', 'Permanências e mudanças | Wadislau Martins Gomes e Elizabeth Charles Gomes', 'Permanências e mudanças De maneira admirável, o casal Gomes fundiu uma exposição bíblica da Epístola aos Filipenses, um depoimento autobiográfico, orientações gerais sobre a vida cristã e a voz poética de quem aprendeu a glorificar a Deus pelas flores à frente da casa ou pelas cascas de laranja cristalizadas. A vasta experiência ministerial e a igualmente vasta erudição teológica não são apresentadas aqui na forma de um árido tratado de teologia, mas como uma conversa franca entre pessoas mais experimentadas e jovens ainda confusos quanto ao que esperar da caminhada com Cristo. Este é um livro impregnado pelas Escrituras e repleto de amor ao Senhor e à sua obra, produto de mais de cinquenta anos de ministério no Brasil e no exterior. Desfrutem da rica oportunidade de ouvir estas "Variações sobre o tema da caminhada cristã na Epístola aos Filipenses" com ações de graça. Título: Permanências e mudanças Subtítulo: Variações sobre o tema da caminhada cristã, na Epístola aos Filipenses Autor: Wadislau Martins Gomes e Elizabeth Charles Gomes Acabamento: Brochura | Soft Touch Páginas: 260 Dimensões: Altura: 20,8 cm Largura: 13,8 cm Profundidade: 1,4 cm Peso: 330 g ISBN: 9786587860091 Editora: Monergismo', 37.29, 37.29, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134275-7r98o-m9krizu42989e5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F42200786289', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
