INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298578360', 'Kit Pantene Restauração Shampoo 350ml + Condicionador 175ml + Máscara Capilar Hidratação 270ml', 'O Kit Pantene Restauração Shampoo 350ml + Condicionador 175ml + Máscara Capilar Hidratação 270ml foi desenvolvido para reparar os danos causados por químicas, calor e agressões externas, devolvendo força, brilho e vitalidade aos cabelos. Ideal para fios danificados, quebradiços ou ressecados. Sua fórmula conta com o exclusivo blend de Pro-Vitaminas Pantene, enriquecido com óleo de argan e agentes restauradores, que penetram nos fios para fortalecer, nutrir e reparar áreas fragilizadas, além de formar uma película protetora contra novos danos. Benefícios:Restauração profunda da estrutura capilar.Fortalece os fios e reduz visivelmente a quebra.Fórmula com Pro-Vitaminas e óleo de argan.Máscara nutritiva que hidrata e repara intensamente.Cabelos mais macios, brilhantes e saudáveis.Ideal para cabelos danificados, quimicamente tratados ou com pontas duplas. Modo de usar:Shampoo: Aplique nos cabelos molhados e massageie suavemente o couro cabeludo. Enxágue.Condicionador: Aplique no comprimento e pontas, deixe agir por alguns minutos e enxágue.Máscara Capilar: Aplique a máscara nos fios úmidos, deixe agir por 3 a 5 minutos e enxágue. Sobre a marca: Presente no mercado global há mais de 40 anos, Elseve, marca da L''Oréal Paris, é sinônimo de inovação em tratamento capilar. Seus produtos são desenvolvidos com tecnologia de ponta e ingredientes poderosos para oferecer soluções eficazes para todos os tipos de cabelo. Com linhas icônicas e resultados comprovados, Elseve combina ciência e beleza para revelar o melhor dos seus fios em cada aplicação.', 75.57, 61.58, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-82628-mlqcj2v9ue4kf2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683941545%2F22298578360', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23602007715', 'Guanidina Óleo Semente De Manga Alisa E Relaxa Salon Line 218gr', 'A Guanidina Óleo Semente De Manga Alisa E Relaxa Salon Line 218gr foi desenvolvida com um novo sistema de hidratação que alisa e nutre profundamente os cabelos. Rica em vitaminas A e C, é compatível com Hidróxido de Sódio e Lithium. Relaxa e reduz o volume dos fios; o Óleo de Semente de Manga hidrata, recupera e fortalece a fibra capilar. A versão Regular é indicada para cabelos de espessura média. Produto de uso profissional. Benefícios: - Nutrição; - Hidratação; - Compatível com Hidróxido de Sódio e Lithium. Modo de usar: Aplique conforme as instruções da embalagem. Sobre a marca: A Salon Line, uma das maiores fabricantes de cosméticos do Brasil, acompanha a evolução da mulher brasileira há mais de 15 anos. Toda essa vivência faz da empresa uma profunda conhecedora do universo feminino. A Salon Line está sempre investindo em novas tecnologias e produtos para oferecer o que há de melhor no segmento cosmético mundial. Empresa 100% Nacional, tem como objetivo especializar-se na beleza das mulheres brasileiras, desenvolvendo produtos de alta tecnologia e valorizando todas as belezas.', 49.94, 49.94, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-8259r-mqhx2ub0q3ghb7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683941545%2F23602007715', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
