INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22592190741', 'Disco de Serra para Madeira em Aço Carbono 12 Pol. 305x22,23', 'Loja do Mecânico - O que você precisa, nós temos O Disco de Corte de Serra para Madeira FG7063C FORTG, é um produto utilizado para realizar cortes precisos e eficientes em madeira. Este disco é instalado em uma serra circular, que pode ser manual ou elétrica, e é projetado para cortar a madeira com facilidade e rapidez. É feito de materiais resistentes, como aço carbono, aço inoxidável ou carbeto de tungstênio, para garantir sua durabilidade e eficiência. Além disso, ele possui dentes afiados e espaçados de forma adequada para cortar a madeira sem danificá-la ou causar rebarbas. - Aplicação: :: Madeira - Especificações Técnicas: :: Diâmetro do Disco: 305mm (12") :: Fuso Central: 22,23mm :: Dentes: 60T :: Velocidade Máxima: 5000 rpm :: Material: Aço Carbono - Conteúdo da Embalagem: :: 1 Disco de Corte - Garantia: 6 meses - Código de Barras: 7908591703153 Ref.: FORTGPRO-FG7063C Marca.: FORTGPRO', 82.99, 62.97, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rbk0-lkrf15kc4c3r2e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F902146556%2F22592190741', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17872135338', 'Autoridade Espiritual | Watchman Nee', 'Autoridade Espiritual A maior exigência que DEUS faz ao homem não é carregar a cruz servir ofertar ou negar a si mesmo É a OBEDIÊNCIA O que é autoridade? O que é autoridade espiritual? Como comportar se quando autoridades civis ou mesmo eclesiásticas encontram se em contradição com o que determina a Palavra de Deus? As páginas deste best seller contêm lições bíblicas essenciais que certamente auxiliarão você a enfrentar e superar problemas e crises relacionadas ao importantíssimo tema da obediência Título Autoridade Espiritual Autor Watchman Nee Páginas 222 Formato 21 x 14 x 1 cm Peso 0 400 kg ISBN 9788538300069 Editora Vida', 42.54, 42.54, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/c5f3879ac9b5f751be2b44d083d16755', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F17872135338', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
