INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22895752287', 'Esmerilhadeira Angular A Bateria 21v 8400rpm 800w Com Maleta', 'Esmerilhadeira Angular A Bateria Importway A Esmerilhadeira Angular A Bateria da Importway é ideal para diversos serviços, podendo ser usada de forma segura e confiável. Possui potência de 800W e uma rotação de 8400rpm, além de acompanhar punho lateral para melhor manuseio, protetor e chave de 2 pinos. Especificações: - Marca: Importway - Modelo: IWEAB21 - Tipo: Esmerilhadeira Angular A Bateria - Potência: 800W - Discos: 115mm (4 1/2'') (não acompanha disco) - Acompanha: Punho Auxiliar, Bateria 21V, Carregador Bivolt, Chave De 2 Pinos, Protetor E Maleta - Interruptor Liga/Desliga - Possui Controle De Velocidade Conteúdo da Embalagem: - 01 Esmerilhadeira Angular A Bateria Importway - 01 Punho Lateral - 01 Protetor - 01 Chave 2 Pinos - 01 Bateria 21V - 01 Carregador Bivolt - 01 Maleta - 01 Manual de Instruções "Compra Garantida" - Ao Comprar conosco a sua compra é 100% garantida, o seu dinheiro está seguro até a entrega.', 649.99, 649.99, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/6e3f10d0e0a65420408173adaccc7419', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F286017818%2F22895752287', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
