INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23194224109', 'Mala De Viagem Up4you Katerini', 'A Mala de Viagem Média Expansiva ABS Up4you com Rodas 360 e Cadeado é perfeita para quem busca praticidade, segurança e elegância em viagens de média duração. Produzida em ABS resistente, oferece excelente durabilidade e proteção contra impactos durante o transporte. Seu acabamento sofisticado em tom rosé traz um visual moderno, delicado e elegante para acompanhar diferentes estilos de viagem. O modelo possui sistema expansivo, permitindo ampliar a capacidade interna para acomodar roupas, acessórios e objetos com ainda mais organização e praticidade. Conta com 4 rodas duplas com giro 360°, proporcionando deslocamento leve, silencioso e confortável em aeroportos, hotéis e rodoviárias. A mala possui cadeado integrado com segredo, ideal para garantir mais segurança aos pertences e facilitar viagens internacionais. Seu carrinho embutido com regulagem de altura oferece maior conforto no transporte, além de possuir alça superior e lateral reforçadas, facilitando o manuseio em diferentes posições. O interior é totalmente forrado e organizado, com divisória interna com fechamento em zíper, bolso organizador em tela e cinta elástica com trava para melhor acomodação dos itens durante a viagem. O modelo também conta com detalhes premium, como protetores de canto metalizados, acabamento refinado e rodas personalizadas Up4you. Mala de Viagem Média Expansiva ABS Up4you Modelo: MF10379UP-24 Dimensões: Altura: 68 x Largura: 44 x Comprimento 28 cm Peso: 3,9 kg Capacidade: Média Classificação: Viagem Média Material: ABS Expansiva Rodas Duplas com Giro 360° Cadeado com Segredo Carrinho Embutido com Regulagem Alça Superior e Lateral Forro Interno Personalizado Divisória Interna com Zíper Bolso Organizador Interno Cinta Elástica Organizadora Protetores de Canto Metalizados Logo Up4you em Alto Relevo Rodas Personalizadas Up4you Dicas de uso: ideal para viagens de média duração, férias, passeios e viagens nacionais ou internacionais Dicas de limpeza: limpar com pano úmido e sabão neutro. Evitar produtos abrasivos para preservar o acabamento do material.', 350.1, 350.1, NULL, 'Travel & Luggage > Travel Bags > Others', 'https://cf.shopee.com.br/file/sg-11134201-8257x-mqs5v90xuuq634', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1251967897%2F23194224109', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
