INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57402080915', 'Alquimia dos segredos - Vol 1', 'O novo livro da aclamada autora de Caraval e Era uma vez um coração partido.SE VOCÊ SOUBER ONDE PROCURAR...A MAGIA É REAL.Holland St. James descobre um curso enigmático em uma velha sala de cinema: "Folklore 517: Mitos Locais e Lendas Urbanas". Enquanto a maioria dos alunos considera as histórias da professora pura fantasia, Holland sabe que a magia é real. Determinada, ela rastreia o lendário Homem das Horas, capaz de prever o momento da morte, e recebe uma profecia aterradora: Morrerá à meia-noite seguinte, a menos que encontre o mítico Coração Alquímico. Com o tempo se esvaindo, Holland mergulha nos segredos de uma Los Angeles cheia de mistérios, acompanhada por um estranho misterioso que afirma ter sido enviado por sua irmã para protegê-la. Mas, à medida que seguem pistas e resolvem enigmas relacionados ao Coração Alquímico, Holland percebe que está cercada de mentiras, e que talvez nem mesmo o tal objeto seja capaz de salvá-la.', 57.44, 57.44, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/sg-11134201-8227o-mhhog5j42t4z88', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F57402080915', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '50702232360', '500 Adesivos Homem-Aranha', 'O Homem-Aranha é o amigão da vizinhança que protege Nova York com seus incríveis poderes e coragem. Com seu senso de justiça e bom humor, ele conquista o coração de todos por onde passa. Conheça mais sobre esse super-herói querido neste livro cheio de ação e aventura. Depois, divirta-se resolvendo atividades, pintando e brincando com mais de 500 adesivos!', 21.74, 21.74, NULL, 'Books & Magazines > Books > Hobbies', 'https://cf.shopee.com.br/file/sg-11134201-8225v-mhkpo0bxa5ms30', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F50702232360', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22798678629', 'Conector DC Jack para Notebook Lenovo G400S-80AC000FBR', 'Conector DC Jack compatível com Lenovo G400S-80AC000FBR Este é um DC Jack bringIT compatível com o notebook Lenovo G400S-80AC000FBR. Ele é ideal para acabar com os problemas de alimentação de energia em um notebook. O DC Jack — ou DC Power Jack — é um conector interno responsável por intermediar a alimentação de energia entre a fonte (carregador) e o laptop. Este produto é um de alta qualidade e cumpre todas as especificações de segurança dos notebooks. Para evitar problemas de compatibilidade, compare as fotos deste anúncio com seu equipamento original. Assim você consegue verificar as principais informações de compatibilidade e demais especificações do seu notebook. Atenção: Esse é um dc jack bringIT, portanto não é um produto original da fabricante Lenovo. Caso seja necessário, todo o suporte e garantia do produto serão oferecidos pela nossa equipe. Informações Técnicas Tamanho do Conector: Retangular x Cabo: Com Cabo de 17 cm Garantia: 3 meses de garantia contra defeitos de fabricação Referência: DC063-LE-031', 45.78, 45.78, NULL, 'Computers & Accessories > Desktop & Laptop Components > Power Supply Units', 'https://cf.shopee.com.br/file/sg-11134201-8259z-mqsk8xqz7g2648', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F801641954%2F22798678629', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
