INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49951259785', 'Livro Tabuada - Escreva e apague para aprender', 'Escreva e apague quantas vezes quiser os resultados das tabuadas deste livro colorido e incrível! Com ele, você vai se divertir com os cálculos de multiplicação enquanto desenvolve o raciocínio lógico e treina a coordenação motora e a escrita dos números! Editora: Ciranda Cultural Edição: 1, 2025 Autor: Karoline Cussolim Idioma: Português Páginas: 10 Dimensões: L 20.00 x A 23.00 x E 1.00 ISBN: 9786526119228 Coleção: Escreva e apague para aprender Linha Editorial: Ciranda Cultural - Trade Faixa Etária: + 4 anos Assuntos (tags): Escrita, Atividades, Atividades pedagógicas, Passatempos, Caneta, Matemática, Aprendizado, Diversão, Criança, Infantil, Educação, Multiplicação, Tabuada BISAC: Jogos e Atividades / Jogos e Atividades / Livros de Atividades Linha de Produto: Escreva e apague Encadernação: Lombada quadrada Acabamento: Laminação brilho Material: Cartonado', 24.9, 24.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-821g4-mgzgoaguoaa24d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F49951259785', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58211705564', 'Colchão Gazin de Molas Ensacadas One Face Air Up Queen 158cm', 'Busca um colchão que ofereça conforto e estabilidade? O Air Up com Molas BlueWave, uma tecnologia exclusiva de molas ensacadas da Gazin: se adapta ao corpo ponto a ponto, reduzindo a transferência de movimento e garantindo mais estabilidade para um sono contínuo. Com conforto equilibrado entre maciez e firmeza e suporte de até 120kg por pessoa, ele entrega sustentação ideal sem perder o aconchego, proporcionando noites mais relaxantes e um descanso na medida certa todos os dias. Especificações Técnicas Colchão: - Marca: Gazin; - Exclusivo Lucas Home; - Tipo: Molas BlueWave (Ensacadas); - Tipo de conforto: Perfeito (Equilíbrio entre maciez e firmeza); - Proteções: Antiácaro, Antialérgico, Antifungo, Antimofo; - Tampo: Malha (Conforto Térmico); - Sistema One Face: Tecnologia No Turn(Dispensa a necessidade de girar); - EPS Poliestireno Expansível: Não Possuí; - Peso máximo recomendado: até 120kg (por pessoa); - Garantia: 12 Meses;- Dimensões (larg. x comp. x alt.) 158x198x22cm. Importante, as cores podem variar conforme a tela; Não oferecemos montagem; recomendamos profissionais qualificados. Confira as dimensões para transporte em elevadores e passagens. Não transportamos por meios especiais. Por se tratar de um produto de uso íntimo e pessoal, só aceitaremos devoluções por arrependimento apenas se a embalagem do produto não for violada.', 2226.7, 1236.7, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-823pf-movp75uyhde7ea', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1208859337%2F58211705564', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58252361450', 'Cama Box Conjugada Probel Espuma D28 Ortopédico Unique Active Casal 138cm', 'Você está buscando um colchão de alta durabilidade e suporte confiável? A Conjugada Active Unique da Probel de Espuma D28 é a escolha ideal! Com conforto firme ortopédico e estrutura robusta, ele suporta até 110kg por pessoa, garantindo resistência e estabilidade por muitos anos. Especificações Técnicas Base Box: - Marca: Probel; - Tipo do colchão acoplado: Espuma D28; - Tipo de conforto: Firme (ortopédico); - Material: Madeira tratada; - Peso máximo recomendado: até 110 Kg (por pessoa); - Altura da base: 40cm; - Altura dos pés: 12cm; - Proteções: Antiácaro, Antialérgico, Antifungo, Antimofo; - Revestimento: Poliéster; - Garantia: 3 meses; - Dimensões (larg. x comp. x alt.) 138x188x64cm. Importante: as cores podem variar conforme a tela; não oferecemos montagem; recomendamos profissionais qualificados. Confira as dimensões para transporte em elevadores e passagens. Não transportamos por meios especiais. Por se tratar de um produto de uso íntimo e pessoal, só aceitaremos devoluções por arrependimento apenas se a embalagem do produto não for violada.', 1377.7, 816.7, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/br-11134207-820lt-mlnsd7nou77qb0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1208859337%2F58252361450', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20399757128', 'Tela 15.6" LED para Notebook Dell Vostro 3500 (2010-2020)', 'Tela 15.6" LED para Notebook Dell Vostro 3500 (2010-2020) A tela é compatível com o modelo de notebook, e possui resolução 1366 x 768. Produto aprovado em rigorosos testes de qualidade, atendendo assim todas as exigências do seu aparelho. Possui circuitos de segurança que garantem 100% de proteção ao seu notebook. Importante! Esse produto será compatível com notebook fabricados entre os anos de 2010 à 2020. Atenção! Essa é uma tela bringIT, portanto não é um produto original da fabricante Dell. Caso seja necessário, todo o suporte e garantia do produto serão oferecidos pela nossa equipe. Compatível com o notebook: HB156WX1-100, V3-571-9_BR643, 270E5G-KD1, 5253, E442, HB156WX1-200, ES1-511-C98N, N156B6-L06, B156XTN02.2, LTN156AT24-803 Marca: bringIT Tamanho: 15.6" Resolução: 1366 x 768 Acabamento: Brilhante Tipo de iluminação: LED Tipo de fixação da tela: Sem Fixação Conector: Inferior Esquerdo Quantidade de pinos: 40 Pinos Procedência: Grade A+ Referência: TE038-DE-0022 Produto com Garantia do vendedor: Sim, 12 meses de garantia contra defeitos de fabricação Atenção: Para que essa tela seja compatível com seu notebook, deverá ter o mesmo tamanho, conector e tipo de fixação. Caso possua qualquer dúvida em relação a compatibilidade, estamos a sua disposição por meio do campo de perguntas! Ficou na dúvida da compatibilidade ou precisa de mais informações? Deixe sua pergunta que nosso time técnico especializado está preparado para auxiliar! A bringIT é líder de mercado com o maior mix de produtos e peças para notebook: Baterias, telas, teclados e carregadores compatíveis com notebooks Dell, Lenovo, Acer, HP, Asus e muito mais!', 237.21, 214.67, NULL, 'Computers & Accessories > Desktop & Laptop Components > Others', 'https://cf.shopee.com.br/file/sg-11134201-8258y-mqtwdcfrso3k51', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F801641954%2F20399757128', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23393086029', 'Balcão de Cozinha de Aço Triplo Telasul Mirage New C/ Tampo', 'Balcão de Cozinha de Aço Triplo Telasul Mirage New C/ Tampo Branco/Preto O Balcão triplo Mirage New alia perfeitamente os conceitos de praticidade e estilo. Com um amplo espaço disponível, possui três gavetas equipadas com corrediças metálicas, que abrem e fecham facilmente. A parte interna da gaveta é produzida em plástico, material resistente e durável. Os puxadores e apliques resinados na cor Cobre Fosco dão um ar sofisticado para a peça, que conta ainda com um tampo de MDP. O espaço disponível internamente é perfeito para acomodar panelas e utensílios de maneira organizada. Fabricado em aço, este balcão recebe pintura eletrostática e anticorrosiva, com acabamento brilhoso. O tratamento recebido na pintura garante resistência e durabilidade ao móvel. Leve mais beleza e funcionalidade para a sua casa com o Balcão Mirage New! Medidas do produto: 1200mm (L) X 910mm (A) X 520mm (PROF) Informações técnicas: Peso do móvel: 32,6kg Portas com design harmônico Puxadores e apliques na cor Cobre Fosco Tampo em MDP Pintura eletrostática com preparo antiferrugem Material: Aço Garantia: 12 (doze) meses para defeitos de fabricação Dúvidas Frequentes: O produto é novo? Sim. Todos os produtos de nossa loja são itens novos, devidamente embalados, com garantia de fábrica e respectiva Nota Fiscal. As cores do produto são exatamente como no anúncio? As cores podem variar de acordo com o monitor, a iluminação do ambiente ou sua percepção visual. Quais são as medidas do produto? Todos os nossos anúncios possuem imagens com medidas, além de constar essa informação também nos textos descritivos. Como é calculado o frete? O valor de envio é calculado considerando: peso e volume do produto, e o CEP de destino. Como conservar o produto: - A limpeza deve ser feita com pano macio e seco ou levemente umedecido com água e sabão neutro. Não devem ser utilizados produtos como palha de aço ou qualquer material que arranhe a superfície de seu produto. - Evite guardar substâncias como sal, vinagre, limão, cebola, etc. em contato direto com o móvel. - Recomenda-se forrar as prateleiras com papel ou plástico liso nas áreas de maior atrito Características: - Possui Vidro: Não - Escala de brilho: Brilhante - Material da Estrutura: Aço - Tampo: Não Apresenta Furação/Marcação para Cooktop - Possui Espaço para Pia?: Não - Espaço Para Micro-ondas: Não - Espaço Para Forno: Não - Acompanha Tampo: Sim - Acompanha Pia: Não - Tipo de móveis de cozinha: Balcão - Móvel Suspenso?: Não - Pode Ser Montado Invertido?: Não - Material do Puxador: Poliestireno - Possui Puxadores?: Sim - Peso Suportado nas Prateleiras: 15 Kg - Quantidade de Prateleiras: 1 - Possui Prateleiras?: Sim - Possui Espelho?: Não - Material das Dobradiças: Metálica - Tipo de Porta: Portas de Bater - Espessura da Porta: 0,6 mm - Material da Porta: Aço - Quantidade de Portas: 3 - Possui Portas?: Sim - Tipo da Corrediça: Simples - Material das Corrediças: Metálica - Peso Suportado nas Gavetas (kg): 3 - Quantidade de Gavetas: 3 - Possui Gavetas?: Sim - Espessura da Estrutura: 0,4 mm - Revestimento /Acabamento: Pintura - Recomendação de Manutenção: Utilizar pano levemente umedecido, seguido de pano seco. Não utilizar quaisquer produtos abrasivos. - Observação: Objetos decorativos que aparecem nas imagens, não acompanham o produto. - Indicação de Uso: Cozinha - Como os Móveis Chegarão na Minha Casa: Desmontado em caixas, acompanhado de todas as peças, ferragens e manuais para montagem. - Grau de Dificuldade da Montagem: Médio: pode ser montado por mais de uma pessoa e/ou necessite de maior conhecimento para montagem - Necessita de Montagem: Sim - Sistema de Montagem: Parafusos, cavilhas, minifix e acessórios plásticos. - Garantia (dias): 365', 1069.0, 759.0, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7rd54-lw8qqx4y0pmq92', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1114000786%2F23393086029', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23492490526', 'Livro Fast English', 'APRENDA 100 FRASES SIMPLES PARA INICIAR SUA COMUNICAÇÃO EM INGLÊS. CADA CARTA APRESENTA UMA FRASE PARA VOCÊ LER E RELER, PODENDO UTILIZÁ-LAS PARA O COMEÇO DE CONVERSAS E ORIENTAÇÕES, USANDO EXPRESSÕES SIMPLES E FUNCIONAIS._x000D_ _x000D_ Editora: Principis_x000D_ Edição: 1, 2023_x000D_ Autor: Donaldo Buchweitz_x000D_ Idioma: Português_x000D_ Páginas: 200_x000D_ Dimensões: L 7.00 x A 9.00 x E 2.61_x000D_ ISBN: 9786550970819_x000D_ Coleção: Fast English_x000D_ Linha Editorial: Principis - Educação_x000D_ Faixa Etária: + 9 anos_x000D_ Assuntos (tags): Inglês, Aprendizagem, Aprendizado, Idioma_x000D_ BISAC: Estudo de Língua Estrangeira / Inglês_x000D_ Linha de Produto: Caixa cards_x000D_ Encadernação: Não se aplica_x000D_ Acabamento: Laminação brilho_x000D_ Material: Papel', 29.9, 29.9, NULL, 'Books & Magazines > Books > Careers, Self Help & Personal Development', 'https://cf.shopee.com.br/file/sg-11134201-7rbni-lmdo0pjn5clhbe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F23492490526', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20698093214', 'Condicionador Pantene Pro-V Miracles Queratina 1 Litro', 'O Condicionador Pantene Pro-V Miracles Queratina 1 Litro foi desenvolvido para proporcionar um cuidado intensivo e restaurador aos seus cabelos. Enriquecido com queratina e pro-vitamina B5, penetra profundamente nos fios, fortalecendo e revitalizando desde o interior. Sua fórmula nutre intensamente, proporcionando hidratação profunda e combatendo o ressecamento. Ajuda a restaurar a elasticidade dos cabelos, deixando-os mais macios e com aspecto saudável. Ideal para cabelos danificados e com necessidade de reparação, proporciona resultados visíveis desde a primeira aplicação. Desfrute de cabelos revitalizados, brilhantes e cheios de vida Benefícios:- Fortalece e revitaliza os fios;- Hidratação profunda e nutrição intensa;- Restaura a elasticidade e previne o ressecamento;- Deixa os cabelos macios e saudáveis. Modo de usar: Aplique o condicionador sobre os cabelos úmidos, começando pelas pontas, massageando suavemente os cabelos, deslizando os fios entre os dedos até que estejam perfeitamente desembaraçados. Deixe agir por 1 minuto e enxágue. Sobre a marca: Pantene foi lançada na Europa em 1947, o nome se refere a origem do produto o Panthenol que é o nome cientifico da vitamina B5. A marca possui produtos com características nunca vistas no mercado, pois são fabricados com uma fórmula 7 vezes mais efetiva. Seus produtos possuem tecnologia Pro-V que fortalece e repara o fio evitando a quebra e reduzindo em até 98% a queda, isso em apenas uma semana.', 94.49, 69.99, NULL, 'Beauty > Hair Care > Hair and Scalp Conditioner', 'https://cf.shopee.com.br/file/sg-11134201-824g7-mpi2i1iwcdmz86', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683941545%2F20698093214', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22593671269', 'Livro Capa dura Dinossauros', 'Venha fazer uma viagem incrível pela pela pré-história para conhecer as criaturas que habitaram a Terra há milhões de anos. Surpreenda-se com as ilustrações coloridas e realistas dos dinossauros e levante as abas para descobrir muitas curiosidades sobre cada um desses animais fantásticos._x000D_ _x000D_ Editora: Ciranda Cultural_x000D_ Edição: 1, 2024_x000D_ Autor: Susaeta Ediciones_x000D_ Ilustrador: Miguel Ángel Rodríguez Cerro_x000D_ Idioma: Português_x000D_ Páginas: 40_x000D_ Dimensões: L 33.30 x A 27.20 x E 1.00_x000D_ ISBN: 9786526114957_x000D_ Coleção: Conheça e aprenda_x000D_ Linha Editorial: Ciranda Cultural - Coedição_x000D_ Faixa Etária: + 6 anos_x000D_ Assuntos (tags): Aprendizado, Textos informativos, Dinossauro, Pré-história, Curiosidade_x000D_ BISAC: Não Ficção Infantil / Animais / Dinossauros & Criaturas Pré-Históricas_x000D_ Linha de Produto: Capa dura_x000D_ Encadernação: Capa dura_x000D_ Acabamento: Laminação fosca e verniz localizado_x000D_ Material: Papel', 79.9, 79.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rbn4-m5kdyss7g1gr2e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F22593671269', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57509125805', 'Lovito Calca de Alfaiataria com Pregas Basica Feminina BRPTB1165BRL1195', '✅DESTAQUES -❤️Confortavel - Calca Trabalho ✅DESCRIÇÕES Estampa: Liso Coleção: Ano Todo Tamanho Plus: Não Composição: 100% Poliester Tipo de Modelagem: Calca Pantalona Transparência: Não Elasticidade: Baixa Região de Origem: Brasil ✅O PACOTE INCLUI 1 Calça ✅INTRODUÇÃO À LOVITO A Lovito é uma marca emergente que acredita no poder feminino, comprometida em oferecer opções de roupas elegantes e acessíveis para diferentes estilos, necessidades e identidades. Acreditamos que a moda deve ser divertida, libertadora e fazer você se sentir bem. Afinal, o melhor acessório para qualquer look é a autoconfiança. ✅NOTAS DE COMPRA Compare suas medidas com nossa tabela disponível no site. Lembre-se de que, por serem feitas manualmente, as medidas podem variar de 1 a 2 cm. As cores dos produtos também podem ter pequenas diferenças em relação às fotos, dependendo da iluminação e das configurações do seu dispositivo. Siga nossa loja e conheça novos itens e as melhores ofertas para você!! Se você tiver alguma dúvida, entre em contato conosco e responderemos o mais rápido possível.😊', 93.9, 45.9, NULL, 'Women Clothes > Pants & Leggings > Pants', 'https://cf.shopee.com.br/file/br-11134207-820l7-mnwxsx3e4j5u07', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1632995122%2F57509125805', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46307100658', 'Jogo de Soquetes Catraca Encaixe 1/4 Pol Aço Cromo Vanádio 57 Peças STELS', 'O Jogo de Ferramentas Encaixe 1/4 Pol Cromo Vanádio 57 Peças STELS reúne as ferramentas essenciais em um conjunto versátil, pensado para tarefas de manutenção, montagem e reparos gerais. Com peças em aço cromo vanádio e encaixe padrão 1/4 polegada, oferece resistência e compatibilidade com acessórios comuns do mercado. Ideal tanto para uso doméstico quanto profissional leve, o kit de 57 peças permite atender diversas demandas sem a necessidade de montar conjuntos adicionais, entregando praticidade e eficiência na execução dos serviços. Características: Modelo: 1410155 Referência: 1410155 Tipo: Jogo de Ferramentas Encaixe: 1/4 Pol Material: Cromo Vanádio Peças: 57 Marca: STELS Benefícios: Conjunto versátil que cobre múltiplas aplicações de manutenção e montagem. Peças em cromo vanádio para maior resistência e durabilidade. Encaixe 1/4" compatível com acessórios e extensões padrão. Kit completo de 57 peças reduz a necessidade de ferramentas adicionais. Design pensado para uso doméstico e profissional leve. Conteúdo da embalagem: 1 jogo de ferramentas com 57 peças.', 371.9, 256.65, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-822z5-mo6z0iwm96o04a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F46307100658', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
