INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23798714366', 'VIAGEM AO CENTRO DA TERRA - JULIO VERNE 13,5X21', 'Axel é um jovem órfão que mora em Hamburgo com seu tio Otto Lindenbrock, um renomado cientista da área de Geologia e Mineralogia. Um dia, o cientista encontra um pergaminho escrito em linguagem misteriosa. Ao desvendarem o enigma, tio e sobrinho descobrem algo inacreditável: a possibilidade de chegar ao centra da terra! Com a ajuda de Hans, um intrigante caçador islandês, eles iniciarão a maior aventura de suas vidas e conhecerão cenários deslumbrantes, criaturas fantásticas e perigos de arrepiar. Prepara-se para essa expedição inesquecível!', 24.9, 24.9, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/sg-11134201-7rdwy-mc3xat6tzyyo20', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F303956123%2F23798714366', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
