INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23091800547', 'Máscara de Sobrancelha Castanho Claro Nádia Tambasco By Océane - Brow Definer Light Brown 5ml', 'Nádia Tambasco É Conhecida Por Ser a Maquiadora Das Celebridades. Por Isso Mesmo, Ela Só Cria Produtos Essenciais para Deixar Qualquer Produção Impecável. É o Caso da Brow Definer - Máscara de Sobrancelha Nádia Tambasco By Océane, Um Produto Indispensável para Deixar Suas Sobrancelhas Bem Marcadas e Cheias de Volume, Emoldurando Seu Olhar para Um Efeito Deslumbrante. Em Instantes, Você Acaba de Vez com o Problema de Falha Nas Sobrancelhas. Ela É Perfeito para Delinear e Preencher o Desenho Dos Fios, Deixando-Os Mais Cheios e Encorpados. Uma Sobrancelha Bem Desenhada Levanta o Olhar e Harmoniza o Rosto, Resultando em Uma Maquiagem do Jeito Que Você Sempre Quis. Sua Cor Marrom Clara É Ideal para Sobrancelhas com Fios de Tonalidade Puxada para o Castanho Claro ou Loiro, Proporcionando Aquele Aspecto Natural Que Não Pesa No Seu Visual. A Brow Definer É Ideal para Todos Os Tipos de Maquiagem. Você Pode Usá-La para Aquela Make Básica do Dia a Dia, para o Trabalho ou para Passeios Pela Manhã, Assim Como É Possível Criar Uma Superprodução para a Noite, Onde o Olhar Ganha Destaque. Versátil e Prática, Essa Máscara de Sobrancelhas Deve Estar Sempre com Você. O Produto Tem Alta Duração com Efeito Mate, Além de Ser Resistente à Umidade, Suor e Borrões. Sua Make Vai Durar Muito Tempo sem Retoques. Ele Traz Um Aplicador em Tamanho Mini Desenvolvido para Desenhar e Esfumar Os Fios da Sobrancelha com Precisão. Uma Informação Muito Importante: Brow Definer, Além de Deixar a Sobrancelha Bem Alinhada, Ainda Cuida Dos Fios, Promovendo Hidratação e Deixando-Os Mais Macios. Ela Tem Óleo de Argan e Vitamina EEm Sua Formulação, Ativos Que Impedem o Ressecamento e Queda Dos Pelos. Isso Quer Dizer Que Ele Pode Ser Usado Diariamente em Todos Os Seus Looks. Sobre a Parceria: A Collab Entre Océane e Nádia Tambasco Já Conquistou Corações com Os Produtos Que Revelam o Espírito Inovador Dessa Maquiadora Profissional Que É Considerada a Rainha do Glow! Agora, Esse Portfólio Aumenta Ainda Mais para Que Você Possa Criar Visuais Diversos de Maneira Prática, Mas com Um Toque Especial Que Entrega Sofisticação a Todo Momento. Os Produtos São Desenvolvidos com a Tecnologia Océane, Juntamente com Nossa Embaixadora, para Que Sua Experiência de Uso Seja Sempre de Alta Qualidade e com Aquele Resultado Profissional Que Reflete o Trabalho Maravilhoso da Make-Up Artist Que Assina a Linha.', 79.9, 49.9, NULL, 'Beauty > Makeup > Eyes', 'https://cf.shopee.com.br/file/sg-11134201-8258q-mr22wh3biebwc8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842559166%2F23091800547', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498921601', 'Tapete Higiênico 50x60cm 100 a 200 Unidades My Pad One Super Absorvente e Anti Vazamento', '🐾 Tapete Higiênico My Pad One – A Solução Ideal para o Seu Pet! Quer praticidade, higiene e conforto para o seu pet? O Tapete Higiênico My Pad One é a escolha perfeita para manter sua casa sempre limpa e sem odores! Cada pacote vem com 50 unidades (50x60cm), oferecendo uma área de absorção generosa (40x50cm) que garante proteção contra vazamentos e facilita o adestramento. ✨ Características que fazem a diferença ✅ Tamanho ideal: 50cm x 60cm, com espaço suficiente para seu pet. ✅ Alta absorção: tecnologia que suga líquidos rapidamente, mantendo o ambiente seco. ✅ Mais grosso e resistente: maior retenção e segurança contra poças. ✅ Atrativo canino: incentiva o pet a usar o tapete corretamente. ✅ Controle total de vazamentos: gel superabsorvente + bordas reforçadas. 🌟 Benefícios para você e seu pet 🐶 Facilita o adestramento com rapidez e eficácia. 🏡 Mantém sua casa limpa e livre de odores. 🧹 Prático de usar e descartar. 💰 Economia: maior durabilidade e absorção em cada unidade. ❤️ Bem-estar e conforto garantidos para o seu pet. 🏆 Indicado para: 🐾 Filhotes em fase de treinamento. 🐾 Cães idosos ou doentes com dificuldade de locomoção. 🐾 Pets com necessidades especiais que precisam de cuidados extras. 🐾 Casas com pisos delicados, protegendo contra manchas e umidade. 👉 Garanta já o seu Tapete Higiênico My Pad One e tenha mais conforto para o seu pet e praticidade para o seu dia a dia! 🐕✨', 139.99, 112.88, NULL, 'Pets > Litter & Toilet > Dog Training Pads & Trays', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mergk0ptf477f2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290073877%2F22498921601', NULL, NULL, '2026-07-28T02:11:31.708458+00:00'