INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18599031009', 'Aveia Flocos Finos Integral Sabores do Campo 400 g', 'A Aveia Flocos Finos Sabores do Campo é uma opção saudável e nutritiva para incluir em sua alimentação diária. Feita a partir dos grãos de aveia integral, ela oferece uma textura delicada e um sabor suave. Rica em fibras solúveis, vitaminas e minerais, é ideal para promover a saúde cardiovascular e digestiva. Sua versatilidade permite que seja consumida em mingaus, papas, smoothies, iogurtes, bolos e outras receitas. Com a Aveia em Flocos Finos Sabores do Campo, você cuida do seu corpo de maneira deliciosa e nutritiva. ALÉRGICOS: CONTÉM DERIVADO DE AVEIA E PODE CONTER AMÊNDOA, SOJA, TRIGO, CENTEIO, CEVADA, CASTANHA-DE-CAJU E CASTANHA-DO-PARÁ. CONTÉM GLÚTEN. INTEGRAL, FONTE DE FIBRAS.', 8.89, 8.89, NULL, 'Food & Beverages > Breakfast Cereals & Spread > Cereal, Granola & Oats', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mdug72zr3v09bb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826485187%2F18599031009', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
