INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22697838096', 'Gravador Dvd Cd Externo Usb 2.0 | Preto', 'Gravador e Leitor de DVD e CD externo Este Gravador e Leitor de CD e DVD Externo - CB31005 é excelente em performance e design. É indicado para gravação e reprodução de discos através da interface de conectividade USB 3.0 ou 2.0. Design simples e leve, assim você poderá levar e guardar em qualquer lugar. Com este leitor e gravador, basta conectar ao seu notebook para reproduzir ou gravar DVD’s ou CD’s, seja no trabalho ou em casa. Especificações: Leitor e Gravador de mídias CD e DVD Compatibilidade com interface USB 2.0 e USB 3.0 Compatível com sistemas Windows XP / 2003 / Vista / 7 / 8 / 8.1 / 10, Sistemas Linux e Sistemas Mac Sem necessidade de drivers de instalação (Plug and Play) Medidas do drive: 143mm (C) X 146mm (L) X 20mm (A) Comprimento cabo USB (Não removível): 23 cm Cor: Preto Conteúdo da embalagem: Drive de DVD/RW externo Manual Referência: AC104 Garantia: 12 meses contra defeitos de fabricação', 173.32, 78.95, NULL, 'Computers & Accessories > Data Storage > Hard Drives', 'https://cf.shopee.com.br/file/sg-11134201-825zu-mlplmjtpi9z955', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F801641954%2F22697838096', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
