INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41455093919', 'Boneco Vinil Cadres Gamer Articulado Youtuber 12cm Algazarra', 'Boneco Vinil Cadres Gamer Articulado Youtuber 12cm Algazarra Agora seu pequeno pode levar o universo criativo do Cadres para qualquer lugar com este boneco oficial de 12cm, feito em vinil resistente e com articulações nos braços e na cabeça! Um brinquedo que une diversão, criatividade e o personagem mais querido da internet em uma versão super colecionável e durável. Articulado para mais interatividade com articulações nos braços e na cabeça, o boneco permite movimento e poses, tornando a brincadeira mais dinâmica e divertida. Vinil de alta qualidade produzido em vinil resistente e seguro, com acabamento suave, cores vivas e visual fiel ao personagem. Tamanho ideal: 12 cm compacto, leve e perfeito para mãos pequenas. Ótimo para brincar ou colecionar! Produto original Algazarra Brinquedos marca confiável no mercado infantil, reconhecida por segurança, durabilidade e fidelidade nos detalhes. Presente ideal para fãs do Cadres excelente escolha para aniversários, datas comemorativas ou para surpreender com algo criativo e educativo. Envio rápido com embalagem segura | Produto 100% original.', 49.9, 43.9, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mf1hayocpxxj75', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1314314958%2F41455093919', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
