INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19363896118', 'Massageador Corporal Elétrico 220V R35-220 Acte Sports', 'Massageador Corporal Elétrico R35-220 ACTE O Massageador Corporal Elétrico R35 da ACTE possui um designer moderno e inovador, com uma estrutura leve e alongada, possibilitando maior tempo de massagem sem cansar os braços e as mãos. Ideal para uso doméstico, automassagem ou para uso em clinicas de estética. O produto é acompanhado de 3 pontas massageadoras com diferentes funções que trabalham pontos específicos durante o uso, as pontas podem ter contato com cremes ou óleos de massagem e são laváveis, facilitando a higienização do produto. FICHA TENICA Dimensão: 45,5x7x12cm (CxAxL) Peso do produto: 837g Material: ABS Material das Ponteiras: Silicone Cor: Preto/Branco Voltagem: 220V CONTEUDO DA EMBALAGEM 1 Massageador Corporal Elétrico com 3 ponteiras GARANTIA DO PRODUTO 3 meses (90 dias) CUIDADOS E HIGIENIZAÇÃO Armazene o produto em local limpo e seco. Para higienização utilize um pano seco ou úmido com água. Não utilize solventes, ácidos, ceras, óleo, silicones ou álcool, não mergulhe o produto na água. Somente as pontas podem ser lavadas.', 276.9, 193.9, NULL, 'Health > Personal Care > Massage & Therapy Devices', 'https://cf.shopee.com.br/file/sg-11134201-22110-4rejp1dr16jvb3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F424114018%2F19363896118', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
