INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28629329994', 'Livro Memórias de Martha', 'Vivendo em um cortiço insalubre, cenário comum no contexto de um crescimento urbano desordenado, as duas Marthas, mãe e filha, enfrentam as adversidades de uma sociedade desigual, onde a luta pela sobrevivência é constante. A mãe, carregada pelas cicatrizes de uma vida d e renúncias, tenta proteger a filha, uma jovem cheia de esperanças, das armadilhas do destino. No entanto, os desafios estruturais, como as precárias condições de moradia, a opressão social e a ausência de oportunidades moldam suas trajetórias e as colocam diante de escolhas difíceis._x000D_ _x000D_ Editora: Principis_x000D_ Edição: 1, 2025_x000D_ Autor: _x000D_ Idioma: Português_x000D_ Páginas: 128_x000D_ Dimensões: L 15.50 x A 22.60 x E 0.80_x000D_ ISBN: 9786550971663_x000D_ Coleção: Clássicos da literatura brasileira_x000D_ Linha Editorial: Principis - Clássicos da literatura_x000D_ Faixa Etária: + 14 anos_x000D_ Assuntos (tags): _x000D_ BISAC: Ficção / Literária_x000D_ Linha de Produto: _x000D_ Encadernação: Brochura_x000D_ Acabamento: Laminação brilho_x000D_ Material: Papel', 19.9, 13.93, NULL, 'Books & Magazines > Books > Classic Literature', 'https://cf.shopee.com.br/file/sg-11134201-7rd57-m79izx1g23u89e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F28629329994', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58206078551', 'Rack Mondrian para TV até 55 Polegadas 1,5M 01 Porta 01 Gaveta Caemmun', 'Rack Mondrian para TV até 55 Polegadas 01 Porta 01 Gaveta Caemmun A Rack Mondrian com 1,5 m de comprimento é a peça perfeita para deixar sua sala bonita e agradável, feita para TVs de até 55, fabricada com MDP de alta qualidade para ter uma durabilidade maior e uma beleza a mais, com sua porta de correr micro-ripada para deixar o ambiente mais elegante. Confira mais detalhes! Qualidade e beleza!! A Mondrian foi fabricada com peças de qualidade, como ser feita em MDP de alta qualidade, oferecendo durabilidade e resistência. Tem uma pintura UV para mais detalhes e possui 1 porta de correr micro-ripada. Seus pés tipo cavalete possuem uma base elevada para garantir um visual leve. O revestimento das bordas é feito com fitas de papel ou PVC especiais para garantir que sua estrutura tenha mais qualidade e durabilidade. Sobre a marca: qualidade Caemmun! A Caemmun Movelaria está situada em Arapongas, um dos maiores polos moveleiros do país. A Caemmun iniciou o Grupo Munhoz Caetano, composta por grandes marcas, como a Caemmun, Aroma e a Líder Design. Com uma experiência de mais de 27 anos no mercado moveleiro e preocupada com a preservação dos recursos naturais, surgiu a Caemmun Agropecuária, que consiste em fazendas de Eucalipto e Pinus para a fabricação dos móveis. Características: Marca: Caemmun Modelo: Mondrian Tipo: Rack Ideal para TVs até: 55 Polegadas Quantidade de portas: 1 porta Quantidade de gavetas: 1 gaveta Material da estrutura: MDP e HDF Material das portas: MDP Material das gavetas: MDP Material dos puxadores: MDP Nichos: Sim Pés: Sim Acabamento: Pintura UV Conteúdo da Embalagem: 01 Rack Acessórios para Montagem Manual de Instruções Dimensões: Altura: 61,9 cm Largura: 150 cm Profundidade: 36 cm Peso: 31,6 kg Garantia do Fornecedor: 03 meses contra defeito de fabricação. Detalhes sobre a compra: Fique de olho: siga sempre as orientações do fabricante e utilize seu produto de acordo com o manual. A empresa não se responsabiliza pelo mau uso do produto, o que pode causar perda da garantia.#8239; Não nos encarregamos, no ato da entrega, por montagens e desmontagens, subir escadas/elevadores ou transporte por guincho para apartamentos. Eventuais despesas são de responsabilidade do cliente. O valor divulgado é unitário e a imagem é meramente ilustrativa. Precisou trocar ou devolver? O prazo é de 7 dias a partir do recebimento do produto - Lei número 8.078 - Sempre confira no ato da entrega.', 494.9, 494.9, NULL, 'Home & Living > Furniture > Shelves & Racks', 'https://cf.shopee.com.br/file/sg-11134201-82631-mlc4d5a9g0ld60', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1082747237%2F58206078551', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
