INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23299147803', 'Par Bucha Eixo Traseiro Axios Ka 1.0 1.6 2000 A 2002', 'Este anúncio contém os seguintes produtos: Par de buchas do eixo traseiro. Fabricante das buchas do eixo traseiro: Axios Produtos novos, com 90 dias de garantia. Este produto se aplica a esses veículos: Veiculo: Ka; Motores: 1.0, 1.3; Anos de fabricação: 1997, 1998, 1999; Veiculo: Ka; Motores: 1.0, 1.6; Anos de fabricação: 2000, 2001, 2002; Veiculo: Ka; Motores: 1.0, 1.6; Anos de fabricação: 2002, 2003, 2004, 2005, 2006, 2007; Veiculo: Fiesta; Motores: 1.0, 1.3; Anos de fabricação: 1996, 1997, 1998, 1999; Veiculo: Fiesta; Motores: 1.4; Anos de fabricação: 1996, 1997, 1998, 1999; Veiculo: Escort; Motores: 1.8; Anos de fabricação: 1996, 1997, 1998, 1999, 2000, 2001, 2002; Veiculo: Escort; Motores: 1.8; Anos de fabricação: 2000, 2001, 2002; Somos a Go! Mec Auto Peças, estamos no ramo de autopeças para veículos nacionais e importados há duas décadas, nosso estoque conta com uma variedade de aproximadamente 45.000 itens. Nossa equipe de Pós-Vendas é altamente capacitada, resultando na excelência no atendimento e na busca constante pela satisfação dos clientes. Navegue pela loja virtual e fique à vontade!', 114.0, 114.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/sg-11134201-821f6-mgjtygrpzu2x41', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1397705076%2F23299147803', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43673260939', 'O tribunal dos mortos: Uma aventura de Nico di Angelo - Vol. 2 por Rick Riordan e Mark Oshiro', 'Nesta aguardada continuação do sucesso O sol e a estrela, Nico di Angelo e Will Solace estão de volta e precisam enfrentar um julgamento para provar a inocência de seus amigos Nico di Angelo está se sentindo… entediado. Já se passaram quase três meses desde que ele e seu namorado, o filho de Apolo Will Solace, voltaram para o Acampamento Meio-Sangue após a destemida jornada até as profundezas do Tártaro, e não houve nenhuma missão ou conflito com monstros durante todo esse tempo. Então, quando sua meia-irmã, Hazel Levesque, pede a ele e a Will para se juntarem a ela no Acampamento Júpiter, Nico aproveita a chance de sair e enfim dar uma movimentada nas coisas. Em sua mensagem de Íris, Hazel disse que estava tendo “problemas” com alguns “novos hóspedes” e precisava de ajuda. Só se esqueceu de contar um pequeno detalhe: ela está oferecendo refúgio a um grupo de monstros que escaparam do Mundo Inferior! Aparentemente, os “míticos” — como agora preferem ser chamados — aprenderam com Nico e Will que podem ser muito mais do que apenas monstros violentos. Enquanto Nico e Will tentam dar um jeito na situação, os míticos simplesmente começam a desaparecer. Uma força maligna está em ação, e seu plano é punir as criaturas por seus crimes do passado. E tudo só piora quando Hazel descobre que está intimamente ligada a essa força misteriosa… Nesta nova aventura brilhante e divertida do universo de Percy Jackson, Nico e Will vão até o fim pelo que acreditam, mesmo que isso signifique ir contra tudo e todos.', 69.9, 55.92, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/br-11134275-81z1k-mflky3ojqozraa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1208017249%2F43673260939', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
