INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259826861', 'Conjunto Curto Infantil Menino Marisol', 'O conjunto curto da Marisol é perfeito para meninas que buscam conforto e estilo nos dias mais quentes. Composto por camiseta de manga curta em meia malha, a peça oferece toque macio, leveza e caimento confortável. O bolso decorativo acrescenta um detalhe charmoso e moderno, deixando o visual ainda mais divertido e estiloso. A bermuda, confeccionada em tricot leve, garante liberdade de movimentos e conforto durante o uso. Com elástico no cós e cordão de ajuste, proporciona ajuste seguro e prático, permitindo que a peça se adapte perfeitamente ao corpo. Versátil e cheio de charme, esse conjunto é ideal para passeios, momentos de lazer ou o dia a dia das meninas, unindo praticidade, conforto e a qualidade Marisol.', 139.9, 97.93, NULL, 'Baby & Kids Fashion > Boy Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/sg-11134201-820lw-mnmygtzctuko67', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F980954412%2F58259826861', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
