INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58256883919', 'KIT Bandeja Retangular de Aço Inox Multiuso Servir Alimentos Cozinha', 'A bandeja retangular de aço inox é prática, resistente e ideal para servir ou organizar alimentos no dia a dia. Com design funcional e acabamento em inox, ela oferece durabilidade e um visual moderno que combina facilmente com qualquer ambiente da cozinha. Perfeita para servir frutas, petiscos, frios, queijos, salgados e diversos tipos de alimentos, também pode ser utilizada no preparo de refeições ou para organização de ingredientes. Seu material em aço inoxidável é resistente à corrosão, não absorve odores e facilita a limpeza. Leve e versátil, é uma excelente opção tanto para uso doméstico quanto para restaurantes, buffets, lanchonetes e eventos. VANTAGENS DO PRODUTO: - Material resistente e durável - Aço inox que não enferruja e não absorve odores - Fácil de limpar e higienizar - Formato retangular ideal para servir alimentos - Versátil para cozinha, eventos e organização ESPECIFICAÇÕES DO PRODUTO: - Material: Aço inoxidável - Formato: Retangular - Acabamento: Inox polido - Uso: Servir alimentos e organização de cozinha - Indicações de Uso - Servir frutas - Petiscos e aperitivos - Frios e queijos - Salgados e lanches - Organização de alimentos na cozinha CONTEÚDO DA EMBALAGEM: - 1 Bandeja retangular de aço inox', 44.99, 33.99, NULL, 'Home & Living > Kitchenware > Others', 'https://cf.shopee.com.br/file/br-11134207-820m9-mlrxxjcy248wba', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1333507062%2F58256883919', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19297227249', 'Barbie Kit Infantil Maleta Médica F0011-9 Fun', 'DESCRIÇÃO DO PRODUTO A maleta medica Barbie possui diversos acessórios especiais que fazem a imaginação de ser médica uma brincadeira muito divertida. As meninas vão adorar se transformar em médicas com a Maleta Médica da Barbie da Fun! São diversos acessórios especiais que vão tornar a brincadeira de ser médica um momento criativo, no qual as crianças vão explorar a imaginação de forma ilimitada! CARACTERÍSTICAS TÉCNICAS Conteúdo da Embalagem: Prontuário, Termômetro, Estetoscópio, Martelinho, Otoscópio, Espelhinho, Bisturi, Pinça Dimensões Aproximadas da Embalagem: 7 x 28 x 30 (Altura x Largura x Comprimento/Profundidade) Material/Composição: Plástico Idade Mínima Recomendada: A partir de 3 anos Marca: Fun Referência: F0011-9 Outras informações: As cores podem variar entre as imagens mostradas acima e o produto. Imagens meramente ilustrativas. Aviso: As informações e imagens divulgadas são de total responsabilidade do fabricante/fornecedor. APROVADO PELO INMETRO', 134.96, 118.99, NULL, 'Mom & Baby > Toys > Pretend Play', 'https://cf.shopee.com.br/file/sg-11134201-7qvdu-lj5q7vldkmj1df', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F446413605%2F19297227249', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
