INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58251357109', 'Energético Hudema Energy Drink 473 ml Edição Limitada Lata Black White 2 Opalas', 'A Hudema Energy Drink chega acelerando com a sua Edição Especial de Lançamento, trazendo latas colecionáveis exclusivas inspiradas na trajetória do Opala Carbon na Arrancada Brasileira . São ilustrações únicas, cheias de atitude, estilo e velocidade! São 16 Latas Colecionáveis da Linha Hudema Energy Drink, sendo 8 latas de energético Zero Açúcar e 8 latas de energético Com Açúcar. Compre todas as latas aqui. Desenvolvido com fórmula exclusiva que combina taurina, cafeína e inositol, este energético potencializa seu desempenho físico e mental, ideal para dias de alta exigência e momentos de lazer. Destaques do produto: - Edição Limitada com design exclusivo inspirado no Lendário Opala Carbon de Josimar Hudema da Lista Área 43, maior Campeão de Armagedons da história, para você colecionar e experimentar essa nova emoção. - São 473 ml de energia concentrada para maior disposição durante o dia - Fórmula funcional que melhora o foco, a resistência e revitaliza o corpo - Refrescante, com sabor marcante e equilibrado - Produto aprovado para consumo imediato, pronto para te acompanhar onde precisar Não perca a oportunidade de colecionar e experimentar essa Edição limitada do Hudema Energy Drink, que já está fazendo barulho entre os fãs de carros e bebidas energéticas. Garanta já o seu e sinta o poder da energia que vai além do comum! B2OP', 22.0, 22.0, NULL, 'Food & Beverages > Beverages > Chocolate Drinks', 'https://cf.shopee.com.br/file/sg-11134201-82268-mhrx5yxfwdmr25', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F288347041%2F58251357109', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594373757', 'Cachorrinho Pelúcia Interativo Com Som e Movimento CBS1194 - Castela', 'DESCRIÇÃO DO PRODUTO Leve para casa um amiguinho super fofo e interativo! O Cachorrinho de Pelúcia Castela é macio, divertido e cheio de surpresas: ele emite sons reais de cachorro e ainda se movimenta, deixando a brincadeira muito mais animada e realista. Presente perfeito para crianças que adoram pets e sonham em ter um cachorrinho para brincar e cuidar. CARACTERÍSTICAS TÉCNICAS: Conteúdo da Embalagem: 1 Cachorrinho de Pelúcia Com Som e Movimento Dimensões Aproximadas do Produto: 14,5 cm x 10 cm x 17 cm (Altura x Largura x Comprimento/Profundidade). Dimensões Aproximadas da Embalagem: 11 cm x 20 cm x 24 cm (Altura x Largura x Comprimento/Profundidade). Material/Composição: Pelúcia Idade Mínima Recomendada: A partir de 3 anos Participantes: A partir de 1 ou mais pessoas Alimentação: Requer 2 Pilhas 1,5V AA - Não incluídas Marca: Castela Referência: CBS1194 Outras informações: As cores podem variar entre as imagens mostradas acima e o produto. Imagens meramente ilustrativas. Aviso: As informações e imagens divulgadas são de total responsabilidade do fabricante/fornecedor. Produto lacrado e disponível a pronta entrega para todo Brasil! APROVADO PELO INMETRO', 51.12, 41.99, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/br-11134207-820l9-mqqn84elc2df36', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F446413605%2F23594373757', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
