INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21464855712', 'Kit 2 Sabonete Asepxia Suavizante Ação Reequilibrante 80g', 'SABONETE ASEPXIA SUAVIZANTE Asepxia Sabonete antiacne. Pele mista com tendência a ressecamento. Ação Reequilibrante. Enriquecido com extrato de pepino. Reequilibra a oleosidade da pele. Acalma a vermelhidão. Combate e ajuda a prevenir cravos e espinhas. O novo Asepxia Sabonete Antiacne Suavizante, enriquecido com pepino, limpa os poros e regula a oleosidade, combatendo cravos e espinhas enquanto acalma a vermelhidão e o reequilíbrio da pele. Sabemos que você está sempre mudando, e por isso mudamos com você! Evoluímos toda a linha Asepxia com a nova fórmula avançada Hidro-Force, o equilíbrio perfeito entre tecnologia e natureza. Sua combinação única de ácidos salicílico, glicólico e ingredientes de origem natural combate cravos e espinhas enquanto equilibra a oleosidade da sua pele, deixando-a mais saudável e bonita todos os dias. Fórmula multibenefícios, enriquecida com extrato de pepino e máxima concentração de ácido salicílico, que: Acalma a vermelhidão. Não agride a pele. Reduz o brilho. Limpa sem ressecar. Modo de usar: Aplique com uma leve massagem no rosto úmido, de manhã e à noite, insistindo nas áreas com cravos e espinhas. Enxágue logo em seguida.', 19.98, 19.98, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/sg-11134201-8259t-mqmzglalwetff8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F21464855712', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23297666367', 'Buzina Automotiva Caracol Ford Escort 1987-1996 12v Original Gauss', '🚚 𝗘𝗡𝗩𝗜𝗢 𝗜𝗠𝗘𝗗𝗜𝗔𝗧𝗢 𝗘𝗠 𝗔𝗧𝗘́ 𝟭𝟮𝗛 𝗨́𝗧𝗘𝗜𝗦 Buzina Automotiva Caracol Ford Escort 1987-1996 12v Gauss A principal função da buzina é alertar no trânsito sobre alguma condição adversa sendo utilizada para evitar uma colisão no trânsito, em ocasiões de desatenção de outro motorista.Trata-se de um item obrigatório no veículo, que pode render multa para o motorista, caso não esteja funcionando regularmente. A Buzina Gauss Ford Escort Buzina Caracol combina eficiência com durabilidade, para que você possa ter o melhor desempenho do seu veículo As buzinas da Gauss são rigorosamente testados para que apresentem sempre o melhor resultado. Usando tecnologia de ponta, a Gauss hoje é uma multinacional, com mais de 20 anos do mercado e certificado pelo ISO 9001, que garante excelência de qualidade e atendimento. Compatibilidade com os seguintes veículos: Ford Escort 1987 Ford Escort 1988 Ford Escort 1989 Ford Escort 1990 Ford Escort 1991 Ford Escort 1992 Ford Escort 1993 Ford Escort 1994 Ford Escort 1995 Ford Escort 1996 Especificações Técnicas do Veículo: Veículo: Escort Montadora: Ford Ano: 1987 a 1996 Especificação Técnica - Buzina: Cod Produto: Gb1052 Modelo: Buzina Caracol Voltagem: 12.0 Nivel Sonoro: 110.0 Quantidade De Conectores: 2.0 Quantidade Buzinas: 1.0 Quandidade De Cornetas: 1.0 Origem: Brasil 🚚 Enviamos para todo o Brasil com segurança e rapidez! ✅ Qualquer dúvida estamos à disposição no chat.', 46.99, 46.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/br-11134201-7r98o-m5kpg8ognzphe4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1272573624%2F23297666367', NULL, NULL, '2026-07-28T