INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21998257395', 'Sérum Facial Creamy Skincare PRO-Adapaleno 30g', 'Sérum Facial Pro-Adapaleno O QUE É? O SÉRUM ANTIACNE PRO-ADAPALENO da Creamy é um antiacne a base de adapanelato, um retinoide de terceira geração, e por esta razão apresenta resultados mais rápidos e', 127.99, 127.99, NULL, 'Beauty > Skincare > Acne Treatment', 'https://cf.shopee.com.br/file/sg-11134201-820oc-mo18w51f9c05e2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F21998257395', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44303014502', 'Válvula Termostática LINEA 1.9 16V COM AR 2008 /2010 - 71872 - 336788', 'Válvula Termostática LINEA 1.9 16V COM AR 2008 /2010 1.9 16v - Com Ar - 1 Furo - Kit - Flange + Válvula Termostática - 88º / VALCLEI 336788 A válvula termostática é uma peça importantíssima do sistema de arrefecimento dos carros. Ela controla a temperatura do motor. Quando o motor está frio, ela fica fechada, fazendo com que o líquido de arrefecimento (água e aditivo) volte para o bloco do motor. A partir de uma determinada temperatura, cerca de 90 graus, ela se abre, permitindo a passagem do líquido para o radiador para que ele seja refrigerado e volte para o bloco. A manutenção preventiva a cada 30 mil km ou menos.', 412.19, 412.19, NULL, 'Automobiles > Automobile Spare Parts > Radiators, Engine Cooling & Climate Control', 'https://cf.shopee.com.br/file/sg-11134201-7rauu-maj9gv8ujroz76', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F44303014502', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22393748076', 'Cano Refrigeração PALIO 1997/2000 COM AR - 98142 - VC211', 'Cano Refrigeração PALIO 1997/2000 COM AR VALCLEI VC211 (Weekend) - Motor 1.0/1.5 8v Álcool/Gasolina - (Com ACD/Ar Quente/Desembaçador) (Tubo do Fluxo D''Água do Motor) O Tubo de Refrigeração do motor é um item de suma importância para o sistema de arrefecimento, a sua vida útil está ligada diretamente aos cuidados com a manutenção e troca do fluído (água + anticorrosivo) dentro do período recomendado. Quando não utilizado da maneira correta este tubo libera uma camada corrosiva que circula pelo sistema de arrefecimento danificando todos os componentes ligados ao sistema de arrefecimento.', 42.54, 42.54, NULL, 'Automobiles > Automobile Spare Parts > Radiators, Engine Cooling & Climate Control', 'https://cf.shopee.com.br/file/sg-11134201-7raur-majc4m2ukdxs59', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22393748076', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
