INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23898227053', 'Pijama Manga Longa Algodão Menina Teen Onça - Puket', 'Pijama em meia malha de algodão com estampa exclusiva Onça Fantástica. Para noites tranquilas de sono e momentos de relaxamento em casa. Detalhes: Camiseta com modelagem em manga longa; Camiseta com silk localizado na frente. Calça estampada com elástico macio na cintura; Gola redonda com friso contrastante; O pijama de algodão da Puket proporciona conforto durante a vestibilidade, possui toque macio e ótimo caimento. Tecido: Meia malha de algodão. Cuidados: Lavagem e conservação: Lavagem à mão, não alvejar; não secar em tambor; não Passar; não limpar a seco (mais informações, vide na etiqueta). Garantia: Deverá ser encaminhado dentro da embalagem original; sem indicações de uso; acompanhado de nota fiscal e com todos os Itens constante na solicitação da compra. 100%Algodão |100%Algodão', 159.9, 159.9, NULL, 'Baby & Kids Fashion > Baby Clothes > Sleepwear', 'https://cf.shopee.com.br/file/sg-11134201-7rd6k-m6r550ow60or57', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F805460736%2F23898227053', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22798244035', 'Kit Bico Injetor CELTA 1999/2008 - 97352 - 12112', 'Kit Bico Injetor CELTA 1999/2008 Tem a finalidade de evitar entupimento do bico injetor devido às impurezas e contaminações do combustível. Outra função é vedar a entrada falsa de ar no coletor de admissão evitando vazamentos. Ao fazer a limpeza do bico injetor, devemos trocar o(s) filtro(s) e os anéis, pois eles retêm as impurezas que diminuem o volume de combustível injetado provocando assim, algumas irregularidades como perda de potência, dificuldade na partida e funcionamento irregular do motor.', 46.39, 46.39, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Electrical System', 'https://cf.shopee.com.br/file/sg-11134201-7rd4q-m6u3h5gtuvw232', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22798244035', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22198379988', 'Mangueira Respiro Óleo QUANTUM 1.8 8v AP 1985 - 89016 - 7411', 'Mangueira Respiro Óleo QUANTUM 1.8 8v AP 1985 Cabeçote ao Filtro de Ar 1.6/1.8 8v (Ø:16mm 5/8 ")(Medida:6cm x 13cm)Essa mangueira serve para aliviar a pressão de dentro do cárter pelo vazamento dos gases dos anéis. Isso é normal e chama-se ventilação positiva. Esse gás é reabsorvido junto com o vapor do óleo pelo motor para ser queimado dentro da camara de combustão, por isso ela fica ligada logo na entrada de ar do motor, ou seja, junto do filtro de ar. Isso foi desenvolvido para não poluir o ar com esses gases.', 14.06, 14.06, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rd3x-m7rnh5k8j3k75d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22198379988', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
