INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21299357175', 'Quatree Snacks Bifinhos Sabor Frango 500g Para Cães', 'Descrução: Snack Quatree Bifinho Para Cães Sabor Frango - 500g - Indicado para cães; - Para cães de todas as raças; - Auxilia na higiene bucal; - Equilibra a flora intestinal; - Sabor frango. Snack Quatree Bifinho Para Cães satisfaz o instinto de mastigação do seu cãozinho e higieniza dos dentes. Contém hexametafosfato de sódio para o controle de tártaro e com o seu prebiótico, equilibra a flora intestinal. Quatree Bifinho Para Cães possui um sabor inconfundível de frango faz com que o pet sempre queira mais. O Snack pode ser utilizado como premiação, distração e brincadeira, contribui para diminuição do estresse e proporciona gengivas mais saudáveis. Snack Quatree Bifinho é um petisco de cuidado diário para oferecer com carinho e diversão ao seu cãozinho de todos os portes. Modo de usar Cães de pequeno porte: 2 bifinhos Cães de médio porte: 4 bifinhos Cães de grande porte: 6 bifinhos Composição Carne Mecanicamente Separada (frango), Proteína de Soja, Farinha de Trigo, Farinha Patabilizante de fígado de Frango, Fosfato Bicálcico, Hexametafosfato de sódio (0,03%), Mananoligossacarídeo, Óleo de linhaça, Propileno Glicol, Glicerina Branca bidestilada USP, Sorbato de Potássio, Ácido Eritórbico, Eritorbato de Sódio, Cloreto de Sódio (sal comum), Nitrito de Sódio, Fosfato Trissódico, Corante Alimentício e Aromatizante.', 45.51, 33.13, NULL, 'Pets > Pet Food > Dog Treats', 'https://cf.shopee.com.br/file/sg-11134201-7rdwo-lyqwubdhdrjr73', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1009890604%2F21299357175', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
