INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46708139953', 'Bomba Costal Pulverizador Veneno Agrícola Manual 20 Litros Speedmax Resistente Com Alça', 'Pulverizador Costal Manual TNT Speedmax – 20 Litros O Pulverizador Costal TNT Speedmax é a solução definitiva para o cuidado eficiente de jardins, hortas e propriedades rurais. Desenvolvido para oferecer máxima ergonomia, ele combina a resistência da linha Speedmax com a praticidade necessária para o dia a dia no campo ou em áreas verdes. Com seu sistema de compressão prévia, a aplicação é fluida e exige menos esforço. A estrutura foi projetada para profissionais que buscam um equipamento de alta durabilidade e performance superior. Diferenciais de Ergonomia e Uso: Conforto Prolongado: Trava no gatilho para evitar a fadiga muscular e alças de transporte com ajuste rápido. Corpo Anatômico: Extremamente leve e com formato que se molda perfeitamente às costas do operador. Versatilidade: Compatível com álcool 70% (líquido). Nota: Não recomendável para uso com solventes, ácidos ou tintas. Conteúdo da Embalagem: 01 Pulverizador Costal TNT Speedmax 20 Litros 03 Bicos intercambiáveis: Simples, Duplo e Ducha 01 Manual de Instruções Completo Especificações Técnicas: Capacidade do Reservatório: 20 Litros Marca: Speedmax Sistema de Bombeamento: Compressão prévia suave Segurança: Reservatório com escala de medidas visível Pressão de Trabalho: 2 a 4 Bar Padrão: Fabricado seguindo normas técnicas de segurança e resistência Dimensões: Altura: 51 cm Largura: 36 cm Profundidade: 16 cm', 169.9, 124.9, NULL, 'Home & Living > Gardening > Gardening Tools', 'https://cf.shopee.com.br/file/br-11134207-820lo-mok3duqjd1j9bd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308179417%2F46708139953', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
