INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21599841600', 'Cinta Para Elevação De Cargas 7:1 2.0m 3.0tf Vonder', 'A cinta para elevação de cargas 7:1 CE 320 da Vonder é projetada para oferecer segurança, resistência e praticidade no içamento e movimentação de cargas em ambientes industriais, logísticos e de construção civil. Com comprimento de 2 metros e capacidade de trabalho de até 3 toneladas na posição vertical, ela é ideal para operações que exigem força, estabilidade e manuseio seguro. Fabricada em poliéster de alta resistência, possui olhais reforçados e excelente flexibilidade, o que reduz o esforço do operador e minimiza o risco de danos às cargas. Atende à norma ABNT NBR 15637-1 e conta com fator de segurança 7:1, garantindo desempenho confiável e durabilidade superior mesmo sob uso intenso. Características: Modelo: CE 320 Referência: 8014090203 Material da cinta: Poliéster Cor: Amarela Largura da cinta: 90 mm Comprimento total da cinta: 2,0 m Carga de trabalho posição vertical/direta: 3,0 tf Carga de trabalho posição cesto/paralela: 6,0 tf Carga de trabalho posição cesto/angular até 45º: 4,2 tf Carga de trabalho posição cesto/angular 46° até 60º: 3,0 tf Carga de trabalho posição forca/laço: 2,4 tf Fator de segurança: 7:1 Segue norma(s): ABNT NBR 15637-1 Massa aproximada: 1,194 kg Benefícios: Alta capacidade de carga com fator de segurança 7:1 Olhais reforçados que garantem maior resistência na operação Flexível e fácil de manusear, reduzindo o esforço físico Menor risco de danos às cargas durante a movimentação Conforme norma ABNT, ideal para uso profissional Conteúdo da embalagem: 1 Cinta.', 124.33, 124.33, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rdww-mdc66452nliv5b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F