INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20799300276', 'Placa com 1 Furo 9,5mm Tramontina Liz 4x2 Branca - 57106/002 Placa com 1 Furo 9,5mm Tramontina Liz 4 x 2 Branca - 57106/002', 'A Placa com 1 Furo 9,5 mm 4x2 Tramontina Liz Branca é a escolha certa para organizar fios e cabos elétricos. Com 1 furo de 9,5 milímetros, ela é ideal para levar mais praticidade para os projetos. É produzida em termoplástico com acabamento em brilho na cor branca, característica que não retém poeira e que garante mais qualidade e bom gosto para a peça. Apresenta sistema modular em duas peças: placa e suporte, tendo um ajuste entre ambos que torna o acabamento entre a placa e a parede muito mais perfeito, sem deixar frestas. Possui furo oblongo que facilita a fixação e a regulagem da placa à parede, deixando-a reta. Para um visual ainda mais especial, a fixação não é aparente. Com as placas e os módulos Tramontina você tem muito mais versatilidade e estilo, podendo trocar as cores disponíveis sempre que quiser. Além disso, pode ser fixada em paredes de madeira. É uma placa no modelo 4x2, que acompanha suporte e parafusos para a instalação.', 10.9, 10.9, NULL, 'Home Appliances > Electrical Circuitry & Parts > Electric Sockets & Extension Cords', 'https://cf.shopee.com.br/file/sg-11134201-7rd50-lwzsd05o3gtl3c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F412527932%2F20799300276', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
