INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23697071172', 'Kaiju N.° 8 - 03 - Panini', 'Para salvar Ichikawa, Furuhashi e os outros soldados, Kafka se transforma e inicia uma batalha fervorosa contra o kaiju humanoide, cuja força é esmagadora. Porém, ele é descoberto pelas Forças de Defesa no momento em que ia dar o golpe final e acaba deixando seu inimigo fugir. Ao tentar se afastar do local depois de cumprir seu objetivo, Kafka se depara com o vice-comandante Hoshina!!! Este é o terceiro volume, no qual esse combate chega ao fim!!!', 42.17, 42.17, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-7rbmr-ln3gj9tuy1wh56', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F23697071172', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
