INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21297730540', 'Módulo Amplificador Taramps Hd 3000 Watts Rms', 'MÓDULO AMPLIFICADOR TARAMPS HD 3000 - 3000W RMS DESCRIÇÃO DO PRODUTO: O Módulo Amplificador Taramps HD 3000 é um equipamento de alta performance desenvolvido com tecnologia de ponta, proporcionando excelente qualidade sonora e potência extraordinária em um design compacto. CARACTERÍSTICAS PRINCIPAIS: • Potência nominal: 3000W RMS • Impedância: 1, 2 e 4 Ohms • Sistema de proteção contra curto-circuito e sobrecarga • Ventilação forçada de alta eficiência • Design moderno e compacto ESPECIFICAÇÕES TÉCNICAS: • Potência nominal em 1 Ohms: 3000W RMS • Potência nominal em 2 Ohms: 3000w RMS • Potência nominal em 4 Ohms: 3000w RMS • Resposta de frequência: 10Hz ~ 20KHz • Sensibilidade de entrada: 0.2V • Relação sinal/ruído: >90dB • Tensão de alimentação: 9V ~ 16V • Consumo musical: 150A • Consumo em repouso: 2.5A • Sistema de proteção térmica • Dimensões (A x L x C): 70 x 240 x 240mm • Peso: 2.5kg RECURSOS ADICIONAIS: • Crossover ativo integrado • Filtro subsônico variável (10Hz ~ 50Hz) • Filtro Low Pass variável (50Hz ~ 200Hz) • Boost para graves em 50Hz (0 ~ +10dB) • Sistema Smart Cooler para melhor dissipação térmica APLICAÇÕES RECOMENDADAS: • Ideal para subwoofers de alta potência • Perfeito para sistemas de som automotivo profissional • Compatível com diversos modelos de alto-falantes • Excelente para competições de som CONTEÚDO DA EMBALAGEM: • 1 Módulo Amplificador Taramps HD 3000 1, 2 ou 4 Ohms • 1 Manual do usuário • 1 Certificado de garantia GARANTIA E SUPORTE: • Garantia de 1 ano contra defeitos de fabricação • Suporte técnico especializado • Rede autorizada em todo território nacional DICAS DE INSTALAÇÃO: • Recomenda-se instalação por profissional qualificado • Necessário cabo de alimentação de 1/0 AWG • Fusível recomendado: 150A • Sistema elétrico do veículo deve estar adequado à potência Importante: - Recomendamos que a instalação seja feita por um profissional, e não nos responsabilizamos pelo mau uso do produto.', 699.0, 699.0, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lxmm879y7muu8a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F388765779%2F21297730540', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
