INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58208507251', 'Blusa Manga Curta Bebê Feminina Lilica Ripilica', 'Blusa Lilica Ripilica com Detalhes 3D – Delicadeza em Cada Movimento Uma peça encantadora que combina conforto, estilo e o charme inconfundível da Lilica Ripilica. Esta blusa de manga curta é confeccionada em algodão com elastano, proporcionando um toque macio e ajuste perfeito para acompanhar a rotina das pequenas com leveza. O destaque está nos detalhes encantadores: As mangas franzidas com babado delicado trazem um ar romântico e feminino, enquanto a estampa localizada em 3D da silhueta da Lilica, na região do peito, adiciona um toque divertido e sofisticado. Próximo à barra, outro detalhe apaixonante: O clássico laço da Lilica Ripilica também aparece em estampa 3D, tornando a peça ainda mais especial e única. Ideal para ocasiões como passeios em família, festinhas entre amigas ou até para dar um toque fashion aos looks do dia a dia. Combine com saias rodadas, shorts ou calças para um visual encantador e cheio de personalidade.', 139.0, 83.4, NULL, 'Baby & Kids Fashion > Girl Clothes > Tops', 'https://cf.shopee.com.br/file/sg-11134201-81zvi-mmueg16dxn2872', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F980954412%2F58208507251', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
