INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8467333615', 'Chave de Ignição Fazer 250 2007 A 2010', 'Chave de Ignição A chave de ignição Stärke é produzida com material de alta qualidade e garantia de funcionamento perfeito e maior segurança para a sua moto. Mantém o padrão de fabricação da montadora com as mesmas especificações da peça original. Código Original: 5D1-82501-00 Compatível com: YAMAHA FAZER 250 2007 FAZER 250 2008 FAZER 250 2009 FAZER 250 2010 Conteúdo da Embalagem: 01 Miolo de Ignição 02 Chaves Responsável pela função de alimentação elétrica, a chave de ignição Stärke permite o desligamento ou a partida (ignição) da moto. A chave também tem a função de fazer o travamento (bloqueio) do guidão, impedindo que moto seja movimentada com facilidade sem o uso da chave. Produto elaborado com material de alta qualidade, testado e aprovado dentro das normas de segurança. Instalação: Este produto possuí fácil instalação, não exige que mude a estrutura de sua moto, pois foi confeccionado seguindo as especificações do produto original, para encaixe e funcionamento perfeito. Vantagem: Agora você pode desfrutar de um produto com qualidade do original, para uma melhor reposição em sua moto e com baixo custo. Importante: Recomendamos que a instalação seja feita por profissional especializado e não nos responsabilizamos pelo mau uso do produto.', 109.9, 74.73, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Ignition', 'https://cf.shopee.com.br/file/00f40d201282929827c5b6c7492d5406', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316500472%2F8467333615', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42954852632', 'Kit Personalizável Anacapri Cadarço e Acessórios Azul - Feminino Lançamento', 'Deixe seu look ainda mais criativo e exclusivo! Kit Personalizável Anacapri Cadarço e Acessórios Azul - Feminino Ficha Técnica: Marca: Anacapri Cor: Azul com estampa exclusiva Vichy xadrez Gênero: Feminino Indicação: Customização de calçados, especialmente o Tênis A''25 da Anacapri Detalhes: Acompanha cadarço em tecido estilo lenço e conjunto de pins metálicos em formato de estrelas, smiles, cerejas e flores Descubra o Kit Personalizével Anacapri e transforme o seu tênis A''25 em uma verdadeira expressão do seu estilo. Porque investir: Com um cadarço em tecido estampado no clássico xadrez Vichy e um conjunto exclusivo de pins metálicos em formatos divertidos, você cria um visual único, com muito charme e personalidade. A customização nunca foi tão fácil e estilosa! Conteúdo da embalagem: 1 kit com 1 cadarço em tecido com estampa Vichy e 1 conjunto de pins metálicos (6 pins)', 99.99, 72.99, NULL, 'Women Shoes > Shoe Care & Accessories > Shoe Laces', 'https://cf.shopee.com.br/file/sg-11134201-7rdwz-mc2fcitwv6we65', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1175741090%2F42954852632', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22798461534', 'Mochila Escolar Xeryus 14 Mickey Y 11623 Azul - Infantil', 'Mochila Escolar Xeryus 14 Mickey Y 11623 Azul - Infantil: Estilo e conforto para o dia a dia escolar dos pequenos. Ficha Técnica: Infantil Marca: Xeryus Cor: Azul Tamanho: 14 polegadas e 13 litros Largura: 27cm x Altura: 35 cm x Comprimento: 14cm Material: Poliéster resistente com painel frontal em PVC vincado Compartimento Principal: Amplo, ideal para materiais escolares Bolso Frontal: 1 bolso com zíper tratorado Bolsos Laterais: 2 bolsos de mesh para garrafas ou pequenos itens Puxadores: Zíper com puxadores personalizados Alça de Mão: Nylon com mesh e piping forrado Alças: Acolchoadas e ajustáveis para maior conforto Estampa: Mickey Mouse Conteúdo da embalagem: 1 Mochila Escolar Xeryus 14 Mickey Y 11623 Azul - Infantil Com um design divertido do Mickey e alças acolchoadas, essa mochila proporciona conforto e praticidade para a rotina escolar. Perfeita para organizar os materiais com estilo, é ideal para o dia a dia das crianças.', 179.99, 179.99, NULL, 'Women Bags > Backpacks', 'https://cf.shopee.com.br/file/sg-11134201-7rfgy-m9hnh9alvr81d4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1175741090%2F22798461534', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41377988749', 'Tênis Coca Cola Atlanta Canvas Coke Branco e Preto - Feminino', 'Estilo sem esforço e conforto o dia todo! Tênis Coca Cola Atlanta Canvas Coke Branco e Preto - Feminino Parte superior do formulário Ficha Técnica: Marca: Coca-Cola Cor: Branco e Preto Modelo: Atlanta Canvas Coke Gênero: Feminino Cabedal: Algodão Palmilha: Poliéster Solado: Borracha Fechamento: Cadarço Lingueta: Fina e flexível Indicado: Dia a dia e lazer Detalhes: Puxador traseiro personalizado, costura aparente na lateral com escrita Coca-Cola, biqueira texturizada e listra preta no solado Com visual urbano e personalidade marcante, o Tênis Coca Cola Atlanta Canvas Coke é perfeito para mulheres que não abrem mão de estilo e atitude. Porque investir: Seu cabedal em algodão proporciona leveza e frescor, enquanto o solado de borracha oferece firmeza ao caminhar. A palmilha em poliéster garante o toque de conforto ideal para o dia a dia. Os detalhes como a costura lateral com o nome da marca, puxador personalizado e biqueira texturizada tornam esse modelo único e cheio de autenticidade. Conteúdo da embalagem: 1 par de Tênis Coca Cola Atlanta Canvas Coke Branco e Preto - FemininoParte superior do formulárioParte superior do formulário Parte superior do formulárioParte superior do formulário', 189.99, 170.99, NULL, 'Women Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-8262p-mjfxwnvsju9td2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1175741090%2F41377988749', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48150846295', 'Vestido CLC Colcci Canelado Slim Laranja - Feminino', 'Versatilidade e atitude para brilhar em qualquer momento! Vestido CLC Colcci Canelado Slim Laranja – Feminino Ficha Técnica: Marca: Colcci Cor: Laranja Gênero: Feminino Indicado: Uso diário, looks urbanos, festas e ocasiões especiais Material: Malha canelada de alta elasticidade (93% algodão, 7% elastano) Modelagem: Vestido curto, justa ao corpo com realce da silhueta Decote: Nadador Detalhes: Malha canelada com elasticidade para liberdade de movimento com caimento firme e elegante; detalhe metálico CLC na parte frontal O Vestido CLC Colcci Canelado Slim é a escolha ideal para quem busca aliar conforto ao estilo. Porque investir: Seu tecido com elastano valoriza a silhueta sem restringir movimentos, enquanto o decote nadador adiciona um toque esportivo e moderno. Use com tênis para um look despojado ou aposte nos saltos e acessórios para um visual ousado e marcante. Conteúdo da embalagem: 1 Vestido CLC Colcci Canelado Slim Laranja – Feminino', 239.99, 239.99, NULL, 'Women Clothes > Tops > T-shirts', 'https://cf.shopee.com.br/file/sg-11134201-821g5-mgnxyuozpma21f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1175741090%2F48150846295', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18766249807', 'Conjunto Cama Box c/ Molas Ensacadas New York Queen 158x198x73', 'Dica Importante Gostou do produto, mas o tamanho não se encaixa à sua necessidade? Não tem problema, o Conjunto Cama Box New York está disponível em 5 medidas para que se adapte a qualquer ambiente. Nada melhor do que dormir confortavelmente, seja sozinho ou com seu parceiro, com um amplo espaço e conforto, não é mesmo?! Medidas do Colchão: 96X203x35 cm,138x188x35 cm, 158x198x35 cm, 193x203x35 cm. Medidas Colchão + Box: 96X203x73 cm, 138x188x73 cm, 158x198x73 cm, 193x203x73 cm. Cores do Colchão: Branco; Cores do Box: Branco PU, Cinza, Marrom e Preto. Caso você tenha interesse em visualizar os anúncios de alguma das opções acima, basta efetuar uma busca de acordo com as opções descritas. Introdução ao Produto: Sabe aquela sensação de felicidade e satisfação que você sente quando faz uma boa escolha?! Pois bem, essa é a sensação de comprar um Conjunto Cama New York. Um produto moderno com design elegante, que irá transformar para sempre suas noites de sono :) Feito com os mais nobres materiais em sua composição, ele conta com espuma D40 e molas ensacadas. Por ser mais macio, o colchão de molas ensacadas individualmente traz benefícios e ajuda no alinhamento da coluna. O colchão King House acomoda melhor o contorno do corpo, dispondo de forma correta quadris e ombros, expulsando as dores e problemas de coluna. Não perca mais tempo e garanta já o seu colchão New York! Características: - Espuma D40; - 201 molas por m2 ensacadas individualmente; - Suporta até 120 kg por pessoa. Características do Box: - 100% eucalipto; - Pés com 12 cm de altura; Dimensões: - Altura: 35 cm (colchão) + 26 cm (box) + 12 cm (pés) = 73 cm de altura; - Largura : 158 cm; - Comprimento: 198 cm. Conteúdo da embalagem: - 01 Colchão Queen Size New York Branco; - 02 Box - 012 Pés de PVC - 01 Certificado de garantia. - 01 Manual de montagem. Garantia: 1 ano de garantia nas molas, 1 ano de garantia nas espumas e 3 meses no revestimento. Informações Relevantes: - É imprescindível ter ciência de que é possível que haja divergência de tonalidade nos tecidos devido às variações de configurações de monitores/telas e lotes do fornecedor; - Não nos responsabilizamos pelo transporte por escadas, elevadores, guincho ou içamento deste produto, qualquer despesa é de responsabilidade do cliente; - Verifique as dimensões do produto, certificando-se de que o mesmo possa ser transportado por portas, corredores e elevadores; - Os objetos que decoram a imagem, não acompanham o produto; - Não nos responsabilizamos pela instalação e montagem; - Prestamos assistência somente por defeitos de fabricação. Nosso produto é certificado pelo INMETRO! CERTIFICADO DE CONFORMIDADE NÚMERO: 07424-001-02/2019 OCP: 003', 3035.89, 3035.89, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-7rd52-lwfr8lxcb96f20', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F874507048%2F18766249807', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41230908129', 'Chinelo Kenner Red Pro Marrom - Juvenil', 'O chinelo perfeito para acompanhar todos os momentos! Chinelo Kenner Red Pro Marrom - Juvenil Ficha Técnica: Marca: Kenner Gênero: Juvenil Cor: Marrom com detalhes em creme Indicado: Praia, piscina, lazer e uso diário Cabedal: Gel maleável bicolor Palmilha: Texturizada, ergonômica – na cor marrom com textura de pontos e impermeável Sola: Borracha vulcanizada levemente tratorada Formato: Forma Padrão Amortecimento: Macio Estabilidade: Alta Entressola: EVA na cor baunilha Tecnologias: Conforto imediato com cabedal gel e palmilha texturizada, durabilidade e tração ativa graças ao solado tratorado de borracha vulcanizada Detalhes: Logotipo K da marca em uma das tiras e nome da marca na outra tira Se você procura um chinelo confortável, resistente e cheio de personalidade, esse modelo é a escolha ideal. Porque investir: Com design slim e acabamento moderno, ele entrega praticidade e excelente aderência para qualquer situação. Um modelo versátil que une conforto e durabilidade para acompanhar sua rotina com segurança. Conteúdo da embalagem: 1 par de Chinelo Kenner Red Pro Marrom - Juvenil', 139.99, 78.99, NULL, 'Baby & Kids Fashion > Boy Shoes > Flip Flops', 'https://cf.shopee.com.br/file/sg-11134201-822yt-mo9uxrh7m70saa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1175741090%2F41230908129', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58251969907', 'Spray Impermeabilizante VedaTudo 400ml/235g Dryko', 'Spray impermeabilizante com acabamento emborrachado que penetra nas aberturas para reparos de vazamentos, trincas, e fissuras, estancando a passagem de água rapidamente após a cura. Produto anticorrosivo com resistência a ferrugem e rápida secagem. Aceita pintura e possui ótima resistência U.V. Onde aplicar: Telhas de fibrocimento; Cerâmicas; Concreto; Galvanizadas; Calhas; Rufos e Clarabóias; Reparo em tubulação PVC; Cantos; Juntas e aberturas. Disponível nas cores: Cinza Terracota Transparente Preto Branco Vantagens: Fácil aplicação; Flexível; Excelente resistência a trincas e rachaduras; Rápida secagem estancando vazamento; Aceita pinturas à base de látex ou acrílicas; Resistente a intempéries. Preparação do produto e aplicação: Realizar teste antes de iniciar a aplicação, identificando a pressão e a distância ideal para bom recobrimento. Aplique uma camada fina e aguarde a secagem de 20 a 35 minutos. Após a secagem aplicar as camadas subsequentes até cobrir totalmente os furos ou fissuras da área. Aguardar secagem total por 24 horas. Na reutilização, caso haja entupimento do bico após secagem, remover o bico e realizar limpeza com Thiner antes de reaplicar. A superfície para aplicação deve estar limpa e isenta de pó. Para superfície de PCV, plásticos e similares, recomendamos realizar lixamento prévio.', 25.9, 24.59, NULL, 'Home & Living > Tools & Home Improvement > Construction Materials', 'https://cf.shopee.com.br/file/br-11134207-81z1k-miadbd439u6bc7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F719930213%2F58251969907', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22994858210', 'Eletroventilador Ventoinha C/S ar Renault Kwid 1.0 12V 2017 em Diante - IR68300', 'Especificações Técnicas: Marca: IRB AUTOMOTIVE Cód. da montadora: 214814297R Transmissão: Manual Combustível: Flex Para veículos com ar-condicionado: Sim e não Cód. de similares: 214297 /GM-20163.0 / MQ0847 / GE1183 / BAU-100429 Quantidade de pás: 9 Defletor incluso: Sim Resistência inclusa: Não Potência (W): 65 Medidas: Diâmetro Hélice (mm): 315 Diâmetro Motor (mm): 67 Aplicações: - Renault Kwid 1.0 12V 2017 em diante O Eletroventilador IRB é eficiente por atingir rotação de trabalho com baixo consumo de corrente elétrica, e consequentemente gerando um fluxo de ar necessário para reduzir a temperatura do líquido de arrefecimento que se encontra circulando na parte interna do radiador do veículo. Fabricado para suportar as mais variadas situações de funcionamento sem deixar de lado a confiabilidade, sendo capaz de suportar condições diversas e severas de operação, com altas temperaturas e vibrações. O Eletroventilador IRB opera de forma silenciosa para não interferir no conforto do motorista e dos passageiros durante a condução! IRB é uma marca brasileira que fornece peças automotivas voltada ao segmento de reposição para todo Brasil. Atendendo frotas de veículos nacionais e importados! Não esqueça de verificar a quantidade de pás, diâmetro e encaixe da peça! Na dúvida, verifique a compatibilidade pelo código da peça do seu veículo ou mande mensagem para verificarmos a aplicação do produto para você. Evite erros na compra!', 299.9, 264.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/br-11134207-81ztm-ml3hqbw81tkw21', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1497249598%2F22994858210', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298924782', 'Tênis Disney Casual Stitch Juvenil Original com Nota Fiscal e Garantia', 'Tênis Disney Stitch Juvenil: A Magia da Disney nos Seus Pés! 👟💙 Olha só que irado! 😎 O Tênis Disney Casual Stitch chegou para quem quer um calçado que é a cara do conforto e do estilo. Feito para a garotada que não abre mão de um visual descolado, ele traz toda a fofura do Stitch, o personagem mais querido da Disney! ✨ Perfeito para o dia a dia, para ir à escola 🎒, passear com os amigos 🚶‍♀️ ou curtir a família, este tênis vai ser o seu novo melhor amigo. O desenho do Stitch na lateral dá aquele toque especial e divertido, deixando qualquer look mais legal. 🚀 Além de lindo, ele é fácil de limpar e feito com material resistente para aguentar o corre-corre do dia. Com o cadarço, você ajusta perfeitamente no pé, garantindo que ele fique super firme e confortável. E o solado emborrachado dá mais segurança na hora da diversão. 😉 Detalhes que fazem a diferença: Unissex: Para meninos e meninas. 👫 Produto Oficial Disney: Qualidade e garantia de um produto original. ✅ Super Confortável: Fechamento com cadarço para o melhor ajuste. Estampa do Stitch: O toque de magia que faltava. ✨ Compre sem medo: 💖 Fotos Reais: O que você vê é o que você leva! 📸 Troca Grátis: Se precisar, a gente troca em até 30 dias. 🔄 Devolução Garantida: Seu dinheiro de volta em 7 dias se você não gostar. 💲 Não perca tempo! ⏳ Garanta já o seu Tênis Disney Stitch Juvenil e prepare-se para caminhar com muito mais estilo e diversão.', 174.99, 139.0, NULL, 'Baby & Kids Fashion > Boy Shoes > Sneakers', 'https://cf.shopee.com.br/file/br-11134207-81z1k-meq2lwmallvm06', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F535071110%2F22298924782', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22495067973', 'Garrafa Térmica Lúmina Marrom Café da Tarde 500ml TERMOLAR', 'A garrafa térmica Lúmina é a escolha ideal para quem busca praticidade e elegância no dia a dia. Com 500 ml de capacidade, essa garrafa térmica pequena combina um design sofisticado com alta eficiência térmica, perfeita para manter suas bebidas quentes ou frias por longos períodos. Feita com exterior em inox, a Lúmina não apenas confere resistência, mas também um toque moderno e elegante. A camada protetora de verniz adiciona uma proteção extra, evitando marcas indesejadas e garantindo que sua garrafa esteja sempre impecável. Um dos grandes destaques da garrafa térmica Lúmina é o seu sistema de bombear exclusivo, que possui um jato forte e preciso, além de não pingar! Somando isso a sua fácil higienização, tornando-a ideal tanto para ambientes residenciais quanto corporativos. Além disso, o interior com ampola de vidro proporciona uma conservação térmica diferenciada, mantendo a temperatura das bebidas por mais tempo com a qualidade que só a Termolar oferece. Características Técnicas: Capacidade: 500 mL Exterior em Inox Jato forte e estabilidade ao bombear Interior com Ampola de Vidro Não deixa marcas de dedo Dicas de Uso: Para aumentar o desempenho do seu Garrafa Térmica Inox Termolar, siga estas dicas simples: Para líquidos quentes: Escalde a garrafa previamente por 2 minutos antes de adicionar o líquido. Para bebidas geladas: Resfrie o interior da garrafa com água fria antes de utilizá-la. Com essas práticas, você garante a máxima eficiência térmica do seu Garrafa Térmica Termolar, mantendo suas bebidas na temperatura ideal por mais tempo. Lembre-se de EVITAR: Evite choque térmico: Não coloque bebida gelada e em seguida a bebida quente, e vice-versa. Não beba diretamente e nem use aquecedor elétrico. Evite abrir a tampa em excesso para não ocorrer perdas na conservação. Não coloque sua garrafa no micro-ondas, nem na máquina de lavar louças. Não coloque cubos de gelo nas garrafas com ampolas de vidro e inox nem bebidas gaseificadas. Dicas de Limpeza: Limpeza Interna Ingredientes: Adicione duas colheres de bicarbonato de sódio e água quente dentro da garrafa. Ação: Deixe agir por 12 horas. Enxágue: Retire o conteúdo e enxágue bem a garrafa. Frequência: Repita a lavagem completa uma vez por semana ou após o uso de café e leite. Armazenamento: Guarde a garrafa aberta para evitar odores e proliferação de mofo. Limpeza Externa Material: Utilize um pano úmido e sabão neutro. Instruções Adicionais: Para uma limpeza mais eficaz, siga as orientações da bula que acompanha o produto. Importante! Posição de Uso: Garrafas com bomba devem ser usadas na vertical. Não incline ou deite a garrafa. Produtos Proibidos: Não utilize produtos abrasivos ou de limpeza que contenham cloro, ácidos ou soda cáustica. Especificações do produto: Acabamento: Lisa Capacidade: 500mL Conservação Térmica: 12h Quente / 24h Frio Dimensões de Produto: (A x L x C) cm: 21,5 x 11,3 x 14,5 Isolamento Térmico: Ampola de Vidro Livre de BPA: Sim Material Atóxico: Sim Material Externo: Inox Sistema de Servir: Bomba de pressão.', 112.9, 101.89, NULL, 'Home & Living > Dinnerware > Water Bottles & Accessories', 'https://cf.shopee.com.br/file/br-11134207-820lq-mprwv2m1emtc8c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F719930213%2F22495067973', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23798040910', 'Brinquedo Chocalho Infantil Animal Coala C/ Mordedor e Ventosa Para Bebes - Castela', 'DESCRIÇÃO DO PRODUTO O Chocalho Mordedor com Ventosa Coala é perfeito para o desenvolvimento dos bebês, oferecendo diferentes texturas e sons suaves que estimulam os sentidos. Com formato de coala e uma ventosa para fixação em superfícies, esse chocalho é ideal para aliviar o incômodo da fase de dentição e promover momentos de diversão. Destaques do produto: Função 2 em 1: Chocalho e mordedor, ajudando no alívio das gengivas durante a dentição. Ventosa prática: Pode ser fixado em superfícies lisas para maior estabilidade e higiene. Design seguro e atraente: Em formato de coala, feito com materiais seguros para bebês. Estimula os sentidos: Sons suaves e texturas variadas que auxiliam no desenvolvimento sensorial. Dimensões aproximadas: Compacto e fácil de manusear. Inclui: 1 chocalho mordedor com ventosa em formato de coala. CARACTERÍSTICAS TÉCNICAS: Conteúdo da Embalagem: 1 Mordedor De Coala Dimensões Aproximadas do Produto: 13cm x 7cm x 3cm (Altura x Largura x Comprimento/Profundidade). Dimensões Aproximadas da Embalagem: 23cm x 14cm x 6xm (Altura x Largura x Comprimento/Profundidade). Material/Composição: Silicone Idade Mínima Recomendada: A partir de 1 Meses Participantes: A partir de 1 pessoa Alimentação: Não se aplica Marca: Castela Referência: CBS0352 Outras informações: As cores podem variar entre as imagens mostradas acima e o produto. Imagens meramente ilustrativas. Aviso: As informações e imagens divulgadas são de total responsabilidade do fabricante/fornecedor. Produto lacrado e disponível a pronta entrega para todo Brasil! APROVADO PELO INMETRO', 24.99, 22.0, NULL, 'Mom & Baby > Toys > Baby & Toddler Toys', 'https://cf.shopee.com.br/file/br-11134207-820m4-mq82p68rwooz72', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F446413605%2F23798040910', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21361377256', 'Macacão Bebê Amore Menina Menino Vira Pé com Zíper Estampado Sortido Infantil 100% Algodão', 'COMO FUNCIONA? É bem simples, Amore. Basta selecionar a quantidade de Macacões que deseja e selecionar a opção de Tamanha e opção Menina ou Menino. Lembrando que enviaremos de forma Sortida (São mais de 50 estampas), ou seja, não tem como escolher as estampas. Mas fique tranquila, enviaremos lindas estampas. DESCRIÇÃO Seu bebê merece esse conforto! O Macacão Vira Pé e protetor de Ziper é uma exclusividade da Amore pensada especialmente para os pequenos. São macias e confortáveis, feitas com tecido em Suedine 100% algodão, para tornar o dia do seu amor mais alegre e cheio de estilo. DETALHES • Confeccionados com tecido macio em Suedine 100% Algodão • Vira Pé • Ziper • Protetor de Ziper TAMANHO • RN = Recém Nascido • P = 3 Meses de Idade • M = 6 Meses de Idade • G = 9 Meses de Idade • GG = 12 Meses de Idade Ou em Centímetros. O tamanho em centímetros é entre a gola do macacão e o pezinho. RN - 48cm P - 51cm M - 56cm G - 61cm GG - 66cm ESPECIFICAÇÕES 1 Macacão com Ziper Você vai amar!', 34.9, 29.9, NULL, 'Baby & Kids Fashion > Baby Clothes > Bodysuits & Jumpsuits', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mi3sw42f2vpidc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F435692544%2F21361377256', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23399464108', 'Passa Mangas Tábua de Passar Portátil e Retrátil Estampas Sortidas - Castela', 'DESCRIÇÃO DO PRODUTO Tábuas de passar mangas sortidas estampadas, perfeitas para deixar o momento de passar mangas mais prático e elegante. Produzidas com tecido resistente e estampas delicadas florais e clássicas, proporcionam um toque decorativo ao ambiente enquanto ajudam a proteger a tábua contra desgaste e calor. Possuem ajuste fácil e excelente acabamento, garantindo melhor encaixe e conforto durante o uso. Ideal para quem busca praticidade, beleza e durabilidade no dia a dia. CARACTERÍSTICAS TÉCNICAS: Conteúdo da Embalagem: Tabua de passar manga sortidas. Dimensões Aproximadas do Produto: 9cm x 10cm x 41cm (Altura x Largura x Comprimento/Profundidade). Dimensões Aproximadas da Embalagem: 5cm x 11cm x 42cm (Altura x Largura x Comprimento/Profundidade). Material/Composição: Madeira e Poliéster. Participantes: A partir de 1 pessoa. Alimentação: Não se aplica. Marca: Castela. Referência: CUY0019. Outras informações: As cores podem variar entre as imagens mostradas acima e o produto. Imagens meramente ilustrativas. Aviso: As informações e imagens divulgadas são de total responsabilidade do fabricante/fornecedor. Produto lacrado e disponível a pronta entrega para todo Brasil! APROVADO PELO INMETRO', 51.12, 38.99, NULL, 'Home & Living > Home Care Supplies > Laundry Care', 'https://cf.shopee.com.br/file/br-11134207-820ld-mojuceaqof0j84', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F446413605%2F23399464108', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12595353405', 'Bota Segurança Bracol bico PVC Modelo BAFN (CA 40872) - Marrom Distribuidora Galante', 'Bem-vindo ao anúncio da Distribuidora Galante. Somos uma loja especializada em vendas com ampla variedade de produtos para revendedores, lojistas e empreendedores que desejam obter os melhores preços e qualidade em suas compras. Nossa equipe está sempre comprometida em oferecer um atendimento excepcional e suporte para nossos clientes, garantindo uma experiência de compra satisfatória. Explore nossa loja e aproveite nossas promoções exclusivas para começar a economizar hoje mesmo! Qualquer dúvida referente ao produto deve ser tirada antes de efetuar a compra! Estamos sempre à disposição. TODOS OS PRODUTOS SÃO ORIGINAIS, NOVOS E ACOMPANHAM NOTA FISCAL. ____________________________ ATENÇÃO__________________________ * Pedidos com pagamento confirmado serão despachados em até 24h (válidos para dias úteis - sábado, domingo e feriado não há expediente de postagem). POLÍTICA DE TROCA E DEVOLUÇÃO: TROCA A solicitação de troca do produto defeituoso deverá ser comunicada em até 07 (sete) dias corridos, a contar da data do recebimento do pedido. Recomendamos que você verifique o status do pedido e não clique no recebimento do pedido antes de verificar se todos os produtos estão funcionando corretamente. Se o produto adquirido em nossa loja apresentar defeito após 07 (sete) dias, a contar da data do recebimento ou se você marcou a opção de recebimento do produto, porém está dentro do prazo de garantia do fabricante (01 ano), você deverá entrar em contato diretamente com o fabricante para comunicar a ocorrência e solicitar a troca. DEVOLUÇÃO O comprador poderá efetuar uma solicitação de devolução/reembolso. Recomendamos que você verifique o status do pedido e não clique no recebimento do pedido, verifique a quantidade de itens a ser devolvido, uma vez que a solicitação de devolução é aprovada, o comprador deve devolver o produto em seu estado original dentro do prazo estipulado pela Shopee (favor atentar-se ao prazo de postagem). Bota de segurança com fechamento em cadarço confeccionada em nobuck, com colarinho em camurça acolchoado, forro do cano em sanitec, forro interno da gáspea e solado em poliuretano (PU) bidensidade. Modelo botina de amarrar Atende a todas as Normas de segurança da ABNT NBR ISO 20344, 20345 e 20347 Especificações Técnicas: Marca: Bracol Modelo: BAFN Referência: 4018BAFN1600LL Cor: MARROM COMPOSITE Numeração: 36 ao 44 CA: 40872', 189.9, 179.9, NULL, 'Men Shoes > Boots > Safety Boots', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lpqupfc7niu7e5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F719930213%2F12595353405', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45303241776', 'Sensor Porta e Janela Inteligente Wi-Fi 2.4 GHz ou Zigbee Sobrepor Branco Avant Neo', 'Sensor de Porta e Janela Zigbee Neo Avant Automação Residencial O Sensor de Porta e Janela Zigbee Neo Avant oferece monitoramento preciso e segurança avançada para sua casa. Com protocolo Zigbee, ele otimiza sua rede Wi-Fi, garantindo uma conexão estável e eficiente para integrar entradas de forma inteligente ao seu ecossistema. Características: - Comando de voz com Alexa ou Google Assistente - Controle completo via app Neo Smart (Android e iOS) - Conexão Zigbee - Programar Horários automáticos - Criação de cenas inteligentes - Acabamento Premium branco - Não sobrecarrega Wi-Fi - Instalação articulada prática - Sensor de alta precisão Material: Policarbonato Tamanho do Item: 71x25x20mm | 36x10x17mm Peso do produto: 0.043 kg ESPECIFICAÇÕES TÉCNICAS Alimentação: 2 Pilhas AAA (Não incluso) Comunicação: Zigbee 3.0 Índice de proteção: IP20 Compatibilidade: Tuya e Smartlife Requer hub Zigbee para funcionar Ambientes ideais para utilização: Ideal para portas, janelas, gavetas, cofres e armários residenciais ou comerciais. Dica: Utilize este sensor em cenas inteligentes para criar alertas de segurança ou acender luzes automaticamente ao abrir uma porta. Garantia: Garantia Oficial da Marca de 12 meses para defeitos de fabricação Sobre a Marca: Neo Avant: inovação em cada detalhe para sua automação residencial. Oferecemos soluções completas em iluminação, Interruptores, Tomadas, sensores, câmeras, fechaduras e hubs inteligentes. Tecnologia de ponta e alta qualidade para transformar a sua rotina e valorizar sua casa.', 107.0, 74.9, NULL, 'Home Appliances > Electrical Circuitry & Parts > House Alarms', 'https://cf.shopee.com.br/file/sg-11134201-823r4-mouccvct77rhfe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1297519240%2F45303241776', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23098090883', 'Computador Gamer 2Eletro Chroma, Intel Core i5, 16GB RAM, SSD 512GB, Fonte 500W - PG2E-1003CH', ':::Computador 2Eletro Chroma::: O PC que cabe no seu bolso Os computadores Chroma da 2Eletroforam desenvolvidos para usuários exigentes que querem um produto pronto para o uso. Cada componente e cada detalhe foram pensados para que você se surpreenda com o seu novo PC. Abaixo seguem 3 diferenciais dessa linha exclusiva da 2Eletro: 1- Gabinete Gamer: Com lateral transparente e PSU cover. 2- Fonte Gamer: Com 500W de potência ela está preparada para receber upgrades futuros. 3- Velocidade com SSD: Até 10 vezes mais veloz que os HDs (disco rígidos) tradicionais. Como citado acima, essa é a solução ideal para as suas tarefas do dia a dia. Ele pode ser utilizado para o trabalho e/ou uso corporativo. Além disso, é ideal para o entretenimento, estudos ou jogos casuais. Com um preço justo, este é seu novo parceiro para executar suas demandas diárias. Agora vamos as especificações técnicas para que você tenha 100% de certeza de que este é o seu novo computador: Computador - Marca: 2Eletro - Linha: Chroma - Modelo: PG2E-1002CH Processador - Marca: Intel - Série: Core i5 - Frequência: 3.40Ghz - Núcleos: 4 Placa mãe e gráficos: - Chipset: Intel H Series - Conexões USB: 6, 4 traseiras e 2 frontais - Rede: Gigabit 10/100/1000 - Áudio: Alta definição com 6 canais - PCIe x16: Sim - Interface de vídeo: HDMI e VGA - Frequência: 1100Mhz - DirectX: Sim - OpenGL: Sim - Tecnologia de alta definição: Sim - Tecnologia 3D: Sim Memória RAM - Capacidade: 16GB Armazenamento - Tipo: SSD - Capacidade: 256GB Gabinete Gamer: - Tamanho: Tower - Conexões: 2x Áudio e 2x USB - Lateral: Transparente - PSU Cover: Sim - Refrigeração: Cooler para processador Heat Pipe Fonte Gamer: - Potência: 500W - Fan de refrigeração: Sim - Bivolt: Sim Cooler do processador: - Tipo: Gamer - Tecnologia: Heat Pipe - TDP: Alto - Sistema automático de velocidade: Sim - Resfriamento: Sistema direto de dissipação de calor Sistema operacional - Desenvolvedor: Microsoft - Versão: Windows 10 Pro Trial Garantia - 6 meses Observações: -> Mudanças podem ocorrer no design do produto de acordo com nosso estoque momentâneo, no entanto, em caso de troca sempre enviaremos um item similar com a mesma qualidade. -> Windows na versão trial. -> Produto pronto para receber upgrades através de 2 slots PCIe e entradas SATA adicionais. -> Caso queira melhorar a performance gráfica dos jogos sugerimos a instalação de uma VGA offboard. -> *As configurações gráficas devem ser ajustadas de jogo para jogo de acordo com as definições do desenvolvedor. -> Produzido por BluePC Computadores 2Eletro: Experiência e inovação a sua disposição.', 1575.0, 1575.0, NULL, 'Computers & Accessories > Desktop Computers > Desktop PC', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m40jm0lqm341ed', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F950046979%2F23098090883', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17785602117', 'Cabelo Humano Liso Na Tela 40cm - 300 Gramas Mega Hair', 'Cabelo 100% Humano Castanho Escuro na Tela 40cm 300g Comprimento do cabelo - 40cm Peso: 300g Cor: Castanho Escuro Textura: Liso, levemente ondulado CARACTERÍSTICAS DO PRODUTO: - Cabelo natural 100% Humano e sem misturas - Cabelo especial para alongamentos e apliques - Selecionados, lavados, hidratados, higienizados e esterilizados. - Tingir, descolorir - Produto é pesado com o elástico, pode ter alteração de 5g para mais ou para menos. OBS: Ao fazer qualquer processo químico recomendamos fazer teste de mechas pois não sabemos qual produto você vai utilizar. - *NÃO REALIZAMOS TROCA OU DEVOLUÇÃO, APÓS REALIZAREM QUALQUER PROCEDIMENTO NO CABELO!! Qual a quantidade que devo comprar? 50 gramas é recomendado para manutenção. 100 gramas é recomendado para fazer a manutenção e dar volume. 200 gramas dar pra fazer uma cabeça toda de volume médio. 300 gramas é recomendado para fazer uma cabeça que tenha muito volume. Perguntas Frequentes: É cabelo humano mesmo? Sim é cabelo totalmente humano, não trabalhamos com cabelos misturados. Que garantia tenho? Garantimos a entrega e a qualidade, caso o cliente não goste pode fazer a devolução, é só não alterar o cabelo.', 732.9, 696.26, NULL, 'Fashion Accessories > Hair Accessories > Wigs & Extensions', 'https://cf.shopee.com.br/file/18d8dcd08703ee43a8d918961f6bf8ca', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F375741503%2F17785602117', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22093581534', 'Mesa Dobrável Portatil 120X60cm Mesa de Campismo Camping Praia Acampamento', 'Material de liga de aço atualizado: A mesa de acampamento leve é feita de material de aço atualizado, que é mais leve e mais durável, fácil de limpar, impermeável e resistente a manchas em comparação com os tampos de madeira. O tampo da mesa é fixado por botões aprimorados, o que faz com que as ripas não caiam facilmente. Portátil e prático: O tampo de chapa de aço se enrola e a mesa tem pernas dobráveis com pés antiderrapantes. A bolsa de transporte incluída torna a mesa muito compacta e fácil de guardar e transportar. Design da perna da mesa em forma de X: as pernas da mesa em forma de X e o design antiderrapante das pernas da mesa tornam a mesa de jantar externa, a mesa de churrasco e a mesa de jogos mais estáveis e duráveis quando em uso, adequadas para acampamento, praia, churrasco no quintal, piquenique no pátio e outros cenários. Mova as pernas da mesa quando for movê-la. INSTALAÇÃO E DESMONTAGEM RÁPIDAS: a mesa de camping dobrável pode ser montada em apenas um minuto. Sua resistência e estabilidade excederão suas expectativas. Abra as pernas inferiores da mesa, fixe as duas barras superiores horizontais e, em seguida, deslize o tampo da mesa em uma extremidade das barras superiores e conecte-o à outra extremidade. Por fim, prenda as peças de ferro às pernas para estabilizar a mesa. DICAS QUENTES: Estamos sempre empenhados em oferecer aos nossos clientes os melhores produtos e a melhor experiência de compra. Se houver alguma insatisfação com a mesa de camping multifuncional, não hesite em entrar em contato conosco. Garantia do vendedor: 90 dias', 399.0, 159.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Camping & Hiking', 'https://cf.shopee.com.br/file/br-11134207-820l6-mqqzq8sfhreqe1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1063922972%2F22093581534', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22097440264', 'Limpa Tela Rodabrill Elimina 99,99% das Bactérias', 'Você já desinfetou a tela do seu celular? E a maquininha de cartões do delivery? De acordo com alguns estudos, a tela do seu celular ou do seu tablet só perde para a sola do seu sapato em volume de bactérias e micróbios. Limpa Telas Rodabrill limpa todas as superfícies de cristal líquido removendo marcas de dedo, poeira e gordura, além de eliminar 99,999% dos germes e bactérias acumulados. Pode ser aplicado em tablets, TV''s (exceto Plasma), GPS, celulares, notebooks, câmeras digitais, máquinas de cartões e monitores em geral. Pode ser utilizado em todos os tipos de superfície incluindo acabamento black piano, capas de borracha e silicone. Produto 100% igual da foto', 29.9, 29.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-ltlcy9x7ogzj6d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F885912594%2F22097440264', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22494466853', 'Suporte Para Monitor SIM-400 Aquário 14 A 32 Com Base Fixa', 'Suporte Para Monitor SIM-400 Aquário 14 A 32 Com Base Fixa O suporte para monitor com base fixa é projetado para oferecer conforto, praticidade e segurança no uso diário. Possui recursos ergonômicos de inclinação e rotação que permitem ajustar o monitor conforme suas preferências, garantindo o ângulo de visão ideal para maior produtividade. Sua base fixa assegura estabilidade durante o uso e pode ser removida, acompanhando um adaptador que possibilita a instalação direta na mesa por meio de furação. Com capacidade de carga de até 10 kg, o suporte é compatível com monitores de 14” a 32” e segue os padrões VESA 75x75 mm e 100x100 mm, proporcionando ampla compatibilidade. A instalação é prática e rápida, tornando-o uma solução versátil para diferentes ambientes de trabalho. Características: Tipo de suporte: Base fixa (removível, com adaptador para furação na mesa) Ajustes ergonômicos: Inclinação e rotação Capacidade de carga: Até 10 kg Tamanho de telas compatíveis: 14” a 32” Compatibilidade VESA: 75x75 mm e 100x100 mm Instalação: Rápida e simples Estabilidade: Base firme e segura Dimensões Dimensões: 440x295x80mm Peso: 3,1Kg Imagens Ilustrativas Garantia 01 Meses', 150.5, 135.45, NULL, 'Computers & Accessories > Peripherals & Accessories > Laptop Stands & Foldable Laptop Desks', 'https://cf.shopee.com.br/file/sg-11134201-824je-mfblsnzi6tcf9e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1006271683%2F22494466853', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20296883958', 'Protetor Motor Mata Cachorro Barra Dupla Varias Motos Oferta', 'O Protetor de Motor Barra Dupla Pro Tork é fabricado em matéria-prima de alta qualidade, garantindo mais resistência e segurança. Protege a moto em caso de quedas, e também o condutor em pequenas colisões frontais. Especificações: - Modelo: Barra Dupla; - Marca: Pro Tork; - Fabricado em aço; - Perfeito ajuste na moto, não necessita de adaptação. Aplicação: - YBR 125 2000; - YBR 125 2001; - YBR 125 2002; - YBR 125 2003; - YBR 125 2004; - YBR 125 2005; - YBR 125 2006; - YBR 125 2007; - YBR 125 2008. Instalação: - Antes de finalizar a compra, certifique-se de que sua moto seja compatível com algum dos modelos acima. Pois o produto é pronto para instalação e não necessita de nenhum tipo de adaptação; - Para realizar a instalação, leve sua moto à uma oficina especializada; - A Sportbay não se responsabiliza pela má instalação do produto. OBS: - Pode haver diferença de tonalidade entre a imagem e o produto real por conta do tratamento de imagens e a calibração de cores da tela de seu monitor ou aparelho. Sportbay - Seu Esporte, Nossa Paixão.', 105.16, 89.9, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Others', 'https://cf.shopee.com.br/file/br-11134201-820lz-mqxhbv6byi9yd0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F20296883958', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22527645422', 'Capacete Motocross Trilha Off Road Pro Tork Fast 788 Solid Feminino Masculino Novo Lançamento', 'O Capacete Pro Tork Fast 788 Solid é o capacete Off Road que garante ao piloto a maior qualidade, conforto e segurança do mercado. O projeto para o desenvolvimento do capacete Fast começou com a necessidade de implantar no mercado um capacete de baixo custo com características inovadoras. O capacete Fast não é só estiloso por fora, seu diferencial está em sua forração, quando o capacete é colocado proporciona 12mm a mais na parte superior e 15mm a mais na parte traseira do forro, desta meneira o capacete conta com um encaixe perfeito na cabeça. Características: - Fabricado em ABS; - Pala com regulagem de altura; - Sistema de ventilação; - Nova forração em Lycra; - Forro antialérgico, removível e lavável; - Acabamentos emborrachados; - Grafismo em transfer envernizado; - Cinta jugular em nylon com fechamento em duas argolas; - Tamanhos disponíveis: 56, 58, 60 e 62; - Capacete devidamente Homologado pelo INMETRO; - Marca: Pro Tork. Importante: - É importante escolher um capacete bem justo, pois a tendência é que ele se alargue com o uso. Portanto, se a sua medida é 56 ou 57 cm, escolha um 56 sem medo.', 284.1, 239.9, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Helmets', 'https://cf.shopee.com.br/file/br-11134201-23020-r55ofidiw2nve1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F22527645422', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10356854990', 'Peça de Moto Paralama Dianteiro Honda CG / Titan / Today 125 1983 a 2000 Pro Tork', 'As carenagens e peças plásticas Pro Tork são produzidas nos moldes das peças originais da moto, descartando qualquer tipo de adaptação. Fabricado em ABS 100% virgem, as carenagens Pro Tork são extremamente resistentes aos raios UV. Características: - Marca: Pro Tork; - Moto compatível: - CG 125 1983 a 1999 - Today 125 1990 a 1994 - Titan 125 1995 a 2000. Aplicação: - Honda CG 125: - Azul: 1983 e 1984; - Azul: 1985; - Azul: 1986 e 1987; - Branco: 1983, 1984 e 1985; - Branco: 1986; - Branco Cargo: 1987 e 1988; - Prata: 1989 e 1990; - Preto: 1983 Á 1999; - Vermelho: 1987, 1988 e 1989; - Vermelho: 1983, 1984 e 1985; - Vermelho: 1986. - Honda Today 125: - Azul: 1991 e 1992; - Azul: 1993 e 1994; - Prata: 1990; - Vermelho: 1991 e 1992; - Vermelho: 1990. - Honda Titan 125: - Azul Abrolhos: 1998 e 1999; - Azul Atessa: 1995; - Azul Enseada: 1996 e 1997; - Azul Metálico: 1998 e 1999; - Azul Metálico: 1999 (Modelo 2000) - Branco Cargo: 1995, 1996 e 1997; - Cinza Metálico:1995; - Grafite: 1996 e 1997; - Verde Metálico: 1999 (Modelo 2000); - Verde Salvador: 1997 e 1998; - Vermelho: 1995, 1996 e 1997; - Vermelho: 1998 e 1999; - Vermelho: 1995, 1996, 1997, 1998 e 1999; - Vermelho Ipiranga: 1999 (Modelo 2000). Instalação: - Antes de finalizar a compra, certifique-se de que sua moto seja compatível com algum dos modelos acima. Pois o produto é pronto para instalação e não necessita de nenhum tipo de adaptação; - Para realizar a instalação, leve sua moto à uma oficina especializada; - A Sportbay não se responsabiliza pela má instalação do produto. OBS: - Pode haver diferença de tonalidade entre a imagem e o produto real por conta do tratamento de imagens e a calibração de cores da tela de seu monitor ou aparelho. Sportbay - Seu Esporte, Nossa Paixão.', 136.74, 49.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/br-11134207-7qukw-lin05bodst9x64', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F10356854990', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22398809734', 'Jogo De Bits/Ponteiras Com 58 Peças Encaixe 1/4 Vonder', 'O jogo de bits/ponteiras com 58 peças encaixe sextavado 1/4" Vonder é ideal para profissionais e hobbistas que buscam praticidade e versatilidade na hora de apertar ou soltar parafusos. Acompanha estojo plástico organizado, facilitando o transporte e o armazenamento das peças. Produzido em aço cromo vanádio de alta resistência, garante maior durabilidade e desempenho, além de possuir acabamento fosfatizado que aumenta a proteção contra corrosão e oxidação. Conta com cabo adaptador anatômico com catraca reversível e encaixe magnético, proporcionando mais agilidade e conforto durante o uso. Características: Modelo: Jogo de bits/ponteiras com 58 peças encaixe sextavado 1/4" Referência: 3538580000 Acabamento do bits: Fosfatizado Material do bits/ponteira: Aço cromo vanádio Tipo do encaixe do bits: Sextavado - 1/4" (6,35 mm) Comprimento total do bits/ponteira: 25 mm / 30 mm Benefícios: Alta resistência e durabilidade Proteção extra contra oxidação e corrosão Estojo plástico para melhor organização Cabo anatômico com catraca reversível Encaixe magnético para mais praticidade Conteúdo da embalagem: 1 Jogo de bits/ponteiras, composto por um estojo plástico com 58 peças, sendo: 9 fenda (3 mm (1 peça), 4 mm (2 peças), 5 mm (3 peças) 6 mm (2 peças) e 7 mm (1 peça)), 10 phillips (n° 0 (1 peça), n° 1 (3 peças), n° 2, (4 peças) e n° 3 (2 peças)), 7 pozidrive (n°0 (1 peça), n° 1 (2 peças) n° 2 (2 peças) e n° 3 (2 peças)), 9 hexalobular (T10 (1 peça), T15 (2 peças), T20 (2 peças), T25 (1 peça), T27 (1 peça), T30 (1 peça) e T40 (1 peça)), 7 allen (2 mm, 2,5 mm, 3 mm, 4 mm, 5 mm, 5,5 mm e 6 mm), 14 soquetes sextavados internos, comprimento 38 mm (5 mm, 6 mm, 7 mm, 8 mm, 9 mm, 10 mm, 11 mm e 3/16", 1/4", 9/32", 11/32", 5/16", 3/8" e 7/16"), 1 extensão flexível e cabo adaptador anatômico em polipropileno revestido com borracha termoplástica com catraca reversível e encaixe magnético', 114.78, 86.17, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rdyr-mdc6sere2uuv8d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F22398809734', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23493110267', 'Kit 3 Creme Dental Sabor Morango Mypetone - 90g', 'Creme Dental Morango Mypetone - 90g - Não requer enxágue: Facilita o processo de higiene bucal para cães e gatos; - Limpeza eficaz: Combate o acúmulo de placas bacterianas para uma boca saudável; - Sabor atraente: O delicioso aroma de Morango torna a escovação mais agradável; - Fortalece dentes e gengivas: Promove a saúde oral do seu pet, prevenindo problemas dentários. Detalhes O Creme Dental Morango Mypetone, é a escolha perfeita para manter a saúde bucal do seu pet em dia. Com seu alto poder de limpeza, este creme dental inovador é formulado para inibir o acúmulo de placas bacterianas, prevenindo problemas dentários comuns em cães e gatos. Você pode garantir que seu pet desfrute de uma boca saudável e refrescante, enquanto fortalece o vínculo entre vocês por meio do cuidado e da atenção diária. Dicas Especiais Escolha a escova certa: Utilize uma escova de dentes adequada para cães ou gatos. Introduza gradualmente: Comece com pequenas quantidades para acostumar seu pet com o sabor. Use regularmente: Escove os dentes do seu pet diariamente para melhores resultados. Seja gentil, escove os dentes do seu pet com movimentos suaves para evitar desconforto. Monitore a saúde oral e fique atento a sinais de problemas dentários e consulte um veterinário regularmente. Indicação: Cachorros, Gatos Porte/Raça: Raças Pequenas, Raças Médias, Raças Grandes Idade: Filhotes, Adultos, Idosos Composição: Goma guar, bicarbonato de sódio, aroma, carbonato de cálcio e veículo. Apresentação: Frasco 90g', 53.38, 34.44, NULL, 'Pets > Pet Grooming > Oral Care', 'https://cf.shopee.com.br/file/br-11134207-7r98o-maik4qnyy3yn63', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290073877%2F23493110267', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21499841606', 'Lixa Costado De Papel Em Rolo 120mm x 25m G80 Vonder', 'A lixa em rolo com costado de papel Vonder é ideal para trabalhos de semiacabamento em superfícies como massa, gesso, alvenaria e madeira. Sua estrutura oferece excelente rendimento em operações manuais ou com lixadeiras que utilizam lixa em formato plano. Produzida com grão abrasivo de óxido de alumínio branco, proporciona um lixamento uniforme com ótimo poder de corte. O costado de papel com menor densidade garante maior flexibilidade e fácil adaptação a superfícies curvas ou irregulares, sendo uma excelente escolha para uso em marcenarias, obras e reformas em geral. Características: Marca: Vonder Modelo: LP 100 Referência: 1292120080 Tipo de grão abrasivo: Óxido de alumínio branco Grão: G 80 Tipo de costado: Papel Largura do rolo: 120 mm Comprimento do rolo: 25 m Benefícios: Ideal para lixamento de massa, gesso, alvenaria e madeira Costado de papel mais leve e flexível para maior adaptação Grão 80 proporciona excelente poder de corte e acabamento Versátil para diferentes aplicações e setores Alta durabilidade e rendimento em operações contínuas Conteúdo da embalagem: 1x Rolo de lixa abrasiva 120 mm x 25 m Grão 80 Vonder', 135.69, 114.33, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rdyu-mdc64q87nqbd37', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F21499841606', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22397333474', 'Pneu Para Moto Sportíssimo II 90/90-14 Dianteiro Maggion Para Uso Sem Câmara + 1 Válvula de Brinde', 'COMBO PNEU MOTO STREET SPORTISSIMO II 90/90-14 S/C DIANT MAGGION + VALVULA PNEU S/C TR-412 A Maggion oferece a melhor relação custo x benefício em todos os tipos de pneus e câmaras. Genuinamente brasileira e a mais de 80 anos no mercado. PERGUNTAS FREQUENTES:O PNEU É NOVO OU REMOLD?R: SÓ TRABALHAMOS COM PNEUS NOVOS E ORIGINAIS DE FÁBRICAS. O PNEU VEM COM NOTA FISCAL?R: SIM, TODOS OS NOSSOS PRODUTOS ACOMPANHAM NOTA FISCAL. O PNEU VEM COM A RODA/ARO?R: O ANUNCIO É APENAS DO PNEU O PNEU ACOMPANHA CAMARA DE AR?R: NÃO ACOMPANHA, O ANUNCIO É APENAS DO PNEU A Maggion garante a excelência da qualidade de seus produtos através das seguintes certificações: - Acreditado pela ANAB, RVA e INMETRO - Laboratório de Ensaios de Pneus - LEP Acreditado pelo INMETRO Nº CLF 0021 - Produtos certificados por Falcão Bauer Quality Institute (Pneus para automóveis,camionetas, motocicletas, scooters, ciclomotores, microônibus, caminhões e ônibus) Nº 018 - Laboratório de Ensaios de Pneus - LEP Acreditado pelo INMETRO Nº CLF 0021 - Sistema de Gestão da Qualidade certificado pela ABS-QE - ISO 9001:2008; Principais aplicações: - SCOOTER - Honda Pcx 150 Até 2019 Identificação: 90/90-14 TL Marca: Maggion Aro: 14 Modelo: Sportissimo II -Válvula p/ Pneu sem câmara Marca: Bremen Modelo: TR-412 * Observações: - O anúncio é apenas do pneu, não acompanha o aro. - Uso SEM CÂMARA. - Recomendamos que os produtos sejam instalados por profissionais capacitados e não nos encarregamos pelo mau uso ou instalação indevida, acarretando a perda da garantia. - Compra 100% segura!', 264.9, 238.41, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Motorcycle Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rceb-lreke7x70qqtdc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F813601541%2F22397333474', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47402907793', 'Espumadeira em Nylon Preto Ability (25158/100) - Tramontina', 'A Espumadeira em Nylon Preto Ability (25158/100) - Tramontina, é produzida em nylon, pode ser utilizada em temperaturas de até 180° graus e é ideal para ser utilizada em revestimentos antiaderentes e cerâmicos, pois não os danifica. Além disso, ela ainda é fácil de limpar e pode ir à máquina de lavar louças, facilitando sua rotina! Descrição do Produto: • Espumadeira de Nylon que permite uso em temperaturas de até 180 °C. • Cabo com furo passante possibilitando que sejam pendurado na sua cozinha. • Utensílio ideal para uso em panelas com revestimentos antiaderentes e cerâmicos, pois não danifica o produto. • Pode ir à máquina de lavar louças facilitando seu dia a dia. Referência: 25158/100. Cód. de Fábrica: 25158/100. Marca: Tramontina.', 19.0, 19.0, NULL, 'Home & Living > Kitchenware > Spatulas & Cooking Tweezers', 'https://cf.shopee.com.br/file/sg-11134201-822yi-mi3c84sxl72bcf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F47402907793', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
