INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793818025', 'Vonixx Multilimpador Para Limpeza Pesada Impact 3l', 'LIMPADOR MULTIUSO IMPACT 3L --------------------------------------------------------------------------------------- DESCUBRA O PODER DO IMPACT, UM LIMPADOR UNIVERSAL ECOLOGICAMENTE CORRETO E NAO-CORROSIVO, DESENVOLVIDO PARA ENFRENTAR AS LIMPEZAS MAIS DIFICEIS EM DIVERSAS SUPERFICIES. SUA FORMULA EXCLUSIVA GARANTE ALTA EFICACIA NA ELIMINACAO DE MANCHAS CAUSADAS PELO IMPACTO DE INSETOS, GORDURA E ENCARDIDOS. COM O IMPACT, VOCE PODE CONFIAR EM UMA LIMPEZA PODEROSA E EFICIENTE, SEM CAUSAR DANOS AO MEIO AMBIENTE. CUIDE DO SEU VEICULO, E DE OUTRAS SUPERFICIES, COM A EXCELENCIA E A RESPONSABILIDADE QUE SO O IMPACT PROPORCIONA. EXPERIMENTE AGORA E DEIXE SUAS SUPERFICIES BRILHANDO COMO NOVAS, SEM PREJUDICAR O PLANETA! IMPACT E IDEAL PARA USO EM RODAS, MOTORES, PNEUS, CHASSIS, CROMADOS, ESTOFADOS, CARPETES, TECIDOS, METAIS, CAIXAS DE RODAS E PINTURAS AUTOMOTIVAS. OBS: IMPACT PODE SER UTILIZADO EM EXTRATORA E TORNADOR. IMPACT NAO E RECOMENDADO PARA USO EM PLASTICOS INTERNOS E EXTERNOS. NAO RECOMENDAMOS USO DO PRODUTO EM BANCOS DE COURO. --------------------------------------------------------------------------------------- CONTEUDO NA EMBALAGEM: 1 NOTA FISCAL 1 LIMPADOR MULTIUSO IMPACT 3L --------------------------------------------------------------------------------------- CARACTERISTICAS DO PRODUTO: IMAGEM ILUSTRATIVA ALTA QUALIDADE E DURABILIDADE COD INTERNO DO PRODUTO: 11020193 --------------------------------------------------------------------------------------- ANTES DE FINALIZAR A COMPRA: VERIFIQUE COM MUITA ATENCAO ATRAVES DAS FOTOS E DESCRICAO SE O PRODUTO E COMPATIVEL COM O MODELO QUE DESEJA ADQUIRIR. NOS NAO NOS RESPONSABILIZAMOS POR MA INSTALACAO OU MAU USO DO PRODUTO. PARA EVITAR TRANSTORNO PROCURE UM PROFISSIONAL ESPECIALIZADO.', 88.83, 88.83, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-7repx-m8ajrjfav5bb95', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F390168708%2F23793818025', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
