INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23294206367', 'Panela De Arroz Philco 5 Xícaras PH5P Visor Glass Inox 220V', 'Panela De Arroz Philco 5 Xícaras PH5P Visor Glass Inox 220VA Panela de Arroz Philco PH5P Inox é Visor Glass, tampa de vidro que possibilita acompanhar o alimento durante o preparo. Com ela você pode refogar alimentos antes de cozinhar e preparar diversas receitas como: ensopados, sopas, legumes e muito mais. Após o término do preparo ela entra em modo Manter Aquecido e retirando o cabo elétrico você pode levar ela à mesa. Sabor e charme em suas refeições! Principais Características: - Capacidade para 5 xícaras de arroz - Tigela com revestimento antiaderente - Luzes indicadoras de funcionamento - Faz diversos tipos de arroz - Cozinha legumes e verduras - Bandeja perfurada para cozinhar no vapor - Acompanha colher e copo medidor - Tampa vedada com alça, botão de travamento e saída de vapor - Tampa com visor em vidro para acompanhar o preparo do alimento - Coletor de água - Cordão elétrico removível. Especificações Técnicas: Marca: Philco Modelo: PH5P Cor: Inox Tampa: Vedada Estado: Novo Toque frio: Sim Tipo: Panela de arroz Capacidade: 5 xícaras Display: Mecânico Copo dosador: Sim Espátula: Sim Potência (W): 400 Revestimento: Inox Altura do produto: 24,3 cm Largura do produto: 23 cm Comprimento do produto: 22 cm Peso do produto: 1,74 kg Altura com embalagem: 25,2 cm Largura com embalagem: 23,6 cm Comprimento com embalagem: 23,6 cm Peso com embalagem: 2,03 kg Garantia (Dias): 360 Observação: Somente faturamos para o nosso consumidor final, ou seja, não faturamos pedidos para CNPJ por este portal de vendas;', 263.9, 263.9, NULL, 'Home Appliances > Kitchen Appliances > Multi-function Cookers', 'https://cf.shopee.com.br/file/sg-11134201-7rdxd-mbwwaoebcsvt3b', 'https://shope.ee/an_redir?origin_link=https%3