INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20899680300', 'Sabonete Líquido Minná Mãos Sache Milk 450ml', 'O Sabonete Líquido Minná Mãos Sachê Milk 450ml oferece uma experiência de cuidado especial, limpando as mãos suavemente e deixando a pele macia e hidratada. Com uma fragrância leve e cremosa de leite, proporciona uma sensação de conforto e aconchego a cada uso. Sua embalagem em sachê de 450ml é prática e ideal para reabastecer dispensers, trazendo economia e funcionalidade para o dia a dia. Modo de Uso: Aplique uma quantidade do sabonete líquido nas mãos úmidas.Esfregue até formar uma espuma cremosa e suave.Enxágue completamente com água corrente.Sinta suas mãos limpas, hidratadas e com um perfume delicado e aconchegante.', 15.48, 9.99, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/sg-11134201-7reo3-m8gejqw9n67q4b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F20899680300', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
