INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26528806720', 'Chinelo Coca Cola Square II Feminino Piscina Casual Quadrado', 'Chinelo Coca Cola Square Sandal II Modelo: CC3514 É a escolha perfeita para quem busca conforto e estilo no dia a dia. Com um design moderno e sofisticado, ele conta com tiras largas que proporcionam um ajuste seguro e confortável aos pés. Sua palmilha anatômica garante maciez e suporte, enquanto o solado em borracha antiderrapante oferece mais estabilidade e segurança a cada passo. Além disso, o icônico logo Coca-Cola em destaque adiciona um toque exclusivo ao visual. Ideal para momentos de lazer, praia, piscina ou passeios casuais, o Square Sandal II une praticidade e autenticidade para quem valoriza conforto sem abrir mão do estilo! Características: - Design moderno e sofisticado: Ideal para quem busca estilo no dia a dia. - Cabedal com tiras largas: Proporciona ajuste seguro e confortável aos pés. - Palmilha anatômica: Garante maciez e suporte para maior conforto. - Solado em borracha antiderrapante: Oferece mais estabilidade e segurança ao caminhar. - Logo Coca-Cola em destaque: Toque exclusivo e autêntico ao visual. - Versátil e prático: Perfeito para momentos de lazer, praia, piscina e passeios casuais. O Chinelo Coca Cola Square Sandal II pode ser encontrado aqui na Usee Brasil! Sobre a Usee Brasil: A Usee Brasil é uma empresa brasileira que oferece uma variedade de produtos de alta qualidade, desde roupas e acessórios até itens para casa. Tenha uma experiência conosco!', 99.99, 61.99, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Flip Flops', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mhccifyw0xz9e3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F349198275%2F26528806720', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
