INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45805381573', 'Kit 4 Caixa Sachê Adultos Raças Pequenas Sabor Frango 100g - Special Dog Ultralife', 'Special Dog Ultralife Sachê Adultos Raças Pequenas Sabor Frango – 100g Alimento úmido completo e balanceado, desenvolvido para cães adultos de raças pequenas. Feito com pedaços de frango cozidos a vapor e batata‑doce, promove saúde da pele, articulações e redução do odor das fezes. Destaques Principais - Sem corantes e aromatizantes artificiais - Ômegas 3 e 6 + zinco orgânico: pele protegida e pelo brilhante - Extrato de Yucca: redução do odor das fezes Análise Nutricional Garantida (por kg) Proteína Bruta: mín. 90 g Gordura (Extrato Etéreo): mín. 35 g Umidade: máx. 820 g Energia Metabolizável: 758 kcal Ingredientes Selecionados Carne de frango, carcaça de aves, miúdos de suíno, biomassa de microalgas, extrato de Yucca schidigera, condroitina, glicosamina e mix de vitaminas e minerais essenciais. Ideal para servir puro ou misturado à ração seca, garantindo nutrição, sabor e bem‑estar em cada sachê.', 171.99, 129.9, NULL, 'Pets > Pet Food > Dog Food', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjyas61y6hhe00', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290073877%2F45805381573', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
