INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44608833149', 'Safira Agua Mineral Com Gás 1,5lt Fardo com 6 unidades', 'A Água Mineral Safira 1,5L Com Gás é perfeita para quem busca hidratação com mais intensidade e frescor. Com uma carbonatação marcante e borbulhas abundantes, proporciona uma experiência refrescante e sofisticada a cada gole, sendo ideal para acompanhar refeições, encontros ou momentos de descontração. Extraída de fontes subterrâneas profundas, essa água mineral é naturalmente pura e rica em sais minerais essenciais como cálcio, magnésio e bicarbonato, contribuindo para o equilíbrio do organismo e o bem-estar diário. Seu processo de envase direto na fonte preserva todas as propriedades naturais, garantindo qualidade superior em cada garrafa. A versão de 1,5 litro é ideal para compartilhar, oferecendo praticidade tanto para consumo em casa quanto em estabelecimentos. Versátil, pode ser consumida pura, bem gelada, ou utilizada no preparo de drinks e coquetéis, sendo também uma excelente alternativa aos refrigerantes. Além disso, sua embalagem PET é resistente e reciclável, reforçando o compromisso com a sustentabilidade e o consumo consciente.', 69.9, 28.9, NULL, 'Food & Beverages > Beverages > Water', 'https://cf.shopee.com.br/file/br-11134207-820l4-mn1hra4vvpxd40', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1306254852%2F44608833149', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
