INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18797738940', 'Base Box Baú Solteirão 96x203 Courino Linho Areia', 'Baú Solteirão King 96: Organização e FuncionalidadeO Baú Solteirão King 96 oferece 393 litros de espaço interno, sendo a solução perfeita para manter o quarto organizado e prático. Revestido em Courino Linho Areia, combina um visual elegante com facilidade de higienização e proteção contra deformidades causadas por impactos externos. Medidas e Características EstruturaisMedidas Externas:96x203x34 cm (sem os pés). 96x203x42 cm (com os pés). Medida Interna:85x192x24 cm. Características Estruturais: Revestimento: Courino Linho Areia. Tecido interno: TNT de alta gramatura. Costura: Reta, com acabamento impecável, sem parafusos aparentes. Fundo do baú: Parafusado por baixo para maior resistência. Pés: Fabricados em polímero resistente. Cuidados e HigienizaçãoFácil manutenção com pano úmido. Evite produtos químicos, para preservar o revestimento. Itens Inclusos1 Cama Baú. 1 Caixa de pezinhos. 1 Alça de apoio, fixada na parte traseira para evitar o deslizamento do colchão. Informações ImportantesConfira as dimensões do produto antes da compra para garantir que ele passe por portas, corredores e elevadores. A transportadora não realiza montagem, içamento externo ou desmontagem de portas e janelas. NÃO ACOMPANHA O COLCHÃO. Foto meramente ilustrativa. O Baú Solteirão King 96 em Courino Linho Areia combina estilo, funcionalidade e praticidade para um quarto sempre organizado! &nbsp;&nbsp;', 721.11, 679.0, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-7rffs-m3gu7eeoprs5cf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F785818771%2F18797738940', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
