INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42269743222', 'Conector DC Jack para Notebook Samsung NP300E5', 'Conector DC Jack compatível com Samsung NP300E5 Este é um DC Jack bringIT compatível com o notebook Samsung NP300E5. Ele é ideal para acabar com os problemas de alimentação de energia em um notebook. O DC Jack — ou DC Power Jack — é um conector interno responsável por intermediar a alimentação de energia entre a fonte (carregador) e o laptop. Este produto é um de alta qualidade e cumpre todas as especificações de segurança dos notebooks. Para evitar problemas de compatibilidade, compare as fotos deste anúncio com seu equipamento original. Assim você consegue verificar as principais informações de compatibilidade e demais especificações do seu notebook. Atenção: Esse é um dc jack bringIT, portanto não é um produto original da fabricante Samsung. Caso seja necessário, todo o suporte e garantia do produto serão oferecidos pela nossa equipe. Informações Técnicas Tamanho do Conector: 5.5mm x 3.0mm Cabo: Sem Cabo Garantia: 3 meses de garantia contra defeitos de fabricação Referência: DC113-SM-0004', 34.67, 34.67, NULL, 'Computers & Accessories > Desktop & Laptop Components > Others', 'https://cf.shopee.com.br/file/sg-11134201-8259i-mqutvi6qfe9v50', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F392651618%2F42269743222', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22835009544', 'Vassoura Plástica de Jardim 22 Dentes com Cabo 120 CM TRAMONTINA', 'Vassoura Plástica Jardim 22 Dentes e Cabo Madeira 120cm 77850721 TRAMONTINA Mantenha seu jardim longe das folhas secas ou outros detritos que possam cair sobre o gramado, com a vassoura plástica laranja Tramontina com 22 dentes e cabo de madeira 120 centímetros. Ideal para a remoção de sobras de grama cortada, folhas que caem sobre o gramado e demais detritos, permitindo a exposição à luz solar, mantendo-o sempre saudável. Com a Tramontina você garante praticidade na hora de cuidar do jardim. Dados técnicos: Fabricada em polipropileno de alta resistência, proporcionando maior durabilidade e ótimo acabamento. Possui 22 dentes fixos. Possui olho de 23 mm de diâmetro. O cabo de 120 cm desta ferramenta, além de possuir ótima resistência, é produzido com madeira de origem renovável. Cabo com acabamento envernizado, para um melhor acabamento e apresentação do produto. A camada protetora em verniz incolor realça sua tonalidade, concedendo brilho e um toque mais liso ao produto. Recomendações de Uso: A vassoura é indispensável para deixar o jardim sempre limpo e bonito. Leve e prática, serve para recolher a grama cortada, folhas que caem com o vento e outros detritos presentes no gramado. Para descarte dos produtos e embalagens siga as orientações de reciclagem vigentes. Ref: 77850721 Marca: Tramontina Garantia: 3 Meses (Vícios ou defeitos de fabricação). *Imagens Meramentes Ilustrativas.', 53.9, 53.9, NULL, 'Home & Living > Home Care Supplies > Brooms', 'https://cf.shopee.com.br/file/sg-11134201-7qvdn-levga01vn04z94', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F357239640%2F22835009544', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
