INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19398106191', 'Suporte Universal Para Baú Bauleta Entrega De Moto Completo Resistente Forte Original ICBRAS Premium', 'Suporte Universal para Baú de Moto – iCbras 🏍️📦 O Suporte Universal iCbras foi desenvolvido para quem precisa de praticidade, segurança e agilidade na instalação do baú na moto. Com sistema de engate rápido, ele permite fixação firme no pegador traseiro sem complicação, dispensando ferramentas complexas e facilitando tanto a instalação quanto a remoção no dia a dia. Compatível com 95% das motos nacionais, é a solução ideal para entregadores, motoboys e motociclistas que buscam estabilidade, durabilidade e confiança mesmo em uso intenso. 📦 Itens que acompanham o produto: ✔ 01 Suporte plástico ✔ 02 Catracas com cintas para fixação ✔ 04 Parafusos ✔ 01 Chave plástica ✔ Manual de instruções 🔧 Detalhes Técnicos: • Fixação por catracas no pegador traseiro da moto • Compatível com 95% das motos nacionais • Sistema de engate rápido – fácil instalar e remover • Dimensões: 12 x 26 x 43 cm • Peso: 2,0 kg • Material resistente para uso diário 🚀 🚀 Por que escolher este suporte? 🔥 Instalação simples e rápida 🔥 Excelente estabilidade para o baú 🔥 Ideal para delivery e uso profissional 🔥 Compatível com a maioria das motos ✔ Produto novo e original ✔ Pronta entrega e envio em até 24 horas ✔ Compra 100% segura IMPORTANTE: SUA SATISFAÇÃO GARANTIDA! ✔️ -----> Entrega assegurada pela Shopee com garantia', 319.9, 249.99, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Cases', 'https://cf.shopee.com.br/file/br-11134207-820m4-moscaseo2e4l5b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F942805673%2F19398106191', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
