INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14382451887', 'CABO VELOCIMETRO UNO PREMIO ELBA FIORINO Efrari', 'IDEAL AUTO PECAS - Desde 1992 - IDEAL PARA SEU CARRO! Cabo Velocimetro - Efrari APLICACAO: UNO 1050 / 1.3 / 1.5 / 1.6 DE 1984 A 1990 PREMIO 1050 / 1.3 / 1.5 / 1.6 DE 1984 A 1990 ELBA 1050 / 1.3 / 1.5 / 1.6 DE 1984 A 1990 FIORINO 1050 / 1.3 / 1.5 / 1.6 DE 1984 A 1990 (COMPRIMENTO: 1070 MM) DESCRICAO DO PRODUTO: Em veiculos antigos existe um sistema mecanico de ima implantado na roda ou na transmissao do veiculo, que quanto maior a rotacao da peca maior a forca que esse ima transmite, e para ocorrer essa transmissao e necessario um cabo do velocimetro que envia a forca que o ima manda para o painel do veiculo, onde e convertido por outro ima em km/h.', 56.9, 56.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/b8dcb545fb5c447668027f5840a9dd52', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F616290090%2F14382451887', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19697515051', 'Kit Mini Veiculos Pull Back Sonic 2 kit com 5', 'Os personagens de Sonic embarcaram em uma nova aventura! Com o kit de Mini Veiculos Pull Back, a brincadeira vai ficar muito mais divertida! Estes incríveis carrinhos são de fricção pull back, puxe o carrinho para trás e solte-o para ele sair correndo por aí, além de um design inspirado nos grandes eprsonagens do Sonic: Tails, Sonic, Tails, Knuckles, Dr. Eggman e Shadow ! A brincadeira ficará muito mais emocionante com os Mini Veiculos Pull Back do Sonic!', 59.99, 49.99, NULL, 'Mom & Baby > Toys > Toy Vehicles', 'https://cf.shopee.com.br/file/sg-11134201-7rd4y-lupo1y1y52fd0f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F689242394%2F19697515051', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
