INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22997495820', 'Kit Farol Milha Auxiliar Saveiro G6 2013 2014 2015 2016 Trend Trooper Botão Universal', 'Kit Farol de Milha Auxiliar Volkswagen Saveiro G6 2013 2014 2015 2016 Trend Trooper Botão Universal Características: Produto novo de ótima qualidade; Lente lisa em acrílico. Especificações técnicas: Encaixe de lâmpada hb4; Regulagem de foco manual; Não acompanha lâmpadas nem soquetes. Conteúdo da embalagem: 01 Relê; 02 Faróis de milha; 01 Chicote elétrico; 01 Botão universal. Compatível com os modelos: Saveiro G6 Trend 2013; Saveiro G6 Trend 2014; Saveiro G6 Trend 2015; Saveiro G6 Trend 2016; Saveiro G6 Trooper 2013; Saveiro G6 Trooper 2014; Saveiro G6 Trooper 2015; Saveiro G6 Trooper 2016. Atenção: Para à instalação dos faróis é necessário a furação das molduras. Obs: valor anunciado referente ao KIT. Garantia: 90 dias. Dica: Dê um novo visual para o seu carro, aqui você encontra os melhores produtos com os melhores preços! Importante: NÃO somos responsáveis pela má instalação ou mau uso do produto, para evitar transtornos procure por um profissional especializado.', 130.0, 117.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/br-11134201-7r98o-lv113fviwirk8c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1242764769%2F22997495820', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
