INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58208534346', 'Camiseta Juvenil Menino Costas Com Estampa Beats Preto', 'Peça-chave para um visual moderno e cheio de personalidade, a Camiseta Elian Beats é indispensável no guarda-roupa teen. Feita em meia malha penteada, ela possui mangas longas e estampa frontal discreta. Já a maxi estampa nas costas traz um destaque especial para o look e valoriza o estilo urbano, sendo ideal para momentos de lazer com a galera ou com a família. Invista nesse visual para curtir a estação com estilo e conforto!Detalhes da peça: • Feita em meia malha penteada • Possui mangas longas • Estampa em lettering • Ideal para momentos de lazer', 74.9, 52.43, NULL, 'Baby & Kids Fashion > Boy Clothes > Tops', 'https://cf.shopee.com.br/file/sg-11134201-825ae-mr1tu036p1xc4a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1079500559%2F58208534346', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
