INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23193234712', 'Jogo de Cartas 1x Eu Vi! - Copag', '*O produto é unitário, escolher o modelo de acordo com as variações disponíveis. Reúna a família e os amigos para horas de diversão com o jogo Eu Vi! Desenvolva a observação, a memória e a rapidez com este clássico jogo de cartas. Ideal para todas as idades, o Eu Vi! é perfeito para momentos de lazer e descontração. Contém 55 cartas no formato 56 mm x 87 mm Dados Técnicos: Embalagem: Unitário Quantidade de Cartas: 55 Características: - Marca: Copag *Imagens meramente ilustrativas Conteúdo da Embalagem: 01x Jogo Eu Vi! Com 55 Cartas', 26.0, 26.0, NULL, 'Hobbies & Collections > Toys & Games > Dice, Board & Card Games', 'https://cf.shopee.com.br/file/sg-11134201-7rdxk-lz6jj5wncm9685', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F371036439%2F23193234712', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
