INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22195061686', 'Kit com 2 Canetas Oficiais Paraná Clube Vermelha e Azul | Escrita Macia | Produto Oficial', 'Leve sua paixão pelo Paraná Clube para o dia a dia com este Kit Oficial de Canetas, composto por uma caneta vermelha e uma caneta azul, ambas personalizadas com o escudo e a identidade visual do clube. Ideal para uso no trabalho, na escola, na faculdade ou no escritório, este kit combina praticidade, qualidade e o orgulho de torcer pelo Tricolor da Vila. Também é uma excelente opção de presente para colecionadores e torcedores que valorizam produtos oficiais licenciados. As canetas possuem corpo metálico, acabamento premium e escrita suave, proporcionando conforto e elegância em qualquer ocasião. Destaques do produto: Produto Oficial Licenciado do Paraná Clube Kit com 2 canetas Corpo metálico nas cores vermelha e azul Escrita macia e confortável Acabamento resistente e de alta durabilidade Ideal para uso diário, coleção ou presente Conteúdo da embalagem: 01 Caneta Vermelha Oficial Paraná Clube 01 Caneta Azul Oficial Paraná Clube Especificações: Quantidade: 2 canetas Material: Corpo metálico Cores: Vermelha e Azul Produto Oficial Licenciado Demonstre seu orgulho pelo Paraná Clube em todos os momentos com um kit elegante, funcional e desenvolvido especialmente para os torcedores que desejam levar as cores do Tricolor da Vila para o seu dia a dia.', 19.89, 18.89, NULL, 'Stationery > Writing & Correction > Pens & Inks', 'https://cf.shopee.com.br/file/br-11134207-820lm-mqgvpakkjbb6c1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1561205436%2F22195061686', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
