INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22593184146', 'Faca Para Cortador de Gramas SL - 30T / SL - 30E (4111097) - Trapp', 'A Faca Para Maquinas SL-30T / SL-30E (4111-097) - Trapp, é uma peça de reposição que foi desenvolvida para os cortadores de gramas SL-30T / SL-30E. Fabricadas em Aço, com pintura em pó de poliéster polimerizado em estufa a 180°C. ATENÇÃO: Favor atentar-se sobre a largura da sua faca antes de efetuar a compra, pois existe mais de um tamanho para os mesmos modelos de máquina. Descrição do Produto: • Possui acabamento pintado que proporciona maior resistência à corrosão/oxidação. • Indicada para reposição na máquina SL-30T / SL-30E Trapp. • Contém na embalagem 1 Lâmina faca. • Pintura com tinta a pó de poliéster polimerizado em estufa a 180°C. • Modelos Compatíveis: SL -30T/ SL -30E. • Diâmetro do Furo: 16mm. Referência: 4111-097. Cód. Fábrica: 4111-097. Marca: Trapp.', 42.33, 42.33, NULL, 'Home & Living > Gardening > Lawn Mowers', 'https://cf.shopee.com.br/file/sg-11134201-7rdyc-ly6jfwxb5wdkdd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F22593184146', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
