INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993705065', 'Porca de latão 3/8 Sae Hulter HT2POR38P', 'Porca de latão 3/8 Sae Hulter HT2POR38P Este produto é uma escolha excepcional para diversas aplicações industriais e de construção, proporcionando durabilidade e desempenho confiável. Fabricada com precisão em latão de alta qualidade, apresenta resistência superior à corrosão, garantindo uma longa vida útil mesmo em ambientes desafiadores. A rosca SAE 3/8 é padronizada, assegurando uma instalação fácil e compatibilidade com uma variedade de parafusos e peças correspondentes. O design cuidadosamente elaborado oferece uma fixação robusta e segura, sendo uma escolha confiável para projetos que demandam resistência e estabilidade. Seja para uso em maquinário pesado, estruturas metálicas ou projetos de construção civil, esta porca de latão atende aos mais altos padrões de qualidade.', 15.9, 15.9, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https://cf.shopee.com.br/file/sg-11134201-7rbl4-m644fpg21o4r79', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1398462025%2F23993705065', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22193587466', 'Chave Combinada Com Catraca Flexível 18mm (735618) - Onsite', 'A Chave Combinada Com Catraca Flexível 18mm (735618) - Onsite, oferece ainda mais versatilidade e praticidade do que a chave combinada com catraca comum. - Chave Combinada Com Catraca Flexível 18mm em AÇO CARBONO: Uso Profissional. Características: • Chave fixa: Um lado da chave é tradicional e serve para segurar porcas ou parafusos de forma firme. • Chave com catraca flexível: O outro lado da ferramenta possui a catraca, mas com um diferencial: a sua cabeça é flexível, ou seja, pode ser inclinada em diferentes ângulos. Essa flexibilidade permite ao usuário acessar parafusos em locais de difícil alcance ou em ângulos que seriam complicados de se trabalhar com uma chave fixa ou uma chave catraca comum. Principais benefícios: • Acesso a locais de difícil alcance: A cabeça flexível facilita o trabalho em espaços apertados ou em áreas onde o ângulo de operação é limitado. • Eficiência: Assim como a chave com catraca comum, a função de catraca permite apertar ou afrouxar sem a necessidade de retirar a chave a cada movimento. • Essa ferramenta é especialmente útil em trabalhos mecânicos, de montagem e manutenção, onde o acesso a parafusos e porcas pode variar em complexidade. Código: 735618. Marca: Onsite. Tamanho: 18mm. Ean: 1008500989299.', 47.9, 45.51, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rfgd-m3c4uk4m89np99', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F22193587466', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26576837410', 'Jarra Graduada Transparente Com Capacidade de 3L (2028-3L) - Lupus', 'A Jarra Graduada Transparente Com Capacidade de 3L (2028-3L) - Lupus, é ideal para o Armazenamento, transferência e manuseio de óleos e líquidos em geral. Fabricada em Polipropileno translúcido, esta jarra permite ser utilizada para uma diversidade de tarefas, como por exemplo nas tarefas domésticas. Descrição do Produto: • Modelo: Jarra Graduada Transparente. • Material: Polipropileno (PP), Translúcido. • Peso (Kg): 0,270. • Capacidade: 3 Litros. • Alça Para Transporte. Referência: 2028-3L. Cód. de Fábrica: 3620763. Marca: Lupus.', 54.49, 54.49, NULL, 'Home & Living > Dinnerware > Jugs, Pitchers & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7rccr-m6h14ecx2ez8af', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F26576837410', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23134907914', 'Reparo Driver HDI 300 HDI 320 Hinor 8 Ohms Para Corneta Som Automotivo', 'Reparo para driver compatível com HDI 300 e HDI 320. Produto indicado para reposição em corneta e sistemas de som automotivo, com impedância de 8 Ohms e ótimo custo-benefício para manutenção e substituição. Especificações Técnicas: • Impedância: 8 Ohms • Aplicação: reparo para driver • Compatível com HDI 300 • Compatível com HDI 320 • Indicado para corneta e som automotivo • Quantidade: 1 unidade Conteúdo da Embalagem: • 1 Reparo para Driver HDI 300 / HDI 320 Importante: • Verifique o modelo do seu driver antes da compra • Confirme medidas, impedância e compatibilidade antes da instalação • Recomendamos instalação por profissional especializado reparo driver hdi 300, reparo driver hdi 320, reparo hinor 8 ohms, reparo corneta hinor, reparo para som automotivo, reparo driver corneta, driver 8 ohms, reparo compatível hdi300, reparo compatível hdi320, reparo para corneta automotiva, reparo driver paralelo', 18.4, 18.4, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/br-11134207-820m7-mnnda4fecfls53', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F413680793%2F23134907914', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
