INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19197614431', 'Detergente Clorado Gold - Galão 5L', 'Detergente Clorado 5L Gold Desenvolvido para desinfecção, limpeza e clareamento das superfícies em ambientes de fluxo alto, médio e baixo. Com excelente ação bactericida, possui agentes de alto poder de remoção nas sujidades gordurosas e manchas impregnadas. Tem comprovada eficiência contra bactérias como: Staphylococcus aureus, Salmonella e Pseudomonas aeruginosa. Indicado para desinfetar ralos, lixeiras, vasos sanitários, banheiros, pisos não tratados, mármores, louças, vidros, cerâmicas, azulejos e utensílios de polipropileno. Ideal para cozinhas industriais e hospitais em geral. Cor: Incolor Fragrância: Característica Diluição: - Desinfecção e Limpeza Pesada: 01 parte do produto para 30 partes de água; - Limpeza Leve: 01 parte do produto para 100 partes de água. Embalagem: 01 unidade com 5L', 96.12, 96.12, NULL, 'Health > Medical Supplies > Others', 'https://cf.shopee.com.br/file/sg-11134201-824i1-meeb1newms5j90', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F946161700%2F19197614431', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
