INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42208202267', 'Pelúcia Fuggler Laboratory Misfits 23cm - Sir Belch', 'Conheça a Pelúcia Fuggler Laboratory Misfits 23cm, a linha mais caótica e divertida de monstrinhos que você vai encontrar! Com 11 modelos únicos para descobrir, esses Fugglers são o resultado de uma experiência científica que deu completamente errado Cada um deles possui dentes humanos realistas e um design peculiar, com cores e marcas excêntricas que vão deixar você surpreso Além disso, seu tamanho de 23cm os torna perfeitos para colecionar ou para dar aquele toque de irreverência ao seu espaço Eles são estranhos, bizarros e absolutamente adoráveis de uma forma única Prepare-se para um risco total de diversão e loucura com esses Fugglers, que vão conquistar você e todos ao seu redor!', 197.99, 197.99, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/sg-11134201-7rdyj-mc2dka0dedp488', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F689242394%2F42208202267', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
