INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45261388580', 'Regata Flamengo Masculina Dry Performance Coimbra', 'A Regata Flamengo Masculina Dry Performance Coimbra é a escolha perfeita para os torcedores apaixonados pelo Mengão. Com um design moderno e elegante, esta camisa é ideal para ocasiões comemorativas, permitindo que você mostre seu amor pelo clube de forma estilosa e confortável. Produzida pela marca Coimbra, a camisa é confeccionada em 100% poliéster, garantindo leveza e respirabilidade. O material Dry Texturizado proporciona um toque suave na pele, ideal para dias quentes ou para atividades ao ar livre. A gola redonda e sem mangas oferecem um ajuste perfeito, tornando-a uma peça versátil para o seu guarda-roupa. O logo em TPU destaca a identidade do Flamengo, simbolizando a paixão e a tradição do clube. Seja para um passeio com amigos ou para torcer em casa, esta camisa regata é uma adição essencial para qualquer fã do futebol brasileiro. Vista-se com orgulho e celebre cada momento ao lado do seu time do coração', 179.99, 179.99, NULL, 'Men Clothes > Tops > Tanks', 'https://cf.shopee.com.br/file/br-11134207-820me-mouf4r0rskxv28', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467774639%2F45261388580', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22193878148', 'Bieleta Direita Original Cofap New Civic 2006 2007 2008 2009 2010 2011', 'Seja Bem-vindo(a)!! É um prazer imenso tê-lo em nosso anuncio. Abaixo algumas informações sobre o Produto e Aplicação. Por fim, conheça um pouco mais sobre a nossa loja. Produtos: 1 Bieleta Dianteria Lado Direito Marcas: Cofap Aplicação: Veículo: New Civic; Motor: Todos. Ano: 2006, 2007, 2008, 2009, 2010, 2011. Garantia: 90 dias. É novo, e acompanha nota fiscal Sim! Todos nossos produtos são novos acompanhados de nota fiscal. Sobre a Loja: Somos uma empresa que trabalha exclusivamente com o setor de peças para veículos leves e médios, sendo eles nacionais ou importados. Oferecemos peças com qualidade, prazo de entrega, parcerias com as melhores marcas e eficiência no atendimento. Temos uma equipe de profissionais qualificados para orientar o cliente nas suas mais variadas necessidades relacionadas à manutenção do seu veículo. Oferecemos também um amplo estoque de peças e envios diários. Visamos constantemente o aperfeiçoamento e melhoria dos serviços para a satisfação total do cliente. - ATENÇÃO Para garantia de AMORTECEDORES, só serão aceitas mediante apresentação do certificado enviado junto ao produto. Sem esse documento, não será possível efetuar a garantia do produto. Em caso do não recebimento do certificado, favor nos enviar assim que receber a mercadoria e notar a ausência.', 54.43, 54.43, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/sg-11134201-7rd60-m7qxl6ne89dk28', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373135807%2F22193878148', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22599452187', 'Cotonetes Hastes Flexíveis', 'Cotonetes Hastes Flexíveis são ideais para a higiene pessoal de toda a família. Perfeitos para limpar delicadamente a parte externa da orelha (sem atingir o canal do ouvido), as dobrinhas do pescoço e pernas do bebê, além de serem recomendados para aplicar e remover maquiagem. Feitos com algodão 100% puro e hastes plásticas flexíveis, proporcionam maior suavidade, conforto e segurança para o seu dia a dia.', 8.79, 8.79, NULL, 'Health > Personal Care > Ear Care', 'https://cf.shopee.com.br/file/sg-11134201-8258x-mqnektutqcr3cb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555087%2F22599452187', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '4252807528', 'Kit Com 6 Pares Cano Médio Meias Lupo Original Algodão Unissex Masculino E Feminino', 'Kit Com 6 Pares De Meias Algodão Sport Cano Médio Lupo Ref. 3245 - Original Kit de meias Lupo Sport, confeccionadas em algodão penteado super macio e confortável. Cano médio, adornadas por logotipo da marca punho canelado com calcanhar verdadeiro, com isso, evitando que a meia saia do lugar durante o uso. Ideal para a prática de esportes e nas atividades diárias, possui tecnologia atoalhada, o que facilita a absorção do suor diminuindo o odor nos pés. Excelente custo benefício na compra do kit. O bico e o calcanhar foram reforçados para maior conforto e durabilidade, costuras firmes, interior respirável e macio. Calcanhar Verdadeiro. Atoalhada - Felpa de proteção na sola ou nas regiões de maior impacto. Excelente custo benefício na compra do kit. Original Lupo Sport. Punho canelado. Conforto e durabilidade Tamanhos: M - 37 a 40 G - 41 a 44 Composição: 65% Algodão 34% Poliamida 1% Outra Fibra Descrição da Marca Lupo É uma das maiores e melhores fabricantes de moda íntima e meias. Em 1947 a empresa já era o maior fabricante de meias masculinas do Brasil, a partir de 1990 a Lupo ampliou sua linha de produtos, e hoje é uma das marcas mais conhecidas neste ramo.', 77.65, 77.65, NULL, 'Men Clothes > Socks', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lp9cdys35dadd4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308601970%2F4252807528', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
