INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20498076316', 'Sabonete Líquido Íntimo Nivea Suave 250ml', 'Sabonete Líquido Íntimo Nivea Suave 250ml - Higiene Delicada e Proteção Diária Nivea Sabonete Líquido Íntimo Suave é um sabonete íntimo, de uso diário, que limpa e protege a região íntima. Para que serve? Dermatologicamente e ginecologicamente testado, Nivea Sabonete Líquido Íntimo Suave é um produto de cuidado calmante para uma pele sensível que proporciona sensação de conforto, limpeza, proteção e bem-estar diariamente. Sua fórmula, livre de corantes e propriedades alcalinas, contém extrato de camomila e panthenol que, além de promover uma limpeza suave, previne a irritação no local. Outro ingrediente importante presente neste sabonete é o ácido lático, que ajuda a manter o pH natural da zona íntima. Benefícios - Livre de corantes e propriedades alcalinas - Dermatologicamente e ginecologicamente testado - Pode ser usado diariamente - Mantém o pH natural da região íntima - Previne irritações e acalma a pele Como usar o Sabonete Líquido Íntimo Nivea Suave? -Aplique uma pequena quantidade do produto na palma da mão. -Espalhe suavemente na região íntima externa. -Enxágue bem com água abundante. -Utilize diariamente para manter a higiene e o frescor da área íntima. Dica extra: Para maior conforto, utilize o sabonete íntimo Nivea Suave após atividades físicas ou em dias mais quentes para garantir frescor e proteção prolongados. Encontre o Sabonete Líquido Íntimo Nivea Suave a escolha ideal para quem busca uma higiene íntima delicada, segura e com frescor duradouro. Sua fórmula equilibrada garante proteção e conforto diariamente. Cuide-se com a suavidade e a qualidade de Nivea.', 45.46, 45.46, NULL, 'Health > Personal Care > Feminine Care', 'https://cf.shopee.com.br/file/sg-11134201-7rd44-m76udf1f59jmb8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467864110%2F20498076316', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22792993847', 'Prancha Mq Chapinha Profissional Titanium 450 F Bivolt', 'Prancha Mq Chapinha Profissional Titanium 450 F BivoltDescrição:A Prancha MQ Professional Titanium é a aliada perfeita para quem busca cabelos lisos, macios e livres de frizz. Com placas de titanium e tecnologia avançada, essa prancha profissional garante resultados incríveis em pouco tempo. Seja para escovas progressivas ou simplesmente para um visual impecável no dia a dia, a MQ Professional Titanium é a escolha certa. Características: Placas de Titanium: transferem calor rapidamente, selando as cutículas e modelando com eficiência. Temperatura: 5 opções de temperatura, até 450°F / 232°C, controláveis via display digital. Voltagem: bivolt automático para uso em 110V ou 220V sem ajustes manuais. Tecnologia MCH: aquecimento rápido e constante para resultados uniformes da raiz às pontas. Sistema Floating Plates: placas se ajustam suavemente ao fio, modelando sem danificar. Tecnologia IONIC: elimina o frizz e a estática dos fios, proporcionando um acabamento impecável. Cabo: 2,5 metros de comprimento com base giratória para mais liberdade de movimento. Como Usar MQ Professional Titanium:Conecte, ajuste a temperatura desejada e deslize a prancha pelas mechas para um alisamento perfeito. Com a MQ Professional Titanium, você conquista resultados profissionais no conforto de casa. Marca: Mq Professional Hair Styling Modelo: Prancha Chapinha de Cabelo Titanium Prof a sua MQ Professional Titanium e transforme seus cabelos com praticidade e eficiência!', 812.47, 401.28, NULL, 'Beauty > Beauty Tools > Hair Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rdvn-lycdugq9h4s4bb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1186779187%2F22792993847', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
