INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21477572733', 'Alicate Corta E Desencapa Cabos Vonder', 'Este Alicate Desencapador/Cortador de Fios oferece praticidade e eficiência para profissionais que necessitam cortar e desencapar fios com diferentes espessuras de maneira rápida e segura. Ideal para serviços elétricos e de instalações em geral. Características Principais: > Versatilidade de Uso: Pode desencapar fios de 1,0 mm² a 16,0 mm² e cortar cabos até 16,0 mm², atendendo uma ampla gama de necessidades. > Trava de Segurança: Possui trava que mantém o alicate fechado, facilitando o armazenamento seguro. > Estrutura Resistente: Corpo em aço forjado com acabamento pintado, garantindo maior resistência e durabilidade para o uso constante. > Leve e Compacto: Com 177 mm de comprimento, é confortável para o manuseio em espaços apertados. > Uso Profissional: Indicado para eletricistas e técnicos em instalações elétricas, proporcionando corte preciso e desencape eficiente. Detalhes Técnicos: * Capacidade de Corte: Até 16,0 mm². * Capacidade de Desencape: De 1,0 mm² a 16,0 mm². * Material: Corpo em aço forjado com acabamento pintado. * Comprimento Total: 177,0 mm * Peso Aproximado: 0,22 kg Adquira já o Alicate Desencapador/Cortador de Fios e facilite suas tarefas de corte e desencapamento com mais precisão e segurança!', 49.99, 49.99, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7qvfp-lfa9r1gcofna5c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F942805673%2F21477572733', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
