INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23094837928', 'Pack 3un Multiuso UAU - 1un Rosas e Sedução + 2un Cloro Ativo', 'Multiuso UAU Cloro Ativo 5 em 1: Onde usar? É mais comum usar UAU Cloro Ativo Squeeze Ação 5 em 1 em pisos e azulejos de banheiros e cozinhas. Mas você pode usar sua criatividade e estender o uso para outras superfícies laváveis e resistentes ao cloro, como lavanderia, garagem e área de churrasco. Você até pode substituir a água sanitária na limpeza de tecidos. Não use em carpetes, madeiras, superfícies pintadas ou metálicas, de papel, borracha ou aço inox. Tome cuidado com cerâmicas porosas ou desgastadas, pois pode haver alteração na cor do piso. E não misture com outros produtos de limpeza, especialmente produtos com amônia e ácidos. Como usar? UAU Cloro Ativo Squeeze Ação 4 em 1 limpa, branqueia, desinfeta e remove o limo. Ele te ajuda a limpar manchas de mofo e limo e ainda mata germes e bactérias. Coloque uma luva, dirija o jato sobre a superfície, deixe agir por alguns instantes e enxágue, limpando grandes áreas aos poucos. Se a superfície estiver muito suja, deixe o produto agir um pouco mais e esfregue com esponja macia se precisar (esponja de aço está proibida aqui). Germes e bactérias são exterminados se você aplicar o produto puro e deixar agir por 10 minutos. Multiuso UAU Perfumes Rosas e Sedução: Limpeza e perfume surpreendentes! Máximo poder de limpeza Perfume sofisticado Ideal para cada cantinho da sua casa Surpreenda-se com a eficiência e perfume único do Produto.', 26.92, 26.92, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-8261j-mk2u3k4k2nlw0a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1658245933%2F23094837928', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22794539795', 'Vitamina D3 2000ui Com TCM - 60 Cápsulas - Bigens', 'A Vitamina D3 entrega um suplemento superior aos comumente encontrados no mercado. Sua fórmula contém Óleo TCM (mct) e foi elaborada especificamente para a melhor absorção no organismo, com compostos em sua forma mais biodisponível. Como Tomar A recomendação é de 1 (uma) cápsula ao dia, para adultos acima de 19 anos Ingredientes Colecalciferol (Vitamina D), Veiculo (Triglicerídeos de Cadeia Média - TCM); Cápsula: ÁGua purificada, Geleificante (Gelatina) e Umectante (INS 422). NÃO CONTÉM GLÚTEN. ALÉRGICOS PODE CONTER PEIXE, SOJA E CRUSTÁCEOS (CARANGUEJO). ...', 46.0, 46.0, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/sg-11134201-8259v-mfx6lhidqpe1f8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F976704374%2F22794539795', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
