INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '5195340934', 'Caneta hidrográfica Supersoft Brush 20 cores 150720SOFT Faber-Castell', 'Produto certificado no âmbito brasileiro de qualidade, conforme Portaria Inmetro Nº 333/2012: Segurança, Compulsório, Registro 008053/2017, OCP0003, INMETRO As canetinhas hidrográficas Faber-Castell da linha SuperSoft tem design arrojado e moderno, com ponta pincel (brush) supermacia, perfeita para técnicas de Lettering e desenhos artísticos. Detalhes: - Criatividade em dobro - Ponta Brush: ideal para técnicas de Lettering e desenhos artísticos - Tinta lavável e atóxica - Corantes de alta qualidade - Embalagem reutilizável e 100% reciclável.', 141.56, 109.0, NULL, 'Stationery > Writing & Correction > Pens & Inks', 'https://cf.shopee.com.br/file/sg-11134201-7rdyt-mc6cju4pl8we6e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F479054821%2F5195340934', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '5695338994', 'Pincel marca texto Textliner 46 Amarelo pastel MT/1546AM Faber-Castell', 'Pincel marca texto Textliner 46 - Amarelo pastel - MT/1546AM - Faber-Castell O Marca Texto Pastel Textliner 46 garante um destaque suave e brilhante, além de uma marcação à prova de manchas em todos os papéis padrão. Está disponível em uma variedade de cores pastel luminosas. A ponta especial de poliéster marca em três larguras diferentes de linha para realce individual e de precisão. Detalhes: - Textliner com tinta à base de água - 3 larguras diferentes de linha 1, 2 e 5 mm - Ponta durável - Ideal para todo o papel padrão.', 21.94, 18.9, NULL, 'Stationery > Writing & Correction > Highlighters', 'https://cf.shopee.com.br/file/sg-11134201-7qvf4-lge43y07uik435', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F479054821%2F5695338994', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22193811644', 'Lavadora Semi Automática Tanquinho Colormaq 20kg', 'O Tanquinho Colormaq Ecomax 20kg é ideal para suas necessidades de lavagem. Com batedor no fundo, oferece 6 ciclos de lavagem, incluindo a lavagem rápida, 2 intervalos de molho, desligamento automático, saída de água facilitada pelo painel e 12 meses de garantia. Proporcione uma lavagem eficiente com a linha Ecomax. Marca: Colormaq Modelo: LCS20 Linha: Ecomax Capacidade: 20kg Dimensões: 97 x 55 x 60cm Batedor: Fundo Painel: Manual Timer: Analógico Tempo de Lavagem: 28 min Programas: 6 (Muito Sujo, Rápido, Jeans, Dia-a-dia, Enxágue, Delicado) Molhos: 2 Lavagem Econômica: Sim Lava Edredom: Sim Desligamento: Automático Potência: 380w Garantia: 1 ano (3 meses legais + 9 meses especiais) A Colormaq lança o primeiro eletrodoméstico nacional feito com materiais sustentáveis, marcando um avanço significativo para a sustentabilidade no setor. A linha Ecomax une eficiência, tecnologia e compromisso ambiental.', 990.9, 759.99, NULL, 'Home Appliances > Large Household Appliances > Washing Machines & Dryers', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m76tixqjcfgs38', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F781250043%2F22193811644', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48850841867', 'Bermuda Térmica Compressão Masculina Poliamida Shorts Térmico Santara Premium', 'Bermuda Térmica Esportiva Masculina Compressão Performance Santara A Bermuda Térmica Santara Premium foi desenvolvida para quem busca alto desempenho, conforto e estilo em treinos, corridas e atividades do dia a dia. Produzida com microfibra elástica de alta compressão, garante melhor ajuste ao corpo, sustentação muscular e liberdade total de movimento. O tecido respirável e de secagem rápida mantém a pele seca e fresca, ajudando na regulação térmica mesmo durante treinos intensos. Com modelagem anatômica e tecnologia sem costura, evita atritos e proporciona sensação de segunda pele ? perfeita para academia, ciclismo, corrida, futebol e esportes em geral. Diferenciais: - Tecido de compressão firme e confortável - Regulação térmica e alta respirabilidade - Tecnologia Seamless (sem costura) - Secagem rápida e toque suave - Ideal para treinos e uso esportivo - Design anatômico que valoriza o corpo Tamanhos disponíveis: P | M | G | GG Composição: 92% Poliamida | 8% Elastano Produzida no Brasil com qualidade Santara Premium', 99.99, 28.99, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Bottoms', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mi1xf2birrwh75', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F349198275%2F48850841867', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
