INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22994056943', 'Manopla Câmbio 5 Marchas Onix 2013 A 2019 Encaixe Parafuso', 'Manopla de Câmbio 5 Marchas Chevrolet Onix 2013 a 2019 Tipo B Encaixe Parafuso Enroscado Indústria Brasileira A NAT Indústria disponibiliza aos seus clientes um alto padrão de qualidade na fabricação de peças de reposição e acessórios automotivos. Todas as peças são fabricadas com qualidade original, mantendo sua funcionalidade e melhor custo-benefício. A Manopla de Câmbio da NAT possui uma instalação simples e intuitiva. A Manopla de Câmbio é confeccionada em PVC de alta resistência e acabamento emborrachado. Aplicação: - Onix 2013 a 2019 Tipo de Encaixe: - Encaixe Parafuso Enroscado Informações: - Qualidade de Original - Tamanho e peso idênticos ao Original - Produto Nacional - Ótimo acabamento Emborrachado - Instalação simples, rápida e intuitiva - Para Câmbio Manual. Garantia: - 3 meses Cor do Produto Pode haver divergência na tonalidade do produto vista no site e a do produto ao vivo, devido a calibragem de brilho do monitor das telas de computadores e celulares. Não nos responsabilizamos por essa alteração. - Imagens meramente ilustrativas Garantia do vendedor: 3 meses', 69.97, 69.97, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Internal Parts', 'https://cf.shopee.com.br/file/sg-11134201-7rauc-maele3bfdv2odc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F353832716%2F22994056943', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18397763752', 'Sylvanian Families Conjunto Quiosque De Hambúrguer - Epoch', 'O kit Hamburger Stand contém uma lanchonete em forma de hambúrguer, além de uma bicicleta para entrega e o pai Gato de Leite. Desmonte o hambúrguer grande para criar vários itens, como uma barraca de hambúrguer, mesa e cadeiras. Você pode se divertir grelhando hambúrgueres e fritando batatas. Vem com mais de 30 acessórios, incluindo hambúrgueres fofos com pães em formato de orelha de gato e bebidas. A barraca de hambúrguer pode ser configurada de duas maneiras: modo de loja e modo de transporte. A barraca de hambúrguer pode ser acoplada à bicicleta de entrega e levada para toda parte. O pai Gato de Leite, dono da barraca, entrega hambúrgueres deliciosos para todos os moradores. Ele está vestindo um uniforme especial de lanchonete que só está disponível com este conjunto. Especificações: Marca: Epoch Referência: 5757 Cód. Barras: 5054131057575 Idade recomendada: 3+ anos. Funciona a bateria ou pilha? Não Dimensões do Produto na Embalagem: 18 x 29 x 12 cm Peso: 522 g Certificado Inmetro: 004530/2019 Garantia do Fabricante: 3 meses Garantia do Vendedor: 7 dias Produto Novo, Original, Lacrado e Acompanhado de Nota Fiscal', 459.99, 359.99, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/br-11134207-7r98o-ly6lns73pi8l12', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1162387686%2F18397763752', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
