INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23796960132', 'Kit Conexão Para Gazebo Tenda Ráfia 3,00x3,00 11 Peças Reparo', 'KIT PEÇAS DE REPOSIÇÃO PARA GAZEBO 3X3 METROS Marca: MOR Para manter a vida útil do seu gazebo, esse Kit Reposição Peças Gazebo é perfeito! Ele possui conectores e sapatas em polipropileno, ganchos de aço e corda de poliéster, materiais de qualidade que são tudo o que você precisa para deixar os eventos em família mais seguros e confortáveis. Indicado para gazebos de topo e base 3 metros, o Kit acompanha dois conectores para canto, um conector central, quatro ganchos de fixação, duas cordas para amarrar e duas sapatas para pés que vão ajudar a manter a estrutura do seu gazebo sempre conservada e firme. Material Polipropileno (( Peças do kit )) 04 Ganchos de fixação - 15cm x Ø3,7cm 01 Conector central - 9cm x 9cm x 3,8cm 02 Conectores para canto - 10,3cm x 8cm x 9,5cm 02 Cordas para amarrar - 3m 02 Sapatas para pés - 6,3cm x 3,3cm Para gazebos com: Topo e Base: 3,00 m x 3,00 m Peso 192,00 Gramas', 42.9, 38.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Camping & Hiking', 'https://cf.shopee.com.br/file/sg-11134201-7rbnk-lljno47iqmip51', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F415129379%2F23796960132', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
