INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23697475387', 'Sensor Rotação Fiat Strada 1998 a 2003 - 168077 - 1803', 'Sensor Rotação Fiat Strada 1998 a 2003 168077 1803 Motor 1.5 8v Álcool/Gasolina - (3 Vias) (Comprimento do Cabo - 48 cm) Sua principal função é medir a velocidade de rotação do motor (RPM), através de pulsos digitais captados em cima da roda dentada (fônica) do virabrequim do mesmo motor repassando essa informação a central. Ele é um componente vital no sistema de injeção eletrônica do seu carro a ponto de, em alguns modelos, o carro sequer ligar. Este sensor é um ímã enrolado em uma bobina dentro de um recipiente cilíndrico e selado. Ou seja: não tem conserto, levando a troca da peça quando apresentar defeito.', 95.69, 95.69, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/sg-11134201-7rd4z-luia5h07r3lp91', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23697475387', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23398005347', 'Pastilha Freio Renault Logan 2008 a 2017 - 513456 - SYL1357', 'Pastilha Freio Renault Logan 2008 a 2017 513456 SYL1357 (Privilege) - Motor 1.6 8/16v - (Dianteira) (Sistema Girling) (Sem Alarme) As pastilhas de freio são essenciais para a frenagem do automóvel, pois, são responsáveis por 70% desse trabalho. Elas fazem as rodas pararem, ao entrarem em contato com o disco de freio. É bom verificar a espessura das pastilhas a cada 5 mil quilômetros, mas recomenda-se determinar a periodicidade de troca adequada manual do veículo. Importante lembrar a substituição delas pode variar de acordo com o uso do veículo. A vida útil das pastilhas é de 25 a 35 mil quilômetros rodados, em média.', 56.33, 56.33, NULL, 'Automobiles > Automobile Spare Parts > Brake System', 'https://cf.shopee.com.br/file/sg-11134201-7rblg-lnsxnm101r5219', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23398005347', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22798077445', 'Cilindro Freio SANTANA 1986/1996 - 50697 - CCR9213', 'Cilindro Freio SANTANA 1986/1996 TRASEIRO ESQ/DIR COM CÂMBIO AUTOMÁTICO (11/16" OU 17,46mm) O Conjunto de Cilindro de Roda é utilizado em veículos cujo sistema de freios é a tambor. Ele aciona os freios na roda quando recebe pressão hidráulica enviada pelo cilindro mestre, assim, as sapatas são empurradas dando o atrito no tambor de freio, fazendo com que a roda freie e pare o veículo.', 36.51, 36.51, NULL, 'Automobiles > Automobile Spare Parts > Brake System', 'https://cf.shopee.com.br/file/sg-11134201-7rblp-lmqkdm8b0h5c38', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22798077445', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18897433262', 'Filtro Óleo Ford Fiesta 1997 a 1999 - 166165 - WUNI0001', 'Filtro Óleo Ford Fiesta 1997 a 1999 166165 WUNI0001 (CLX) - 1.4 16V Zetec - Gasolina - Mecânico Basicamente, os filtros lubrificantes devem atender às funções de reter todos contaminantes que possam causar danos ao perfeito funcionamento do motor, mantendo as características de estrutura do óleo, uniformidade de circulação e eficiência no período de uso pelo motor. O Filtro do Óleo retém os contaminantes contidos no sistema de lubrificação, principalmente os abrasivos (metais) , provenientes do atrito das partes móveis do motor que permanecem em suspensão no óleo lubrificante.', 25.05, 25.05, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7repi-m8zkh6b16ls0a8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F18897433262', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18599072582', 'Correia Poly V Alternador POLO 12 13 14 - 15200 - 6PK1699', 'Correia Poly V Alternador POLO 12 13 14 Produto novo, com garantia e Nota Fiscal! Correia Poly V - 6PK1699 POLO - 1.6 VHT Anos: 2012 2013 2014 Utilização: Virabrequim / Alternador / Direção Hidráulica / Ar Condicionado As correias Multi V permitem a transmissão não positiva de binários. A sua função: O acionamento do alternador, ventoinha, bomba de água, compressor do ar condicionado e direção assistida nos motores modernos. As correias Multi V estão sujeitas a envelhecimento e desgaste. Por essa razão, têm de ser controladas e substituídas a intervalos regulares. Os intervalos de controle e de substituição são sempre estabelecidos pelo fabricante do veículo e devem ser respeitados.', 112.05, 112.05, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rfih-m9jk0qv0lup5fd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F18599072582', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
