INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209779312', 'Shark Up Black Gel - 10 Sachês 30g Açaí Com Banana - Shark Pro', 'O Shark Up Shark Pro é um gel energético desenvolvido para oferecer energia rápida, reposição de eletrólitos e suporte à performance em treinos intensos ou competições longas. Sua formulação prática e eficiente garante disposição extra nos momentos em que você mais precisa, sendo ideal para corredores, ciclistas, triatletas e praticantes de atividades de endurance. Com textura leve e sabores agradáveis, o Shark Up é fácil de consumir durante o esforço físico, evitando desconfortos e mantendo sua performance em alta. Ingredientes: Maltodextrina, água deionizada, amido de milho ceroso, nicotinamida (niacina), D-pantotenato de cálcio (ácido pantotênico), cloridrato de piridoxina (vitamina B6), riboflavina (vitamina B2), cianocobalamina (vitamina B12), citrato de sódio, ácido cítrico, aroma idêntico ao natural (açaí com banana), conservadores (sorbato de potássio e benzoato de sódio) e edulcorantes (sucralose, aspartame, ciclamato de sódio, acessulfame de potássio, sacarina sódica). Aromatizado artificialmente.', 39.9, 29.9, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/br-11134207-820ln-mnlpza5ozll0d9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1778743739%2F58209779312', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
