INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58261486514', 'Aditivo Diesel Bardahl Agro D600 500ml Trator Caminhão', 'BARDAHL AGRO D600 500ml — Aditivo descarbonizante para Diesel e Biodiesel APLICAÇÃO: Tanques de combustível (diesel ou biodiesel) de veículos e máquinas, como motores agrícolas, equipamentos de terraplenagem, geradores, tanques e reservatórios subterrâneos, além de veículos e máquinas que ficam parados por períodos acima de um mês. BENEFÍCIOS: • Descarbonizante: limpa injetores e remove resíduos de carbono • Bactericida e fungicida: elimina imediatamente o desenvolvimento de bactérias • Prolonga a vida útil do diesel por até 180 dias • Protege contra a corrosão tanque, tubulações, bomba injetora e válvulas • Separa água do diesel, facilitando drenagens MODO DE USO: Na taxa de Tratamento de Choque, adicionar 500 mL para 1.000 L de diesel. Na taxa de Manutenção, usar 500 ml para até 2.500 L de diesel. Embalagem: 1 frasco de 500ml Marca: Bardahl (Promax) — Original e Certificado', 94.9, 94.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-823pi-mopkt1rsyt58ce', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1819345424%2F58261486514', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '25141569145', 'KIT Pincéis de Silicone Grande Pincel Culinário Cozinha Utilidades Pincel para Azeite Confeitaria', 'O **KIT 3 Pincéis de Silicone Grande** é perfeito para quem busca praticidade e eficiência na cozinha. Ideal para pincelar azeite, manteiga, coberturas ou até mesmo glacês em suas receitas de confeitaria, esse kit de pincéis proporciona uma aplicação uniforme e precisa. Os pincéis possuem cerdas de silicone duráveis e resistentes ao calor, tornando-os ideais para uso em altas temperaturas, além de serem fáceis de limpar e manter. Versátil, pode ser utilizado para diversas preparações, como pincelar carnes, assados, massas, entre outras delícias. Com design ergonômico e material de alta qualidade, esses pincéis são essenciais para quem ama cozinhar e confeitar com praticidade e perfeição. ESCOLHA NA VARIAÇÃO SUA MEDIDA: 21,5 CM X 4,5 CM 18 CM X 3 CM', 23.9, 17.01, NULL, 'Home & Living > Kitchenware > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m6e161w7alvr24', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436723291%2F25141569145', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19598545143', 'Brinquedos de Cozinha Kit Fogão De Brinquedo Fogãozinho De Cozinha Infantil', 'DESCRIÇÃO DO PRODUTO:_x000D_ _x000D_ Com certeza qualquer criança vai adorar ganhar esse lindo fogãozinho além de usar a imaginação, é um brinquedo que estimula a brincadeira._x000D_ _x000D_ ESPECIFICAÇÕES:_x000D_ Idade recomendada: acima de 3 anos._x000D_ Tamanho (alt x larg): 4 cm x 18 cm_x000D_ Material/Composição: Polipropileno._x000D_ Fornecedor: Altimar_x000D_ CERTIFICAÇÃO: 07593/2020 OCP 0098._x000D_ _x000D_ _x000D_ As cores apresentadas podem sofrer variações de tonalidade de acordo com a configuração do monitor.', 37.99, 27.99, NULL, 'Mom & Baby > Toys > Pretend Play', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m0orf9rmj2cgf9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436723291%2F19598545143', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
