INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40267129862', 'Botijão Térmico Garrafão Aspen 9 Litros Vermelho Soprano', 'Botijão Isotérmico com Torneira 9 Litros Vermelho Aspen Soprano 09000.0017.17 Botijão térmico 9 litros com design moderno, pés de apoio e porta copos retráteis. Botijão térmico com torneira prática para servir, alça de alta resistência para transporte e bocal largo para facilitar o abastecimento de gelo ou líquidos quentes e frios. Este modelo de Botijão térmico possui isolamento em poliuretano (PU) e é livre de Bisfenol (BPA Free). A opção ideal para os seus clientes que buscam por praticidade e durabilidade. Saiba ainda mais sobre isotérmicos acessando a categoria "Bem estar e saúde" no nosso blog! Eficiência Térmica: Quente - 10 horas Frio - 10 horas Principais características: Capacidade 9 Litros Torneira para servir Bocal largo Alça para transporte Isolamento térmico em Poliuretano (PU) BPA free Outras características: Dimensões do produto: 31 x 27,5 x 31cm Peso: 1,840kg Material: Polietileno de Alta Densidade (PEAD) + Poliuretano (PU) Código interno de referência: 09000.0017.17 Garantia: 90 dias contra defeitos de fabricação', 139.9, 119.9, NULL, 'Home & Living > Dinnerware > Water Bottles & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-824gb-mpe930mo8ikt5e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F844004880%2F40267129862', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41313844232', 'Anel de Prata 95 Infinito e Detalhado', 'Anel de Prata 925 Infinito e Detalhado: Elegância e Simbolismo O Anel de Prata 925 Infinito e Detalhado é uma joia delicada e cheia de significado, perfeita para quem deseja unir estilo e simbolismo em um acessório. Com design inspirado no símbolo do infinito, representa continuidade, amor eterno e boas energias. Confeccionado em Prata 925 de alta qualidade, garante brilho duradouro e resistência, sendo ideal para complementar qualquer look. Especificações do Anel Tamanho do Infinito: 6mm Largura: 1mm Peso Médio: 0,5g Material: Prata 925 Destaques do Anel Design delicado com símbolo do infinito, representando amor eterno e continuidade. Produzido em Prata 925 de alta qualidade, garantindo durabilidade e brilho constante. Leve e confortável, ideal para uso diário ou ocasiões especiais. Simbolismo e Estilo em um Único Acessório O Anel de Prata 925 Infinito e Detalhado é perfeito para quem busca um acessório que combine delicadeza, elegância e significado. Ideal para presentear ou para uso pessoal, adiciona um toque especial a qualquer visual. Cuidados com o Anel Evite contato com produtos químicos para preservar o brilho da prata. Guarde em local seco e seguro para evitar arranhões e oxidação. Limpe regularmente com flanela macia para manter o brilho e a beleza do anel. Adicione Significado e Sofisticação ao Seu Estilo Inclua o Anel de Prata 925 Infinito e Detalhado em sua coleção e experimente um acessório elegante e simbólico, que valoriza qualquer look com charme e sofisticação.', 58.0, 43.0, NULL, 'Fashion Accessories > Rings', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mdkjk5v2gam167', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328147687%2F41313844232', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21699308511', 'Colar Feminino de Prata 925 Folha com zircônia', 'Colar Feminino de Prata 925 Folha com Zircônia Descubra a elegância do Colar Feminino de Prata 925 Folha com Zircônia. Um colar encantador com corrente Veneziana delicada e pingente de folha adornado com uma deslumbrante zircônia. Perfeito para adicionar um toque de sofisticação ao seu visual. Especificações: Tamanhos: 40cm, 45cm, 50cm, 60cm, 70cm Modelo da Corrente: Veneziana Espessura: 0.6mm Tamanho do Pingente: 11mm Peso do Colar: 2g, 2.1g, 2.7g, 3g, 3.3g Material: Prata 925 Adicione Elegância ao Seu Visual O Colar Feminino de Prata 925 Folha com Zircônia é uma escolha refinada para quem busca um toque de elegância e estilo. Seja para uso diário ou para ocasiões especiais, este colar é uma expressão de sofisticação. Descubra Mais na Aqua Joias Explore nossa coleção completa de colares de prata 925 na Aqua Joias e descubra mais peças exclusivas e cheias de significado.', 84.2, 71.57, NULL, 'Fashion Accessories > Necklaces', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lydtlfvn4xd1f1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328147687%2F21699308511', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
