INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '25543160829', 'Recadinho Rolo Nota Adesiva em Rolo Roller Notes c/ Dispenser 12,5mmx8mm Sortido Escritório Escolar', 'O Recadinho Rolo Nota Adesiva em Rolo Roller Notes c/ Dispenser 12,5mmx8mm Sortido é uma opção prática e colorida para facilitar sua organização no dia a dia. Com tamanho compacto de 12,5mm x 8mm, essas notas adesivas são perfeitas para recados rápidos, lembretes e pequenas anotações, seja no escritório, na escola ou em casa. O dispenser incluso garante que as notas fiquem organizadas e sejam facilmente retiradas, evitando bagunça e desperdício. Disponível em cores sortidas, o produto adiciona um toque divertido e prático ao seu ambiente, permitindo que você se organize de forma eficiente e estilosa. Ideal para quem busca agilidade e criatividade nas tarefas cotidianas!', 23.9, 17.01, NULL, 'Stationery > Notebooks & Papers > Memo & Sticky Notes', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m7tfbgufly1gd0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436723291%2F25543160829', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23499242948', 'Kit 2 Truly Wanpy Petisco Sachê para Gatos Sabor Frango e Camarão 85g', 'PRODUTO ORIGINAL COM NOTA FISCAL! - - - - - APRESENTAÇÃO: COMBO 2 x G Wanpy Sache de Frango e Camarao 85G - - - - - - - - - - DESCRIÇÃO: Muito mais do que um petisco, um momento de conexão entre você o seu pet! Os Sachês Super Premium de Frango e Camarão são preparados com ingredientes selecionados e sem adição de corantes ou conservantes artificiais. promovem uma digestão saudável, aumentam a ingestão hídrica e são facilmente absorvidos pelo organismo do seu felino, proporcionando uma opção completa nutritiva e saborosa. Sua fórmula é enriquecida com vitaminas essenciais (A, B2, B3, B5, D3 e E), promovendo a saúde e o bem-estar do seu MIAUmigo. - - - - - MODO DE USO: Ofereça a recomendação diária descrita na embalagem ou sempre que necessário para agrado do seu pet! Tal petisco não substitui o alimento comleto :) . - - - - - - - - - - Enviamos o seu pedido o quanto antes possível! Agradecemos a preferência.', 63.7, 32.81, NULL, 'Pets > Pet Food > Cat Treats', 'https://cf.shopee.com.br/file/br-11134207-81z1k-min2b7rtlhc28f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442964228%2F23499242948', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58202148596', 'Truly Wanpy Petisco Creamy para Gatos Sabor Frango e Cenoura 90g', 'PRODUTO ORIGINAL COM NOTA FISCAL! - - - - - APRESENTAÇÃO: 1 x G Wanpy Creamy Sache Frango Cenoura 90G - - - - - - - - - - DESCRIÇÃO: Muito mais do que um petisco, um momento de conexão entre você o seu pet! Os Creamies de Frango e Cenoura promovem um aumento na ingestão hídrica dos MIAUmigos, com diversas opções saborosas. Você pode adicionar o creamy junto com a ração seca, ou oferecer diretamente para o gato. O formato de tubo da embalagem permite que o gatinho consuma o petisco direto na embalagem, o que faz dele o aliado perfeito para momentos como cortar as unhas, dar medicamentos, ou até mesmo promover um momento de conexão entre você e seu pet. Possuem vitaminas em sua composição, e são livres de corantes ou conservantes artificiais. Cremoso, nutritivo, irresistível e muuuito maior! - - - - - MODO DE USO: Ofereça a recomendação diária descrita na embalagem ou sempre que necessário para agrado do seu pet! Tal petisco não substitui o alimento comleto :) . - - - - - - - - - - Enviamos o seu pedido o quanto antes possível! Agradecemos a preferência.', 40.5, 20.86, NULL, 'Pets > Pet Food > Cat Treats', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mibyjr0ia70j2c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442964228%2F58202148596', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
