INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42554863072', 'Esmerilhadeira Angular Hammer GYEM7101 4.1/2" 710W 220V', 'A Esmerilhadeira Angular GYEM7101, possui ótima ergonomia e um motor potente de 710W. Esta ferramenta elétrica destina-se a operações de esmerilhamento e corte de metais e outros materiais. É ideal para desbaste em peças metálicas, acabamentos sobre soldas, remoção de rebarbas de peças fundidas, limpeza de superfícies enferrujadas ou com tinta. Possui trava para uso contínuo, permitindo a utilização de maneira contínua sem a necessidade de pressionar o gatilho. E sua empunhadura lateral dá maior conforto e segurança na hora de trabalho. CARACTERÍSTICAS: - Máquina 100% rolamentada - Rotação (sem carga): 12000 rpm - Diâmetro de disco: 4.1/2" (115mm) - Trava para uso contínuo - Empunhadura lateral DADOS TÉCNICOS: - Voltagem: 220v - Potência: 710W - Rotação (rpm): 12.000/min - Capacidade da esmerilhadeira (disco): 4.1/2" - 115 mm - Rosca do eixo: M 14 - Tipo de velocidade: Fixa - Número de posições de ajuste do punho: 2 posições - Ajuste do cabo da esmerilhadeira: Fixo - Medidas (AxLxP): 10,5x30,5x10,5 cm - Peso: 1,845 Kg - Garantia: 6 meses CONTEÚDO DA EMBALAGEM: - 01 Esmerilhadeira angular EM-710-1 - 01 Punho auxiliar - 01 Chave de porca para fixação - Manual de instruções Aqui na Loja O Pescador de Ofertas, você pode concluir a sua compra facilmente, com toda a segurança e a sua entrega é garantida. Aqui você está em 1º Lugar!', 209.9, 209.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7ravo-mb3xhj0appw1b5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F785052377%2F42554863072', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41206309609', 'Cute & Comfy Coloring Book for Adults - Special Edition - Livro de Colorir Adulto', '-Se colorir é o seu hobby, o Cute & Comfy - Coloring Book for Adults Special Edition é a escolha perfeita para você! Sucesso no TikTok, este livro traz 32 ilustrações encantadoras para preencher com lápis de cor ou marcadores, e ainda acompanha 6 marcadores de ponta dupla, ideais para dar vida às suas criações com cores vibrantes. 32 ilustrações originais: Cada página é desenhada à mão, pronta para receber sua criatividade. Desenhos amplos e de fácil preenchimento: Proporciona uma experiência relaxante e envolvente. Acompanha 6 marcadores de ponta dupla: Perfeitos para detalhes precisos e preenchimentos suaves. Tamanho confortável (21,0 x 21,0 cm): Ideal para manuseio prático e fácil transporte. Alta resolução: Impressões nítidas e detalhadas, garantindo um resultado incrível. Deixe sua criatividade florescer e desfrute de momentos de tranquilidade com o Cute & Comfy! Um presente perfeito para você, familiares ou aquele amigo que também ama colorir. Combine fofura, leveza e inspiração em cada página e torne suas sessões de pintura ainda mais especiais!', 39.99, 14.9, NULL, 'Books & Magazines > Books > Sticker & Colouring Books', 'https://cf.shopee.com.br/file/sg-11134201-7ra0k-mbh4es3zdu8m2d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F482840775%2F41206309609', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22095667378', 'Aqua Book Floresta Encantada |Unicórnios', 'Os Unicórnios mais fofos da Floresta Encantada aguardam pelas suas cores de uma forma diferente e muito divertida usando a caneta mágica! Use a caneta nos desenhos e veja a mágica acontecer!', 29.9, 19.95, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7qvfp-lgl54ahn721xf7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F482840775%2F22095667378', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23197608625', 'Advogado de Defesa - Irving Stone', 'Quando Irving Stone se dispôs a levantar os dados para escrever a Biografia de Clarence Darrow, sabia que a vida que iria contar era muito mais que a história de um homem. Tudo isso está habilmente narrado em Advogado da Defesa, em que o autor de Agonia e Êxtase alia à sua altíssima categoria de romancista a exação do historiador consciente, produzindo uma biografia que, por vários motivos, leva o leitor preso da primeira à última página, sem um momento de cansaço.', 86.0, 10.0, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/br-11134201-820lt-mqy5nzf8wx6s46', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F482840775%2F23197608625', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
