INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58201166703', 'Camiseta Feminina Texturizada Calvin Klein Sport - Preto', 'EXPLORE O MELHOR DO CONFORTO E DESEMPENHO Projetada para mulheres que buscam o equilíbrio perfeito entre estilo e desempenho, a Camiseta Feminina Calvin Klein Sport é a melhor escolha para qualquer atividade. Confeccionada com tecnologia Dry-Fit, garante que você permaneça seca, confortável mesmo nos treinos mais intensos e pronta para enfrentar o Sol sem preocupações. CARACTERÍSTICAS • Tecnologia Dry-Fit • Proteção UV UPF 15 • Feito de poliamida creponada • Suave contato com a pele • Tecido antimicrobiano que evita odor • Transfer frontal e traseiro • Alta respirabilidade • Secagem rápida • Fácil cuidado RECOMENDAÇÕES • Lavagem à mão • Não alvejar • Não secar em tambor • Secagem em varal à sombra • Não passar • Não limpar a seco • Limpeza à úmido profissional', 199.0, 199.0, NULL, 'Women Clothes > Others', 'https://cf.shopee.com.br/file/sg-11134201-820nz-mnegalse93icb8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1593932205%2F58201166703', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209452659', 'Flor de Ypê Flor de Maçã e Framboesa Sabonete em Barra', 'O sabonete Flor de Ypê Flor de Maçã e Framboesa proporciona um toque cremoso ao seu banho, deixando a sensação de pele fresquinha e suave. Sua fórmula dermatologicamente testada combina óleos essenciais e glicerina, garantindo cuidado e perfumação para a pele. Ideal para uso diário no corpo e nas mãos. Molhe a região desejada, ensaboe normalmente e enxágue suavemente.', 2.99, 2.99, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/sg-11134201-8258p-mqnelwf8a13638', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555057%2F58209452659', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
