INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41763831037', 'Espelho Lopazzi Corpo Inteiro Base Reta 150x60cm Retangular Oval Orgânico Dourado Com Suporte de Chão', 'Espelho Corpo Inteiro 150x60 – Design Exclusivo com Sofisticação para Seu Ambiente Transforme seu espaço com o Espelho Corpo Inteiro de 150cm, uma peça única que combina design contemporâneo e funcionalidade. Seu formato exclusivo, com topo arqueado e base reta com cantos arredondados, cria um visual elegante e arquitetônico ideal para banheiros, salas, quartos, closets e ambientes comerciais. · Formato exclusivo · Moldura metálica resistente com pintura epóxi premium · Reflexo perfeito, sem distorções · Vidro de alta qualidade com 3 mm de espessura · Acompanha suporte de chão e suporte de parede inclusos · Disponível em diversas cores e tamanhos para se adaptar ao seu projeto Adicione um toque autoral à sua decoração com o Espelho Corpo Inteiro — sofisticação em cada detalhe. · Destaque: Adiciona amplitude e iluminação ao espaço · Aplicação: Renovação de ambientes e projetos de arquitetura · Instalação: Espelho pensado e projetado para ser mantido estável em apoio ou fixado na parede · Produto de alta qualidade, pronto para envio com embalagem reforçada · Atendimento especializado e suporte total ao cliente Ficha Técnica · Modelos disponíveis: Magnus, Arcos, e Urban com suporte de chão e parede Solis: Apenas com suporte de parede · Dimensões: 150cm x 60 cm · Espessura: 3 mm · Peso: 9 kg · Material: Vidro lapidado (não é acrílico) · Instalação: suporte de parede e suporte de chão · Garantia: 90 dias direto com o vendedor Frete Barato e Confiável para todo o Brasil: · Parceria com empresas de logística confiáveis · Opção de frete econômico para reduzir os custos de envio · Rastreamento do pedido disponível para acompanhamento · Entrega rápida e eficiente para