INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22397432710', 'KEMEI-KM-2192 Depilador recarregável profissional, depilação 6 em 1 portátil Depilador multiuso 2192', 'Esta depiladora avançada oferece a experiência de remoção de pêlos mais rápida de sempre, graças à sua série de discos com pinça tripla que rodam a uma velocidade sem precedentes, garantindo uma aderência firme até mesmo aos pêlos mais finos, tão curtos como 2 mm. 6 funções em 1 depiladora com cabeças intercambiáveis: 1- Depilador: Possui 40 pinças para capturar os pelos mais finos e curtos. 2- Barbeador e Aparador: Ideal para áreas sensíveis. 3- Massageador: Proporciona uma massagem profunda e relaxante. 4- Escova de Limpeza Facial: Limpa e esfolia a pele do rosto. 5- Removedor de Calos nos Pés: Suaviza os pés em segundos. 6- Aparador de nariz e sobrancelha: Perfeito para depilação precisa do nariz, moldar e pentear suas sobrancelhas sem esforço. Sistema de depilação eficiente: Remove os pelos pela raiz, garantindo resultados duradouros. Discos Tri-Pinça Suaves: Remova os pelos sem puxar ou irritar a pele. Cabeça Depiladora Extra Larga (30mm): Acelera o processo de depilação. Visor LCD: O visor LCD nítido alerta quando o carregamento é necessário. Uso úmido e seco sem fio: use-o confortavelmente dentro ou fora do chuveiro. Punho ergonômico: Projetado para um manuseio fácil e confortável. 100% resistente à água: Adequado para uso na banheira ou no chuveiro. Recarregável: carregue-o convenientemente com o cabo de dados USB incluído. Adequado para todas as partes do corpo: versátil e eficaz em várias áreas do corpo. Leve e portátil: perfeito para viagens e uso em trânsito.', 229.99, 166.51, NULL, 'Beauty > Beauty Tools > Hair Removal Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lto12z5ed3wf54', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fsh