INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22793691626', 'Cama Montessoriana Infantil de Chão com Cercado Linha Encanto Branco - Completa Móveis', 'Cama de Chão Montessoriana de Solteiro Linha Encanto Branco - Completa Móveis A Cama de Chão Montessoriana de Solteiro da Linha Encanto da Completa Móveis é perfeita para estimular a autonomia e criatividade das crianças desde a primeira infância. Com design lúdico e seguro, possui grades de proteção que garantem mais tranquilidade para os pais. Ideal para compor um ambiente aconchegante e funcional, seguindo o método Montessori. NÃO ACOMPANHA COLCHÃO! Benefícios Estímulo à Independência: Facilita o acesso da criança à cama, incentivando autonomia. Design Seguro: Grades de Proteção Laterais proporcionam mais segurança no dia a dia. Estética Moderna: Acabamento Fosco e estrutura elegante para um ambiente harmonioso. Fácil de Montar: Sistema intuitivo de fixação com Parafusos, Cavilhas e Minifix. Praticidade na Limpeza: Superfície resistente, fácil de higienizar com pano úmido. Características Material: MDP com Acabamento Fosco. Dimensões (L x A x P): 84 x 45 x 192 cm. Peso Suportado: Até 80 kg. Estrado: Lastros em MDF cru. Colchão Recomendado: Solteiro (188 x 78 cm). Montagem: Necessária (nível de dificuldade baixo). Garanta já a Cama Montessoriana Encanto e proporcione mais liberdade e segurança para o desenvolvimento do seu filho!', 489.9, 419.9, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-7rbn4-m5x8kiagr9t7ad', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F390327339%2F22793691626', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
