INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23597491214', 'Shampoo Sem Sal Hidratação Jacques Janine Just One Min 300ml', 'O SHAMPOO JUST ONE MINUTE, FOI DESENVOLVIDO PARA LIMPAR E RESTAURAR A SAÚDE E A VITALIDADE DOS CABELOS DE FORMA ÚNICA, POIS CONTÉM EM SUA FÓRMULA O REVOLUCIONÁRIO AMINO TECH SYSTEM, UM COMPLEXO DE AMINOÁCIDOS EXCLUSIVO QUE REPARA OS FIOS EM APENAS UM MINUTO. Modo de Uso APLIQUE NO CABELO MOLHADO E MASSAGEIE SUAVEMENTE O COURO CABELUDO COM A PONTA DOS DEDOS ATÉ OBTER ESPUMA. ENXÁGUE. REPITA SE NECESSÁRIO. Composição AQUA, SODIUM LAURETH SULFATE, COCAMIDE DEA, GLYCERIN, COCOAMIDOPROPYL BETAINE, GLYCOL DISTEARATE, GUAR HYDROXYPROPYLTRIMONIUM CHLORIDE, PHENOXYETHANOL, SODIUM CHLORIDE, PARFUM, LACTIC ACID, DISODIUM EDTA, BENZYL SALICYLATE, POLYQUATERNIUM-10, LINALOOL, HEXYL CINNAMAL, COUMARIN, CI 77499, IMIDAZOLIDINYL UREA, HYDROLYZED WHEAT PROTEIN, ARGININE, ITACONIC ACID, ALANINE, HYDROLYZED CORN PROTEIN, HYDROLYZED SOY PROTEIN, LYSINE, ASPARTIC ACID, LINUM USITATISSIMUM (LINSEED) SEED EXTRACT, PANTHENOL, SODIUM PCA, LEUCINE, SERINE, PROLINE, HYDROXYPROLINE, PHENYLALANINE, Especificações Técnicas: COR-02 / A-01 / MOD-02', 66.9, 59.9, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-7rdy3-m0acxsgibuw1c2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1248946294%2F23597491214', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259226629', 'Bota Feminina Cano Baixo Mississipi Mc511', 'A BOTA FEMININA CANO BAIXO MISSISSIPI MC511 é um clássico que nunca sai de moda. Seu design elegante e conforto garantido fazem dela a escolha perfeita para completar qualquer look. Feita com materiais de alta qualidade, essa bota é sinônimo de durabilidade e estilo em todas as ocasiões. Adquira já a sua e faça sucesso por onde passar!. MODELO: 0645511 REFERENCIA: MC511 MARCA: Mississipi MATERIAL DA PALMILHA: PU MATERIAL DA SOLA: Borracha MATERIAL INTERNO: Têxtil ACABAMENTO: Colado/Costurado GÊNERO: Female GRUPO DE IDADE: Adult MEDIDA DO CANO: 13 cm aproximadamente CIRCUNFERÊNCIA DO CANO: 30 cm aproximadamente MATERIAL DO SAPATO: Sintetico MEDIDA DO SALTO: 6,5 cm aproximadamente Altura do Produto: 11 Largura do Produto: 28 Comprimento do Produto: 31 Peso do Produto: 970.00', 203.99, 203.99, NULL, 'Women Shoes > Boots > Fashion Boots', 'https://cf.shopee.com.br/file/sg-11134201-820nz-mna9qwc05edfeb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F784810315%2F58259226629', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20697682241', 'Jogo 4 Pneus Pirelli Aro 14 P400 EVO 175/65R14 82H', 'Marca: PIRELLI Modelo: P400 EVO Medida: 175/65R14 Largura: 175 Perfil: 65 Tamanho de Aro: 14 Índice de peso: 82 - 475 kg Índice de velocidade: H - 210 km/h Tipo de Veiculo: CARRO Tipo de terreno: HT RunFlat: Não Sidewall: BSW LETRAS PRETAS Extra Load: Não Desenho: ASSIMÉTRICO UTGQ: N/A Adesão à àgua: E Eficiência energética: E Ruído externo: 73 *Nossas vendas são realizadas apenas para consumidor final, sendo vetada a comercialização para CNPJ de revendedores.O pneu Pirelli P400 Evo é ideal para quem precisa de um pneu com ótimo desempenho em segurança e conforto, sem abrir mão da dirigibilidade. Sua banda de rodagem assimétrica é capaz de proporcionar excelente escoamento da água quando roda em piso molhado, e também exercer amplo contato com o solo, aumentando a estabilidade e aderência. É um pneu voltado a carros compactos, com ótima durabilidade e longa vida útil, proporcionando economia e maior espaço entre as trocas de pneus. Sobre a marca Pirelli A Pirelli nasceu na Itália há mais de 100 anos, em Milão. Com longa tradição na construção de pneus, a marca produz soluções para carros, motos, tratores, caminhões e ônibus e possui fábricas espalhadas pelo mundo. A Pirelli é a atual fornecedora de pneus da Fórmula 1, a principal categoria do automobilismo mundial, e possui longa tradição em pneus de alto desempenho.', 1727.48, 1727.48, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rdwf-lxlj4n9ibxage1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F20697682241', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
