INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22094554330', 'Saia de Renda Longa Feminina Flor Forrada Evangélica Elegante Moda 3RD SD1829', 'Uma peça moderna, confortável e super versátil — perfeita tanto para o dia a dia quanto para ocasiões especiais. Com caimento impecável e tecido de alta qualidade, ela garante estilo, praticidade e muito bem-estar em qualquer momento. Nada melhor do que investir em looks que elevam sua autoestima e destacam seu estilo todos os dias. Garanta já o seu! 📌 Tecido Renda(Forrada) - Possui elástico na cintura* Modelo veste tamanho M (Altura 1,60m — 60kg) 📏Medidas Tamanho M(36-38) Circunferência da Cintura:64cm Comprimento : 90cm Tamanho G(40-42) Circunferência da Cintura:68cm Comprimento : 91cm Tamanho GG(44) Circunferência da Cintura:72cm Comprimento : 92cm Atenção: Medidas referentes a peça sem esticar* OBSERVAÇÕES 1) Recomendamos pedir sua numeração habitual. A modelagem é padrão — não veste menor nem maior. 2) Em caso de dúvidas, sugestões ou qualquer problema, nos chame no chat da loja! Atendemos também pedidos no atacado. 3) Trabalhamos somente com produtos importados e de ótima qualidade. Como não há reposição imediata, nossos estoques são limitados — aproveite enquanto temos! 4) Siga a 3RD Fashion e conheça todas as novidades que preparamos com muito carinho para você! ⭐ Muito obrigado pelo seu bom gosto! Esperamos oferecer a melhor experiência de compra possível.', 95.0, 95.0, NULL, 'Women Clothes > Skirts', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mfv6oktakxds98', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F393568956%2F22094554330', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22719138763', 'Bola Futsal Penalty Rx 100 XXIII Infantil Sub 9 - Selo CBFS', 'Indicado para categoria Sub 11 / Sub 9 Chegou a hora de treinar suas habilidades dentro das quadras de salão e se tornar um craque no futuro com a Bola Futsal Penalty Rx 100 XXIII. Sua construção elimina as costuras, garantindo menor absorção de água durante as partidas em quadras abertas. Além disso, o produto recebe um tratamento térmico com borracha natural, proporcionando maior resistência, uniformidade e estabilidade da bola. E tem mais, por conter camada de amortecimento interno, favorece muito mais conforto ao diminuir o impacto, deixando a bola ainda mais macia. Recomendada pela Confederação Brasileira de Futsal para competições SUB 11 / SUB 9. Benefícios: Menor absorção de água. Resistência e durabilidade. Uniformidade e estabilidade. Tamanho e peso ideal para a categoria Sub-11 e Sub 9 Alguns diferenciais técnicos: A Bola Futsal Penalty Rx 100 XXIII possui miolo lubrificado e substituível, além de bico alongado que envolve a agulha impedindo que perfure a câmara de ar, graças a tecnologia Cápsula SIS. Além disso, a bola possui Câmara 6D, que por ser composto por 6 discos posicionados simetricamente, proporcionam equilíbrio total para você dominar a bola da maneira correta. Peso: 300-330g Circunferência: 52-55cm Gomos: 6 Laminado: PU Construção: Ultra Fusion Câmara: 6D Sistema de Forro: Termofixo Camada Interna: Evacel Processo Extra: Dupla Colagem Miolo: Cápsula SIS Cuidados limpar a bola com escova ou pano limpo levemente úmido com água após utilização secar a bola por completo armazenar em ambiente seco e ventilado não deixar exposta ao sol ou chuva mantê-la sempre calibrada', 149.9, 149.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Soccer, Futsal & Sepak Takraw', 'https://cf.shopee.com.br/file/sg-11134201-7rep9-m29nt5pckwcc89', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F786526144%2F22719138763', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23319136598', 'Bola Handebol Penalty Feminino Suécia H2L Pro X Profissional', 'Mostre e treine suas habilidades com a Bola de Handebol Penalty Suécia H2L Pro X. Desenvolvida para jogos femininos em quadras indoor, a Bola de Handebol H2L Pro X está presente na Federação Mineira de Handebol ( FHM). Indicada para quem procura controle e fixação nas mãos durante os arremessos, além disso, garanta maior equilíbrio e firmeza durante as jogadas e ótimo desempenho para seu time ser campeão! Benefícios: Tamanho e peso ideal para jogos femininos. Estabilidade. Maior controle nos arremessos. Melhor fixação nas mãos. Alguns diferenciais técnicos: A Bola de Handebol Penalty Suécia H2L Pro X é desenvolvida com Câmara Airbility, em que seu sistema de balanceamento garante ótima resistência à retenção de ar. Além disso, o produto é costurado à mão com costuras mais estáveis e resistentes.', 449.99, 449.99, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Soccer, Futsal & Sepak Takraw', 'https://cf.shopee.com.br/file/br-11134207-820m9-mp2bcvg9h3b59c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F786526144%2F23319136598', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20072097485', 'Colher Para Sorvete Brinox - Top Pratic 21,5 cm Aço Inox', 'Seja Bem-Vindo(a) à Mimorada! Colher para Sorvete Brinox Top Pratic 21,5 cm em Aço Inox: Praticidade e Durabilidade na Sua Cozinha A Linha Top Pratic da Brinox traz para a sua cozinha produtos projetados para simplificar as atividades culinárias, combinando praticidade e beleza. A Colher para Sorvete Brinox Top Pratic, fabricada em aço inox, é resistente e durável, proporcionando facilidade no preparo e servindo com elegância. *Principais Características: - Material Resistente em Aço Inox: A colher para sorvete é fabricada em aço inox, um material conhecido por sua resistência, durabilidade e fácil limpeza. Além disso, o aço inox confere um aspecto elegante ao utensílio. - Design Prático e Funcional: A Linha Top Pratic foi projetada para facilitar as atividades na cozinha, e a colher para sorvete não é exceção. Seu design é pensado para proporcionar praticidade no manuseio e servir sorvetes de forma eficiente. - Dimensões Ideais: Com 21,5 cm de comprimento, a colher para sorvete possui dimensões ideais para alcançar sorvetes de diferentes recipientes, tornando o momento de servir mais simples e agradável. - Versatilidade: Além de servir sorvetes, a colher pode ser utilizada para porções de sobremesas e outras delícias, adaptando-se às suas necessidades na cozinha. *Especificações Técnicas: - Comprimento: 21,5 cm - Material: Aço Inox Adquira a Colher para Sorvete Brinox Top Pratic e adicione praticidade e elegância ao seu arsenal de utensílios de cozinha. Seja no dia a dia ou em ocasiões especiais, esta colher é uma escolha funcional e duradoura para servir suas sobremesas favoritas.', 49.99, 38.25, NULL, 'Home & Living > Kitchenware > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lpfi6k8zl93p0b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842996464%2F20072097485', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23720920703', 'Cumbuca Tigela Coza Uno 500 ml Branco - Organização', 'Seja Bem-Vindo(a) à Mimorada! Apresentamos a Cumbuca Coza Uno 500 ml. Seu design moderno e as cores variadas dão um toque especial à decoração, trazendo ainda mais sofisticação e elegância ao servir. DIFERENCIAIS: Coza Uno foi criada para os pratos da culinária oriental. 100% PP, apresenta produtos nas cores preto, branco e vermelho bold. Com super resistência, a peça vai à lava-louças, e suporta temperaturas de -10 a 80°C. Tenha à mesa Coza Uno para servir de forma única seus pratos orientais. MATERIAL: A Cumbuca Coza Uno 500 ml é fabricada em polipropileno de alta qualidade. Tudo isso com o compromisso de sustentabilidade, pois as peças são 100% recicláveis, BPA Free e fabricadas com energia de fontes renováveis. DIMENSÕES: As dimensões da Cumbuca Coza Uno 500 ml são de 13,9 cm de comprimento, 13,9 cm de largura e 6,3 cm de altura. Com seu formato compacto e funcional, ela se encaixa facilmente em qualquer cômodo do seu lar. INSTRUÇÃO DE USO E LIMPEZA: Para limpeza e manutenção, basta utilizar um pano macio e umedecido (ou o lado macio da esponja) com água e sabão neutro. Evite o uso de materiais abrasivos que possam danificar a superfície do produto. INFORMAÇÕES ADICIONAIS: Descubra a versatilidade da Linha Uno! São Bandejas, Cumbucas, Pratos, Saladeiras, Tigelas, Travessas e itens de culinaria oriental como: Barco para sushi, molheiras para shoyu e ramekins. Essa coleção combina funcionalidade, durabilidade e resistência suportando temperaturas de -10°C a 80°C, sendo a soluçõa ideal para servir e compartilhar bons momentos. Eleve o nível no hora de servir com a Cumbuca Coza Uno 500 ml. Oferecendo uma combinação única de funcionalidade e estética, tornando-a uma peça essencial para a sua casa.', 10.99, 9.35, NULL, 'Home & Living > Dinnerware > Bowls', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lpkufwlbryb081', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842996464%2F23720920703', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19099781164', 'Mesa De Som Analógica 6 Canais Soundvoice Ms-602 Eux', 'Mesa de Som MS-602 EUX A linha MS é uma das principais da marca Soundvoice, contando com inúmeros recursos e tendo destaque principal para sua função interface, que possibilita a conexão da mesa de maneira direta ao computador, a linha MS conta com equalizador gráfico de 7 bandas, bluetooth, gravação USB direta, display digital, e phantom power +48V. Por fim, nossos modelos são analógicos e se destacam por sua leveza, seu formato compacto e a praticidade em ser transportada e utilizada. Especificações gerais e técnicas do produto: • 6 canais mono com entradas balanceadas e XLR de linha P-10 • Processador de efeitos com tela de LCD • Equalizador gráfico de 7 bandas • Entrada USB com display digital • Gravação e reprodução direta em USB • Função Bluetooth • +48v phantom power • Equalização de 3 vias (grave, -médio e agudo) por canal • Leds indicadores de pico • 1 auxiliar send • Bivolt Conteúdo da embalagem: • Mesa de Som MS-602 EUX', 1334.99, 879.0, NULL, 'Audio > Amplifiers & Mixers', 'https://cf.shopee.com.br/file/br-11134207-7r98o-maoily84z4e10d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1036189392%2F19099781164', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
