INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43628286011', 'Panela Wok Supra 4,3L 28cm Antiaderente Superflon Ultra (Escolha)', 'A Panela Wok Supra da MTA é sinônimo de versatilidade, desempenho e durabilidade. Produzida em alumínio com revestimento antiaderente Superflon Ultra de 7 camadas, proporciona cozimento rápido e uniforme, evitando que os alimentos grudem e facilitando a limpeza no dia a dia. Com capacidade de 4,3 litros e diâmetro de 28 cm, é ideal para preparar refogados, salteados, massas, carnes, legumes e receitas orientais com praticidade. Conta com alças em baquelite antitérmico, que garantem segurança e conforto no manuseio, além de tampa de vidro temperado, permitindo acompanhar o preparo sem perda de calor. Resistente, funcional e moderna, pode ir à lava-louças e atende perfeitamente quem busca qualidade e eficiência na cozinha. Carcterísticas: Capacidade: 4,3 L Diâmetro: 28 cm Material: Alumínio Espessura: Aproximadamente 1,8 mm Revestimento: Antiaderente Superflon Ultra – 7 camadas Tampa: Vidro temperado Alças: Baquelite antitérmico Uso: Fogão a gás ou elétrico Pode ir à lava-louças Variações do Produto: Variação 1 – Cor Grafite Variação 2 – Cor Vermelho Conteúdo Total da Embalagem: - 01x Panela Wok Supra 4,3L 28cm Antiaderente Superflon Ultra 7 Camadas com Tampa de Vidro (Escolha a Cor)', 175.25, 157.72, NULL, 'Home & Living > Kitchenware > Pots', 'https://cf.shopee.com.br/file/sg-11134201-82626-mjtzocc8dfk7ad', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356143297%2F43628286011', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58201163541', 'Conjunto Regata Tropical Bermuda Bee Loop', 'Conjunto infantil para menino, desenvolvido em meia malha e moletom sem felpa, unindo estilo e conforto para o dia a dia. A regata possui estampa que deixa o look moderno e descontraído. Já a bermuda possui cós elástico, proporcionando praticidade ao vestir e ajuste confortável. Ideal para brincar, passear e aproveitar os dias de verão com liberdade de movimentos, frescor e estilo.Tecido: Regata: Meia malha | Bermuda: Moletom sem felpaComposição: BERMUDA: 50% algodão 50% poliéster, REGATA: 100% algodãoModelagem: AmplaComprimento Mangas: CurtaModelo Mangas: RegataComprimento: CurtoForro: NãoCintura: MédiaDecote/Gola: Redondo', 104.9, 41.96, NULL, 'Baby & Kids Fashion > Boy Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/sg-11134201-82254-mhkx7s40cjyeb3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F337974126%2F58201163541', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
