INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20697686659', 'DRACULA LEVEL 2 PACK CD ROM', 'DRACULA LEVEL 2 PACK CD ROM Nas montanhas da Transilvânia, fica um castelo. É o lar do Conde Dracula um lugar sombrio e solitário, e r noite os lobos uivam em torno das paredes. No ano de 1875, Jonathan Harker vem da Inglaterra para fazer negócios com o Conde. Mas J. Informações Adicionais Autor: STOKER, BRAM Data Publicação: 30/12/1899 Tipo de capa: BROCHURA Condição do Item: Novo Subtitulo: DRACULA LEVEL 2 PACK CD ROM Idioma: INGLES Páginas: 102 Edição: 3 ISBN-13: 9780194790208 ISBN-10: 0194790207', 62.4, 62.4, NULL, 'Books & Magazines > Books > Classic Literature', 'https://cf.shopee.com.br/file/sg-11134201-7rbll-lp9br460sbyydd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F20697686659', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9531939850', 'Kriptonia - Como Destruir o que Rouba sua Força - John Bevere', '📝 Descrição: Kriptonia, de John Bevere, é um chamado direto à libertação espiritual. Assim como a kriptonita enfraquecia o Superman, o pecado e a desobediência enfraquecem o cristão. Neste livro impactante, Bevere revela como atitudes aparentemente inofensivas podem drenar nossa força espiritual e nos afastar do propósito de Deus. Com base em princípios bíblicos e experiências práticas, o autor mostra como identificar e eliminar essas “kriptonitas” da alma, restaurando a autoridade, a ousadia e a intimidade com Deus. Uma leitura essencial para quem deseja viver com poder, liberdade e plenitude espiritual. 📄 Ficha técnica: Título: Kriptonia – Como Destruir o que Rouba sua Força Autor: John Bevere Editora: Chara Ano de publicação: 2018 ISBN: 9788559290172 Idioma: Português Número de páginas: 304 Formato: Brochura Dimensões: 23 cm x 16 cm Peso: 450 g Categoria: Vida cristã, espiritualidade, santidade Indicação etária: A partir de 16 anos 🔍 Palavras-chave: kriptonia john bevere, fraqueza espiritual, pecado oculto, santidade cristã, livro de libertação, vida com propósito, chara editora, restauração espiritual, intimidade com Deus, força interior', 54.46, 54.46, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mg5b4bnne87447', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380531074%2F9531939850', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40158185490', 'Livro de Colorir - Fuzzy Friends - Capa Flexivel', 'Descrição Permita-se desacelerar com Fuzzy Friends, livro de colorir da Ciranda Cultural inspirado na tendência cozy do TikTok, que oferece ilustrações adoráveis para aliviar o estresse e estimular a criatividade. Com acabamento em brochura laminada brilho e papel de alta gramatura, cada desenho é um convite ao autocuidado e à atenção plena, ideal para todas as idades. Este título é perfeito para momentos de desconexão da rotina, meditação ativa ou como presente acolhedor. Transforme seu tempo livre em uma experiência de bem-estar — adquira já e comece sua jornada relaxante. Ficha Técnica Título original: Fuzzy Friends – Para Colorir Autor/Ilustrador: Ciranda Cultural / Jeferson da Silva Editora: Ciranda Cultural ISBN: 9786526121696 Formato: 21 × 28 × 0,38 cm Acabamento: Brochura com laminação brilho Idioma: Português Coleção: Comfy & cozy books Faixa etária: +9 anos Edição: 1ª edição, 2024 Material: Papel de alta gramatura Palavras-chave Fuzzy Friends, livro de colorir, Ciranda Cultural, colorir relaxante, anti stress, papel gramatura alta, laminação brilho, arteterapia, mindfulness, autocuidado, passatempo criativo, relaxamento mental, desconexão digital, hobby artístico, presente criativo, ilustrações aconchegantes, livro infantil, livro para adultos, meditação ativa, coordenação motora, atividade sensorial, arte calmante, livro cozy, coleção Comfy & cozy books, lançamento 2024, livro nacional, criatividade terapêutica, estresse relief', 15.33, 15.33, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mc21ciosmcp138', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380531074%2F40158185490', NULL, NULL, '2026-07-28T02:11: