INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22097504214', 'Adega Suggar Lyon 13 Garrafas Com Porta De Vidro 127v - AD1511IX', 'Adega Suggar Lyon 13 Garrafas Com Porta De Vidro 127v - AD1511IX Desfrute de momentos especiais com a sofisticada adega Suggar Lyon Premium. Com capacidade para 13 garrafas, este elegante produto não apenas refrigera, mas também preserva a qualidade dos seus vinhos. Confortável e estilosa, esta adega é perfeita para grandes espaços e residências. As duas bandejas facilitam a organização e otimizam o uso do seu espaço de armazenamento. Sua orientação vertical proporciona uma excelente experiência ao usuário. Mantenha seus vinhos na temperatura ideal por mais tempo, graças ao sistema leve Compressor, que protege e preserva o aroma e o sabor de suas preciosidades vinícolas. Especificações Materiais da porta: Aço inoxidável Vidro Capacidade de garrafas 13 Com controle de temperatura Sim Com luz interior Sim Quantidade de prateleiras 2 Imagens de caráter ilustrativo Informações divulgadas de acordo com o manual do fabricante Em caso de duvidas sobre informações técnicas, utilização, limitações e manuseio do produto, verifique o manual do fabricante. Produto novo na caixa, lacrado com NF e garantia do fabricante de 12 meses EAN7896518509363 NAC013149', 2634.3, 1629.9, NULL, 'Mobile & Gadgets > Tablets', 'https://cf.shopee.com.br/file/sg-11134201-7rd3y-luzadbfijuzd3d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683223635%2F22097504214', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23798076308', 'Filtro Ar Ford Fiesta 2002 a 2003 - 1352998 - FAP9003', 'Filtro Ar Ford Fiesta 2002 a 2003 1352998 FAP9003 Motor 1.6 8v Gasolina - (Mecânico) (Com Pré Filtro) Após passar pelo filtro, o ar é aspirado pelo motor através de seus êmbolos (pistões). Durante este processo, sensores do sistema de injeção eletrônica enviam sinais para o Módulo da Injeção Eletrônica do Veículo, informando a temperatura do ar que está sendo admitido. O filtro do ar é construído para que as impurezas em suspensão no ar sejam separadas, ficando as mais pesadas depositadas no fundo da caixa de filtração e as mais leves sendo retidas pelo elemento filtrante.', 36.44, 36.44, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rfig-m3milp4nec0e67', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23798076308', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23997017858', 'Caixa Térmica 36 Litros Araguaia com Alça 073625 BEL', 'Caixa Térmica 36 Litros com Alça Ergonômica e Trava Araguaia 073625 BEL A Caixa Térmica 36 Litros é perfeita para te acompanhar na praia, camping, churrasco ou reunião com a família e amigos. Possui capacidade de 7 garrafas de 2L ou 54 latinhas de 350ml (sem gelo). As caixas térmicas da Bel são livres de BPA, permitindo assim o armazenamento de alimentos e bebidas com mais segurança. Além disso, são feitas em material 100% virgem, atóxico e sem deixar odores no produto, o que garante sua qualidade e durabilidade. A tampa possui um design diferenciado com suporte para bebidas e sua alça ergonômica facilita na hora do transporte. A Caixa Térmica 36 Litros Marinha Bel é um produto indispensável para manter sua bebida gelada ou seu alimento conservado por mais tempo. Capacidade da Caixa Térmica 36 Litros (sem gelo): 7 garrafas de 2L ou 54 latinhas de 350ml. Vantagens: Em Polipropileno com isolamento térmico em Polietileno Expandido (EPS) Material 100% virgem e Livre de BPA Com alça ergonômica Tampa com trava de segurança Fácil de limpar e prática de usar Conserva a temperatura por mais tempo Produzida com materiais de qualidade que garantem a resistência e durabilidade do produto Dados Técnicos: Alça para transporte: Sim Estrutura: PP (Polipropileno) Revestimento: Isolamento Térmico em EPS (Poliestireno Expandido) Porta Copos: Sim Capacidade: 7 garrafas de 2L ou 54 latinhas de 350ml (sem gelo) Cor: Marinha Dimensões aproximadas montado(CxLxA): 48cm x 33cm x 40cm Selos Produto: Fabricado no Brasil Ref: 073625 Marca: BELFIX Garantia: 03 Meses * Imagens Meramente Ilustrativas. . Caixa, Térmica, 36, Litros, com, Alça, Ergonômica, e, Trava, Araguaia, 073625, BEL, 7896777913949,', 127.28, 127.28, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/sg-11134201-7rblz-lmp465fiefc39f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F357239640%2F23997017858', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
