INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898066284', 'Bacia Plasútil Decorada Astronauta 17L', 'Bacia Plasútil Decorada Astronauta 17L A Bacia Plasútil é perfeita para o uso diário com bebês, oferecendo um design prático e seguro. Com um volume de 17,1 litros, esta bacia é ideal para banhos e outras necessidades. Fabricada em polipropileno de alta qualidade, é resistente e livre de BPA, garantindo a segurança e a saúde do seu bebê. A estampa decorativa adiciona um toque de charme, tornando a hora do banho mais divertida. Além de sua funcionalidade, a bacia é leve e fácil de transportar, facilitando o manuseio para os pais. Seu design foi pensado especialmente para bebês, proporcionando conforto e segurança durante o uso. A bacia Plasútil é uma excelente adição ao enxoval, prática para diversas atividades do dia a dia. Garanta um cuidado especial ao seu bebê com esta bacia decorada e desfrute de momentos agradáveis e seguros. Informações Adicionais: Tamanho: Único Cores: Azul Referência: 4044 Medidas aproximadas: 18,5cm x 48,5cm x 51,5cm Marca: Plasútil', 65.9, 65.9, NULL, 'Mom & Baby > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rfgw-m3dufsfstxwl49', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275097038%2F22898066284', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
