INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '4380022578', 'Aro Adaptador Alto Falante Onix Cruze Spin Cobalt Prisma Portas - preto / 1870', 'Aro Adaptador Onix Dianteiro / Traseiro Spin Cobalt Novo Prisma P/ Alto Falantes 6" Aros Adaptadores Para Fixação de Alto-Falantes Originais Se seu carro necessita algum kit de aros adaptadores específicos de fixação, este é o anúncio certo. Este adaptador evita uma nova furação no veículo, utilizando a furação original. Material : Plástico ABS. Cor: Preto - Produto Novo - Produto de Ótima Qualidade - Com Material de Alta Resistência Envio imediato !!! Postamos seu pedido em 24 horas !!! Sua encomenda segue com seguro e rastreamento O melhor custo-benefício IMPORTANTE !!! -Verifique a compatibilidade do produto com seus equipamentos para que não haja problemas na hora do uso! -Antes da instalação deve ser feito o teste em bancada para que não ocorra a perda da garantia. -A instalação deve ser feita por um profissional capacitado, não nos responsabilizamos por uso indevido ou instalação incorreta. Política de garantia, troca e devolução. A DEVOLUÇÃO POR INSTALAÇÃO OU OUTROS MOTIVOS Poderá ser feita em até 7 dias corridos após o recebimento do produto, desde que com a embalagem original, junto com todos os acessórios que o acompanham, manual e embalagem deverão estar preservados, sem fitas coladas, etiquetas ou algo que a descaracterize. O Produto não poderá haver sido instalado, e sim somente testado em bancada, esse é um procedimento comum feito por instaladores profissional antes de fixar o produto no veículo, e obrigatoriamente todos os produtos que exigem instalação devem ser instalados por profissional devidamente habilitado. A DEVOLUÇÃO/TROCA POR DEFEITO DE FABRICAÇÃO Produtos com defeito somente serão trocados se cumpridas as mesmas condições de devolução, de não instalação, dentro dos 7 dias corridos após o recebimento, sem marcas de uso, do contrário serão enviados à assistência técnica do fabricante para conserto e devolução dentro dos prazos que rege a lei do consumidor vigente (CDC). A GARANTIA DO FABRICANTE Alguns fabricantes dispõe de garantia direta ao consumidor, e nesse caso a troca por defeito, ou a garantia de assistência técnica só poderá ser feita diretamente nos postos autorizado, não sendo feita através do revendedor. Mesmo estando dentro do prazo de 7 dias corridos do recebimento, produtos como DRIVERS E SUPER TWEETERS, possuem garantia somente para defeitos de fabricação, não são cobertos queima ou avaria de reparo, seja ele de qualquer natureza que não a de fabricação. Não serão aceitos devoluções de produtos avariados, queimados, riscados, amassados, por instalação, manuseio, uso ou transporte incorretos, fora da embalagem original ou com a mesma danificada.', 29.88, 26.86, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/fbdce73280990e946754fbc33605263b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F318402227%2F4380022578', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20699067231', 'Cano Refrigeração VECTRA 1994/2011 - 65953 - 087165', 'Cano Refrigeração VECTRA 1994/2011 2.0 8v O Tubo de Refrigeração do motor é um item de suma importância para o sistema de arrefecimento, a sua vida útil está ligada diretamente aos cuidados com a manutenção e troca do fluído (água + anticorrosivo) dentro do período recomendado. Quando não utilizado da maneira correta este tubo libera uma camada corrosiva que circula pelo sistema de arrefecimento danificando todos os componentes ligados ao sistema de arrefecimento.', 49.08, 49.08, NULL, 'Automobiles > Automobile Spare Parts > Radiators, Engine Cooling & Climate Control', 'https://cf.shopee.com.br/file/sg-11134201-7rbni-lnra7ev7bemg9f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F20699067231', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993924172', 'Aditivo Radiador Paraflu 2 Litros Hibrido VERDE Long Life Pronto para uso 103016', 'Conteúdo Da Embalagem: 02 Aditivo do Radiador 1 Litro - Pronto p/ uso 10-3016 VERDE Marca Há mais de 50 anos no mercado, a Paraflu é especialista em desenvolver soluções para cuidar do sistema de arrefecimento de todos os tipos de motores. Com tecnologia de ponta, inovação e qualidade, seus produtos garantem segurança e máxima proteção dos componentes. Código do Fabricante10-3016 Autostilemotors.', 59.8, 58.98, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-8258e-mqvyn07urzsz6a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F954990910%2F23993924172', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22798026613', 'Cadeira de Escritório Mônaco Plus com Base Giratória e Regulagem de Altura', 'Cadeira de Escritório Mônaco Plus com Base Giratória e Regulagem de Altura Eleve sua experiência de trabalho com a Cadeira de Escritório Mônaco Plus com Base Giratória e Regulagem de Altura. Com linhas elegantes e acabamento refinado, a Cadeira de Escritório Mônaco adiciona um toque de profissionalismo e modernidade ao seu espaço de trabalho. Seja em um escritório ou em casa, esta cadeira se destaca como um elemento de estilo! A possibilidade de ajustar a altura da cadeira permite personalizar a posição de trabalho de acordo com suas necessidades. Seja em uma mesa tradicional ou em um ambiente de trabalho mais moderno, a Cadeira de Escritório Mônaco oferece versatilidade para atender às suas preferências. O encosto em tela mesh não apenas adiciona um toque contemporâneo ao design, mas também proporciona uma ventilação eficiente. Isso mantém você fresco e confortável durante todo o dia, enquanto a tela flexível se adapta dinamicamente aos contornos do seu corpo. Construída com materiais de alta qualidade, esta cadeira oferece durabilidade e estabilidade. Seu assento é feito em madeira e revestido em tecido, já a sua estrutura é feita em polipropileno, materiais resistentes que garantem uma longa vida útil ao produto. Dimensões: > Material do Assento: Madeira Revestida com Tecido > Material do Encosto: Tela Mesh > Resistência: Aconselhável até 120,00kg > Peso: Aproximadamente 8,00kg Especificações Técnicas: > Altura Total(cm): 100,00 à 110,00 > Altura do Assento(cm): 40,00 à 50,00 > Altura do Encosto(cm): 60,00 > Largura do Encosto(cm): 45,00 > Profundidade do Assento(cm): 46,00 > Largura do Assento(cm): 46,00 > Espessura do Braço(cm): 7,00 > Profundidade Total(cm): 48,00 > Largura Total(cm): 59,00 Importante: Produto enviado desmontado acondicionado em caixa de papelão reforçada, acompanha manual de montagem (não nos responsabilizamos pela montagem do produto). > Observações de Entrega: Os entregadores não são autorizados: > Entrar no domicílio, sem estar acompanhado pelo cliente; > Entrar ou subir desacompanhado em prédio residencial ou comercial, o cliente precisa receber o pedido na portaria; > Entregar por meios alternativos (exemplo: içar produto por janela, subir escadas); > Entregar em edifícios, entrega será realizada apenas na portaria; > Realizar montagens, instalação ou manutenção de produtos; > Abrir a embalagem do produto; > Realizar entrega em endereço diferente do que consta na Nota Fiscal; > Garantia: 03 Meses Contra Defeitos de Fabricação. > Marca: Magazine Decor', 529.9, 322.31, NULL, 'Home & Living > Furniture > Benches, Chairs & Stools', 'https://cf.shopee.com.br/file/sg-11134201-824hz-mf2tyh6opzileb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F347781606%2F22798026613', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22798244034', 'Mangueira Radiador Inferior ESCORT 1.8 8v 1987 Ate 1992 - 91600 - 904179', 'Mangueira Radiador Inferior ESCORT 1.8 8v 1987 Ate 1992 Inferior Radiador 1.8 8v (Ø:32mm 1 17/64 " )(Medida:14cm x 25cm)O liquido entra no radiador pela "mangueira superior", em geral conectada na parte de cima do radiador. A medida que o liquido desce, ele passa por canais no radiador resfriados por meio de passagem do ar pelas aletas de refrigeração entre os canais. Depois ser resfriado, o liquido sai do radiador pela "mangueira inferior". Em geral, há uma mola dentro dessa mangueira para evitar que ela quebre quando a bomba de agua puxa o liquido do radiador.', 44.5, 44.5, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rd5u-m6u3h1c3widod2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22798244034', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22792523933', 'FIltro Ar Condicionado SPORTAGE 2005/2010 - 37343 - AKX1984', 'FIltro Ar Condicionado SPORTAGE 2005/2010 (EX / LX) - Motor 2.0 16v Gasolina - / (EX) - Motor 2.7 24v V6 Gasolina - (Automático/Mecânico) Os filtros do ar para cabine são produzidos com fibras carregadas eletrostaticamente. Este filtros possuem camadas protegidas de um lado por um pré-filtro para reter partículas maiores. Do lado oposto possui uma camada de proteção a danos ao filtro.A função do meio filtrante é remover a maior quantidade possível de contaminantes do sistema do ar, oferecendo o mínimo de restrição ao fluxo de ar.', 20.16, 20.16, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-822ye-mo9t5wlrr6do2c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22792523933', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '7867135616', 'Pulseira Olho grego em Prata 925', 'Itens incusos: Pulseira em prata 925 com olho grego Certificado de Garantia Cuidados e manutenção Para limpar use apenas flanela Deve-se evitar o uso nas tarefas domésticas, pois produtos químicos danificam a peça Procure separar as peças na hora de guardar Garantimos a autenticidade de nossos produtos. Compre e tenha certeza de receber uma jóia com duração para o resto da vida. A prata 925 é um material que tem garantia e durabilidade permanente, assim como o ouro 18k. Nossas jóias tem certificado de autenticidade reconhecidos no mundo todo, você pode levar em qualquer joalheria para efetuar os testes e comprovar a autenticidade das mesmas. Havendo dúvidas, não hesite em perguntar por favor! Será um prazer atendê-lo. Acompanha certificado que garante teor 925 do produto. EQUIPE AQUAMETAIS', 114.0, 79.99, NULL, 'Fashion Accessories > Bracelets & Bangles', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9t85cvi5em1e8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328147687%2F7867135616', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22398010306', 'Bóia Tanque Sensor Nível Fiat Palio 1996 a 1999 - 511613 - 2354', 'Bóia Tanque Sensor Nível Fiat Palio 1996 a 1999 511613 2354 Motor 1.0 8v Gasolina MPI O sensor de nível de combustível tem a função de medir a quantidade de combustível presente no tanque e informar a UCE (Unidade de Comando Eletrônico) que, por sua vez, controla a posição do marcador de nível no painel de instrumentos do veículo.', 106.21, 106.21, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/sg-11134201-7rbm3-lmz05z8vmekr08', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22398010306', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58260115001', 'Sapato Slingback Salto Baixo Liso Ramarim 2415221', 'Sapatilha Feminina Slingback Salto Baixo Confortável com Fivela Delicadeza, leveza e estilo em um modelo versátil para o seu dia a dia. Design elegante e feminino: Com bico levemente alongado e acabamento sofisticado, essa sandália estilo slingback valoriza o pé com um visual moderno e delicado. As variações em cores trazem ainda mais personalidade para compor diferentes looks. Conforto para acompanhar sua rotina: A palmilha levemente acolchoada garante mais maciez ao caminhar, ideal para quem busca conforto durante todo o dia. Ajuste perfeito aos pés: Possui fechamento com fivela, permitindo melhor regulagem e segurança no uso. O salto baixo de aproximadamente 2,5 cm oferece elegância com conforto, perfeito para uso prolongado. Conta com forro bactericida, auxiliando na prevenção de odores e proporcionando mais bem-estar. Principais características: Material sintético; Salto baixo: 2,5 cm; Ajuste com fivela; Palmilha levemente acolchoada; Forro bactericida. Variações disponíveis: Rosa | Coral | Verde Água Versátil para todas as ocasiões: Perfeita para o trabalho, passeios ou momentos casuais, combinando facilmente com vestidos, saias ou calças. Dica de conservação: Limpar com pano macio e levemente úmido. Evitar exposição prolongada ao sol para preservar a cor e o material. Palavras-chave estratégicas: sandália slingback feminina, sandália salto baixo confortável, sandália com fivela feminina, sapato feminino casual elegante, sandália dia a dia confortável Um modelo que une conforto, praticidade e elegância para acompanhar você em todos os momentos!', 199.9, 69.9, NULL, 'Women Shoes > Heels', 'https://cf.shopee.com.br/file/sg-11134201-820lt-mnvf5k60hs03b9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%