INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18697816547', 'Brinco Feminino de Prata 925 Bola lisa', 'Brinco Feminino de Prata 925 Bola Lisa: Minimalismo e Elegância O Brinco Feminino de Prata 925 Bola Lisa é o acessório perfeito para quem busca um visual clean e sofisticado. Seu design simples e atemporal é feito em Prata 925, oferecendo um brilho duradouro e alta qualidade. Com tamanhos variados, este brinco é versátil e pode ser usado em diferentes ocasiões, desde o dia a dia até momentos especiais. Especificações do Produto Tamanhos Disponíveis: 2mm, 3mm, 5mm, 6mm Pesos: 0,3g, 0,4g, 0,6g, 0,9g Material: Prata 925 Destaques do Brinco Design minimalista e elegante com acabamento liso e brilhante. Disponível em quatro tamanhos para atender diferentes estilos e preferências. Feito em Prata 925, garantindo durabilidade e resistência. Leve e confortável, ideal para o uso diário. Simples e Sofisticado O Brinco Feminino de Prata 925 Bola Lisa combina a simplicidade do design com a sofisticação do material. Ele é uma peça versátil que complementa qualquer look, seja no trabalho, em eventos casuais ou formais. Adicione um toque de elegância discreta ao seu visual com este brinco clássico e atemporal. Cuidados com o Produto Evitar o contato com produtos químicos, como perfumes e cremes, para preservar o brilho. Armazenar em local seco e arejado para manter a qualidade da prata. Limpar regularmente com uma flanela macia para remover impurezas e conservar o brilho. Adicione Elegância ao Seu Dia a Dia Adquira o Brinco Feminino de Prata 925 Bola Lisa e traga um toque de sofisticação minimalista para o seu estilo. Com um design clássico e discreto, ele é o acessório perfeito para qualquer ocasião.', 31.11, 24.0, NULL, 'Fashion Accessories > Earrings', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m0al5sze3xdp16', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328147687%2F18697816547', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22398248693', 'Jogo de Velas PALIO 1996/2001 - 94408 - GV6R92', 'Jogo de Velas PALIO 1996/2001 MOTOR 1.0 8vc FIASA GASOLINA/ETANOL (Vela Resistiva)Conduzir a alta voltagem elétrica para a parte interna da câmara de combustão e transformar essa voltagem em faísca, gerando e inflamando a mistura ar/combustível. Apesar de pequenina e simples, trata-se de um item extremamente importante para o carro. O desempenho da vela vai definir o bom funcionamento do motor, controlar os níveis de combustível e até mesmo a emissão de poluentes.', 58.58, 58.58, NULL, 'Automobiles > Automobile Spare Parts > Electronics', 'https://cf.shopee.com.br/file/sg-11134201-7rd6v-m6u1lt93ehzv48', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22398248693', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
