INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19698869578', 'Massageador Facial de Jade - Jade Roller', 'O Jade Roller É Produzido com a Jade, Pedra de Fama Milenar, Conhecida Por Proporcionar Sensações de Paz e Harmonia e Muito Associada à Redução do Estresse. a Prática de Manusear Jade Rollers Vem Desde o Século 17 em Rituais de Beleza Dos Chineses. O Massageador Facial de Jade É Uma Ferramenta de Relaxamento Que Traz Diversos Benefícios para a Pele: - Estimula a Circulação Sanguínea (para Ajudar a Minimizar As Linhas de Expressão); - Promove Drenagem Linfática, Reduzindo o Inchaço da Pele; - Alivia a Tensão Muscular; - Tonifica a Pele e Melhora a Elasticidade; - Facilita a Absorção de Cosmético Pela Pele. Dica: a Pedra Jade É Naturalmente Fria, Mas Colocar o Massageador Facial Na Geladeira Irá Potencializar Alguns Dos Seus Benefícios.', 169.9, 159.9, NULL, 'Beauty > Beauty Tools > Facial Care Tools', 'https://cf.shopee.com.br/file/sg-11134201-82588-mqxpvze7ggsm21', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842559166%2F19698869578', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
