INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19697926542', 'Troninho Infantil Penico Musical Sapinho Verde Assento Bebe Desfralde Com Som Replay Kids', 'Troninho Penico Infantil Musical Sapinho Verde - Replay Kids O Troninho Sapinho Musical é mais uma solução prática e inovadora para o dia a dia das mamães e seus bebês. Com um design lúdico, este penico facilita a transição das fraldas descartáveis para o uso do vaso sanitário. O assento do troninho possui uma pequena elevação no meio para evitar respingos, e conta com um reservatório removível que facilita a limpeza. Além disso, possui um botão musical para tornar o momento mais descontraído, e apresenta nosso amigável MIMO na tampa! Feito com material resistente de excelente qualidade, este troninho pode ser transformado em um banquinho ao ser virado de ponta cabeça e com a remoção das alças de apoio. Ideal para acompanhar o crescimento da criança. Esse troninho inclui adesivos de incentivos de desfralde, ajudando a evitar traumas. Os adesivos podem ser colocados ao lado do passo a passo ou em qualquer lugar do penico, estimulando a criatividade e a imaginação da criança. Recomendado a partir de 12 meses, este troninho possui uma base antiderrapante, é fácil de limpar e pode ser usado no chão, proporcionando praticidade e conforto para pais e filhos durante todo o processo de aprendizado. Principais Características: - Idade recomendada: A partir de 12 meses - Assento de tampa fixa - Reservatório removível - Interativo com música - Com alças removíveis - Vira Banquinho - Base antiderrapante - Fácil de limpar - Uso no chão - Adesivos Com quadro de Desfralde - Material Resistente Especificações Técnicas: - Conteúdo da Embalagem: 1 Troninho Penico , Adesivos Interativos - Material/Composição: Plástico resistente / Polipropileno - Garantia: 30 Dias (Contra Defeito de Fabricação Pelo Fabricante) - Dimensões do Produto( A x L x P): 36,0 x 25,0 x 32,0 cm aprox - Peso: 1,30 kg - Referência do Fabricante: 21825 - Cód. EAN: 7899403218258 - Marca: Replay Kids Imagens meramente ilustrativas, as cores e estampas podem variar de acordo com o lote do fabricante', 89.9, 70.68, NULL, 'Mom & Baby > Diapering & Potty > Potty Training & Commode Chairs', 'https://cf.shopee.com.br/file/sg-11134201-7rdwh-m0x7rd6d4t94e6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F340054154%2F19697926542', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793136726', 'Assento Redutor Infantil Dobrável C/ Escada Mcfrog Maxi Baby', 'Assento Redutor Infantil Dobrável Com Escada Mcfrog Maxi Baby Descubra o Assento Redutor Com Escada Mcfrog - Maxi Baby, a solução ideal para facilitar a transição do seu filho ao vaso sanitário. Projetado para crianças de 1 a 7 anos, este assento oferece uma série de características que garantem conforto, segurança e praticidade. Com dois pedais ajustáveis em altura e um pedal largo e antiderrapante, seu filho terá um apoio estável e seguro. O assento conta com um mini encosto que proporciona suporte adicional, e o conforto é garantido pelo assento de PU, fácil de higienizar e disponível para upgrade. Além disso, o modelo aprimorado com slot para cartão evita que o assento se desloque, oferecendo uma segurança extra. Com uma base de silicone antiderrapante, você pode ter certeza de que o assento permanecerá firmemente no lugar. Quando não estiver em uso, o Assento Redutor Com Escada Mcfrog pode ser dobrado rapidamente e armazenado sem ocupar muito espaço. Torne o aprendizado do seu filho mais confortável e seguro com este produto versátil e de alta qualidade! Principais características: - Possui dois pedais - Altura Ajustável - Recomendado Para Bebês de 1 a 7 anos - Almofada em PU - Pode Ser Dobrado Suavemente e Fechado Instantaneamente - Base de Silicone Anti Derrapante - Pedal Anti Derrapante Largo - Mini Encosto - Ajuste de Altura - Assento Confortavel e Facil de Higienizar - Escolha entre as Cores Azul ou Rosa Especificações Técnicas: - Conteúdo da Embalagem: 1 Assento, 1 Escada e 1 Manual de Instruções - Composição/Material: PP, TPR, PVC - Dimensões do Produto: 54,0 x 32,5 - Peso: 1,32 kgs - Garantia: 30 dias (Contra Defeitos de Fabricação Pelo Fabricante) - Certificação: Isento - Código do Fabricante: 21733 / 21734 - EAN: 7899403217336 / 7899403217343 - Marca: Maxi Baby Imagens Meramente Ilustrativas. As cores e estampas podem variar de acordo com o lote do fabricante.', 162.9, 119.0, NULL, 'Mom & Baby > Diapering & Potty > Potty Training & Commode Chairs', 'https://cf.shopee.com.br/file/sg-11134201-7rdyo-lxl6ax4ysszu50', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F340054154%2F23793136726', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
