INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209460394', 'Suco Natural One Integral Laranja', 'O Suco de Laranja Integral Natural One é a escolha perfeita para quem busca uma bebida saudável e nutritiva, feita com 100% suco de laranja, sem adição de açúcares e conservantes. Rico em vitamina C, é ideal para fortalecer o sistema imunológico e refrescar o seu dia. Este suco integral é equivalente ao suco de 12,5 laranjas. Agite antes de beber e aproveite todo o sabor natural da fruta. Beba gelado e não consuma caso o lacre esteja violado ou a embalagem estufada.', 17.79, 14.69, NULL, 'Food & Beverages > Beverages > Juice & Juice Vinegar', 'https://cf.shopee.com.br/file/sg-11134201-8258p-mqnekix1z9jib4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555102%2F58209460394', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22297651064', 'Lousinha Infantil 3 em 1 Criatividade Aprendizado Madeira Desenho Brinquedo Pedagógico Montessori', 'Lousinha Infantil 3 em 1 - Estímulo à Criatividade e Aprendizado O brinquedo educativo perfeito para desenvolver a criatividade dos pequenos! A Lousinha Infantil 3 em 1 oferece uma experiência completa e versátil, com tripla funcionalidade que mantém as crianças engajadas e entretidas por horas. Funcionalidades Triplas: Quadro Verde para Giz: De um lado, as crianças podem usar gizes coloridos para desenhar e escrever, explorando sua criatividade sem limites. Quadro Branco para Marcadores: Do outro lado, o quadro branco é perfeito para desenhar e apagar com facilidade, ideal para praticar a escrita e desenhar repetidamente. Bobina de Papel: A lousa também inclui uma bobina de papel, permitindo que as crianças desenhem e escrevam livremente em uma superfície nova a cada vez, ampliando ainda mais as possibilidades de criação. Desenvolvimento e Diversão: Este brinquedo não só incentiva a criatividade, mas também é uma ferramenta poderosa para o desenvolvimento da coordenação motora, da leitura e da escrita. As crianças podem alternar entre as diferentes superfícies de escrita e desenho, garantindo que a diversão nunca acabe! Inclui: Gizes coloridos Apagador Dimensões: Lousa Montada: 105cm de altura x 50cm de largura Quadros: 55cm de altura x 43cm de largura Palavras-chave: Lousinha Infantil, Quadro Infantil, Quadro 3 em 1, Lousa Verde, Quadro Branco, Bobina de Papel, Brinquedo Educativo, Desenvolvimento Infantil, Coordenação Motora, Criatividade, Leitura e Escrita, Brinquedo Versátil, Brinquedos para Crianças, Estímulo à Criatividade, Brinquedo Lúdico, Brincadeira Educativa.', 425.87, 319.4, NULL, 'Mom & Baby > Toys > Pretend Play', 'https://cf.shopee.com.br/file/br-11134207-820ma-mm1s8xrs1gxs0a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F763724888%2F22297651064', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
