INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26788785258', 'Kit Cuba Pia De Apoio Quadrada 32x30cm Topázio Para Banheiro Com Torneira E Válvula Cromada Beltempo', 'Cuba Pia de Apoio 32x30cm Topázio Branca com Torneira e Válvula Cromada - Beltempo Transforme o seu banheiro com a elegância da Cuba Topázio Beltempo. Fabricada em mármore sintético resistente, essa cuba de apoio traz um design moderno, acabamento polido em Gel Coat e alta durabilidade. Ideal para quem busca sofisticação com praticidade na limpeza e instalação. Acompanha torneira cromada com bica giratória 360° e válvula metálica, formando um conjunto completo e funcional para seu ambiente. DIFERENCIAIS DO PRODUTO - Cuba de mármore sintético polido com pintura em Gel Coat - Torneira com 1/4 de volta e arejador que economiza água - Bica giratória 360° - mais mobilidade e conforto no uso - Válvula produzida em metal cromado resistente - Design sofisticado e acabamento de alto padrão - Instalação prática - modelo de apoio sobre bancada - Embalagem com proteção reforçada para transporte seguro DIMENSÕES DA CUBA - Altura: 9 cm - Largura: 30 cm - Comprimento: 32 cm - Profundidade útil: 7,5 cm - Peso: 3,3 kg TORNEIRA CROMADA - Tipo: Mesa, bica baixa - Altura total: 22 cm - Altura da bica: 14,2 cm - Avanço da bica: 15,3 cm - Acionamento: 1/4 de volta - Material: Plástico ABS cromado - Possui arejador: Sim - Bitola: 1/2" - Peso: 134 g VÁLVULA METÁLICA - Tipo: Padrão - Material: Metal cromado - Diâmetro do encaixe: 5,7 cm - Altura da rosca: 6,8 cm - Bitola da saída: 7/8” - Peso: 78 g ITENS INCLUSOS - 1 Cuba Topázio - 1 Torneira cromada com acessórios de instalação - 1 Válvula metálica padrão DICA DE LIMPEZA Para preservar o brilho e a durabilidade do conjunto, utilize apenas pano macio com sabão neutro. Evite palha de aço ou produtos abrasivos.', 199.9, 199.9, NULL, 'Home & Living > Tools & Home Improvement > Sinks & Water Taps', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcb648l5xm8w1a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F377074801%2F26788785258', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40159338654', 'Caixa 6 Doces com Berço Tampa Transparente N° 8 (7,7x11,3x3cm) Kraft - 10 unidades - Assk - Rizzo', 'Caixa 6 Doces com Berço Tampa Transparente N° 8 (7,7x11,3x3cm) Kraft - 10 unidades - Assk - Rizzo A Caixa Berço Nº 8 Kraft para Doces – 7,7×11,3×3 cm é a escolha perfeita para quem busca apresentar doces com elegância e segurança. Produzida em papel kraft resistente, já acompanha berço interno para acomodar brigadeiros, trufas, cup cakes e bombons de forma organizada e protegida. Seu acabamento rústico combina com estilos artesanais e valoriza a aparência do conteúdo, ideal para vitrines, encomendas ou lembrancinhas. Essa caixa é ideal para doces individuais ou duplos, doces finos e mimos de festas. Muito utilizada em confeitarias, padarias e produtores artesanais, ela alia praticidade – dispensando busca por forminhas avulsas – à sofisticação visual. O berço interno evita que os doces se desloquem, garantindo que cheguem intactos ao consumidor, mesmo durante o transporte. Modelo prático e com ótima apresentação, oferecido em caixas desmontadas para reduzir custos de envio e armazenamento Composição: Papel e PVC Medidas Aproximadas: 7,7x11,3x3cm Contém 10 unidades. Dúvidas Frequentes: Quanto tempo leva o envio? ⏰ Todos os pedidos com etiqueta de envio liberado pela shopee até as 18hs são coletados no próximo dia útil pela transportadora Shopee Express. Qual o prazo de entrega? 🛵 A loja não tem acesso a parte logística da shopee. A Shopee não informa para a loja prazo de entrega. Ao clicar em comprar na opção envios é apresentado o prazo de entrega. O produto é novo? 😀 Sim. Só trabalhamos com produto novos e dentro da embalagem original do fabricante. Como faço para comprar mais de um item da loja? 🛍 No app ao lado do botão comprar tem o ícone de um carrinho de supermercado, clicando nele o produto será acrescentado no carrinho que fica na parte superior do app. Após acrescentar todos os produtos que gostaria é só clicar no carrinho e selecionar todos os itens e clicar em continuar. Comemore com Alegria: 🥰😀 Na Rizzo Distribuidora, a tradição e o encanto do nosso espaço físico no coração da 25 de março, em São Paulo, são cuidadosamente embalados para chegar até você. Permita-nos levar a magia de uma das lojas mais tradicionais da região diretamente para o conforto da sua casa ou empresa.', 32.9, 32.9, NULL, 'Home & Living > Party Supplies > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdwf-mcgqpm6lk4vr77', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400124163%2F40159338654', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
