INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22094717180', 'Espaçador E Nivelador Para Piso 1,5 Mm 1000pçs Slim Cortag', 'O Espaçador Nivelador Slim Porcelanato 1,5mm da CORTAG é a ferramenta perfeita para garantir um acabamento impecável em seus projetos de revestimento. Com uma espessura de 1,5mm, este espaçador é ideal para criar um alinhamento uniforme e preciso em suas instalações de porcelanato. Este produto vem em uma embalagem com 1000 peças, proporcionando um excelente custo-benefício para grandes projetos. A cor vermelha vibrante facilita a visualização durante a instalação, garantindo que nenhum espaçador seja esquecido ou perdido. O modelo SLIM da CORTAG é conhecido por sua durabilidade e resistência, garantindo que seus projetos de revestimento durem por muitos anos. Este espaçador nivelador é fácil de usar e pode ser aplicado por profissionais e entusiastas do faça-você-mesmo. Invista no Espaçador Nivelador Slim Porcelanato 1,5mm da CORTAG para garantir um acabamento profissional em todos os seus projetos de revestimento. Com este produto, você pode ter certeza de que cada peça de porcelanato será instalada com precisão e perfeição. Ficha Técnica Indicado para pisos e revestimentos cerâmicos, especialmente porcelanatos. - Quantidade por embalagem: 1000 peças - Cor: Transparente - H2: 1,5 mm Conteúdo da Embalagem CAIXA COM 1000 ESPAÇADORES.', 162.56, 94.9, NULL, 'Home & Living > Tools & Home Improvement > Construction Materials', 'https://cf.shopee.com.br/file/sg-11134201-821et-mgwlrecf1rey5c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1328278916%2F22094717180', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
