INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20899547004', 'Aspirador de Pó BAS1430 1250W Britânia Vermelho 127V', 'Código do Fornecedor: 64901049 Marca: Britânia Conteúdo da embalagem: 1 Aspirador de Pó BAS1430 1250W Britânia Vermelho Reservatório 1,5L Com Rodinhas e Acessórios 127V O Aspirador de Pó Britânia Bas1430 1250W oferece praticidade e eficácia na limpeza do seu lar. Aqui estão algumas características que destacam este produto: Alta potência de sucção: Com 1250W de potência, o aspirador proporciona uma limpeza eficiente, garantindo a remoção de sujeira e poeira com facilidade. Acessórios variados: Acompanha vários acessórios adequados para diferentes tipos de superfícies, como piso frio, carpetes, cantos e frestas, tornando a limpeza mais completa e abrangente. Saco para pó removível e lavável: O saco para pó é permanente e lavável, proporcionando economia e praticidade, pois não é necessário substituí-lo com frequência. Rodinhas e design compacto: As rodinhas facilitam a locomoção do aspirador durante a limpeza, garantindo maior mobilidade. Além disso, o design compacto permite que o aparelho seja guardado na posição vertical, ocupando menos espaço. Compartimento indicador de cheio: Possui um compartimento indicador que sinaliza quando o saco para pó está cheio, facilitando a manutenção e evitando perda de sucção. Segurança: Conta com sistema de desligamento automático para prevenir o superaquecimento do aparelho, garantindo sua durabilidade e segurança durante o uso. Com todas essas características, o Aspirador de Pó Britânia Bas1430 1250W é uma excelente escolha para quem busca eficiência e praticidade na hora da limpeza doméstica. Garantia: 12 meses', 337.9, 337.9, NULL, 'Home Appliances > Small Household Appliances > Vacuum Cleaners & Floor Care Appliances', 'https://cf.shopee.com.br/file/sg-11134201-7rdyo-m1fl8c14wgjt97', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442555366%2F20899547004', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45503025706', 'Tênis Anacapri Lola Off White e Cinza - Feminino', 'Design imponente e conforto absoluto para todos os momentos! Tênis Anacapri Lola Off White e Cinza - Feminino Marca: Anacapri Gênero: Feminino Cor: Off white com detalhes em cinza, preto e branco Indicação: Uso diário, passeios e produções urbanas Material: Napa, couro macio e têxtil Cabedal: Recortes em napa, detalhes em couro macio na biqueira, lingueta e calcanhar Forro: Interno em material têxtil Fechamento: Cadarço branco Lingueta: Levemente acolchoada Palmilha: Confortável com assinatura da marca Solado: Baixo emborrachado, tratorado em goma marrom com detalhe traseiro em preto Desing: Comfy com pegada esportiva Detalhes: Tag marrom lateral Anacapri, costura pesponto nos contornos e peça recortada em napa na cor preta em formato de “A” Com shape robusto e moderno, o Tênis Lola da Anacapri traz um mix de materiais que reforça o estilo esportivo urbano. Os recortes em napa, aliados ao solado tratorado, criam uma proposta versátil e cheia de personalidade. Porque investir: Além de comfy, o modelo traduz a tendência de sneakers imponentes que elevam qualquer look casual, do dia a dia às produções mais elaboradas. Um tênis versátil e atemporal que vai se tornar o destaque do seu closet. Conteúdo da embalagem: 1 par de Tênis Anacapri Lola Off White e Cinza - Feminino', 259.99, 199.99, NULL, 'Women Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-822y0-mi5ywq1efcoy12', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1175741090%2F45503025706', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23694351200', 'Lanterna Pisca Dianteiro Lado Esquerdo MERCEDES BENZ ATEGO Cristal', 'Lanterna Pisca Dianteiro Lado Esquerdo MERCEDES BENZ ATEGO Cristal - Aplicação : Frente da cabine, no lado esquerdo (motorista) — lanterna de pisca frontal. Veículo : Mercedes-Benz Atego (modelos 1315, 1418, 1518, 1718, 1725, 2425 etc.) entre 2005 e 2012, utilizando lanterna dianteira L/E cristal / Atego e Actros a partir de 2012 — aplicação da Pradolux PL04980222 compatível tanto com Atego quanto com Actros (LE cristal, sem soquete) Códigos Compatíveis : 9738200521 / SS1078E‑CR / PL04980222 / PL05880222 Atenção: Trabalhamos com vários lotes de faróis, onde as marcas podem variar dependendo do lote disponível no momento da compra, todos são de procedência garantida, e de marcas confiáveis, sendo de igual aplicação, apenas a marca que pode mudar mas as peças são de uso igual Acompanha o produto: • 01 un | Lanterna Pisca Dianteiro Lado Esquerdo MERCEDES BENZ ATEGO Cristal', 253.9, 203.12, NULL, 'Spare Parts and Accessories for Vehicles > Heavy Duty and Boats > Accessories for Heavy Duty Vehicles', 'https://cf.shopee.com.br/file/sg-11134201-824hy-me03xm6w91j791', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F702541777%2F23694351200', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
