INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23294395589', 'Bolsa Infantil Tiracolo com Tachas e Texturizada Pampili', 'Estilo e atitude que as meninas adoram! Essa bolsa infantil é perfeita para produções modernas com um visual mais urbano e marcante.O destaque vai para o material resistente texturizado e as tachas decorativas que trazem um ar moderno ao acessório. Com estrutura compacta e funcional, essa bolsa conta com fechamento por botão magnético sob aba, super prática. A versatilidade e o design fazem dessa bolsa infantil um acessório indispensável no guarda-roupa das meninas que amam estar na moda desde cedo! Aposte! Com design versátil e cor moderna, essa bolsa é curinga para montar vários looks. E adivinha? Até a mamãe vai querer usar!! Dimensões: Altura: 18cm Largura: 13cm Profundidade: 4cm', 159.9, 159.9, NULL, 'Baby & Kids Fashion > Baby & Kids Accessories > Bags & Luggage', 'https://cf.shopee.com.br/file/sg-11134201-824ji-mekikr0ekf7nbd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1547100334%2F23294395589', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40728172244', 'Tênis Coca Cola Nomad Swift Azul Escuro - Masculino', 'Mais leveza e estilo para caminhar com conforto todos os dias! Tênis Coca Cola Nomad Swift Azul Escuro - Masculino Parte superior do formulário Parte superior do formulário Ficha Técnica: Marca: Coca-Cola Linha: Nomad Swift Cor: Azul escuro Gênero: Feminino Indicado: Dia a dia, passeios e combinações casuais Cabedal: Têxtil – malha elástica para melhor ajuste e conforto Forro: Têxtil respirável Palmilha: EVA, confortável e anatômico Entressola e Solado: EVA, leve e flexível Altura da Entressola: 4cm aproximadamente Fechamento: Cadarço Lingueta: Slip On com tag Coca-Cola Diferenciais: Design esportivo e minimalista com identidade urbana e elegante Com visual esportivo e tom azul, esse modelo combina com passeios, rotina e produções casuais com muita praticidade. Porque investir: O cabedal em malha têxtil elástica garante ajuste mais confortável ao pé, enquanto o forro respirável melhora a ventilação durante o uso. A palmilha em EVA anatômico oferece sensação macia a cada passo, e a entressola com solado em EVA deixa o tênis leve, flexível e ideal para quem passa horas em movimento. O calce com lingueta slip on e a tag Coca-Cola completam o visual urbano com toque moderno. Conteúdo da embalagem: 1 par de Tênis Coca Cola Nomad Swift Azul Escuro - MasculinoParte superior do formulário Parte superior do formulário Parte superior do formulário', 199.99, 177.99, NULL, 'Men Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-8262u-mjpyaumoojd382', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1175741090%2F40728172244', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
