INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22299551777', 'Tênis Fila Rise Up Salmão e Rosa - Feminino', 'Desempenho e conforto para acompanhar sua rotina ativa! Tênis Fila Rise Up Salmão e Rosa - FemininoParte superior do formulário Parte inferior do formulário Ficha Técnica: Marca: Fila Cor: Salmão com detalhes em rosa e tons de roxo Gênero: Feminino Cabedal: Mesh respirável com peças em material sintético aplicadas nas áreas essenciais Indicado: Treinos, caminhadas e atividades do dia a dia Palmilha: EVA confortável Sola: Borracha Fechamento: Cadarço Amortecimento: Macio Estabilidade: Neutro Tecnologias: ENERGIZED RUBBER, tecnologia que garante maior durabilidade, maciez e absorção de impacto Detalhes: Design esportivo moderno com logo Fila nas laterais Seja para treinar ou caminhar, contar com o tênis certo faz toda a diferença para manter conforto e desempenho ao longo do dia. Porque investir: O Fila Rise Up combina design esportivo moderno com tecnologias que elevam a experiência de uso. Seu cabedal em mesh respirável proporciona ventilação constante, enquanto as aplicações sintéticas oferecem maior suporte. A sola com tecnologia ENERGIZED RUBBER garante maciez e durabilidade, proporcionando mais conforto a cada passo. Conteúdo da embalagem: 1 par de Tênis Fila Rise Up Salmão e Rosa - FemininoParte superior do formulárioParte inferior do formulário', 329.99, 230.99, NULL, 'Women Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-824j4-mpmq2rsflou8e7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1614877278%2F22299551777', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200365146', 'Conjunto Infantil Menina Canelado Folhas Colorittá Rosa', 'O Conjunto Colorittá é composto por blusa e short em malha canelada mesclada. A blusa possui mangas curtas com delicados babados, enquanto o short conta com elástico no cós e detalhes em pregas. Além disso, sua estampa com folhas tropicais em cores suaves traz a essência leve da estação. Ideal para momentos casuais com a família e amigos, invista nesse conjunto para garantir um toque de sofisticação no dia a dia das meninas!Detalhes da peça: • Conjunto composto por blusa e short • Feito em malha canelada mesclada • Possui mangas curtas com babados • Elástico no cós • Estampa com folhagens tropicais • Ideal para momentos casuais com família e amigos', 139.9, 69.95, NULL, 'Baby & Kids Fashion > Girl Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/sg-11134201-825ax-mr1tnc5jy77r6e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1079500559%2F58200365146', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
