INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18507531953', 'O Peregrino | Notas de Estudo e Ilustrações | John Bunyan', 'O PeregrinoCom notas de Estudo e Ilustrações O Peregrino tem sido reimpresso lido e traduzido com mais frequência do que qualquer outro livro exceto a Bíblia Pessoas de todas as idades têm encontrando deleite nesta história simples e sincera de Cristão Os acontecimentos assemelham se a vida sucedem se com rapidez e consistência Esta nova edição traz elementos que estimularão a leitura o texto integral da obra notas explicativas das alegorias de Bunyan referências bíblicas os personagens e assuntos em foco breve sentenças à margem do texto chamando a atenção ao conteúdo dos parágrafos desenhos ilustrativos 23 capítulos especificando os assuntos da obra e a visualização fácil do conteúdo da página de modo que o leitor escolha o que deseja ler somente o texto original ou somente as notas explicativas ou somente as breves sentenças Todos estes elementos tornarão a leitura ainda mais agradável Título O Peregrino Subtitulo Com notas de estudo e ilustrações Autor John Bunyan Páginas 272 Formato 20 8 x 13 8 x 1 8 cm Peso 0 322 kg ISBN 9788599145098 Editora Fiel', 68.86, 68.86, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/697788da9e1b86b0f8d585f65f5c2718', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F18507531953', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
