INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23792946114', 'Kit Completo Elseve L’Oréal Paris Glycolic Gloss (5 produtos)', 'O Kit contém: Condicionador Elseve Glycolic Gloss 200ml Creme de Tratamento Elseve Glycolic Gloss 300g Shampoo Elseve Glycolic Gloss 200ml Spray Acidificante Elseve Glycolic Gloss 200ml Creme para Pentear Elseve Glycolic Gloss 250ml MAIS QUE BRILHO, É ULTRA GLOSS! A tecnologia de Elseve Glycolic Gloss de L’Oréal Paris garante brilho ultra gloss, durando até 6 lavagens e isso acontece pois sua fórmula com pH Ácido é rica em Ácido Glicólico, que atua no cabelo combatendo a porosidade e selando as cutículas dos fios, sendo indicado para todos os tipos de cabelos. O Creme de Pentear Elseve L’Oréal Paris Glycolic Gloss, é enriquecido com pH ácido e 3% do Complexo com Ácido Glicólico, o Além disso, com filtro UV e proteção térmica, este creme se torna um aliado essencial para manter o cabelo visivelmente saudável e perfeitamente alinhado. O Acidificante Elseve L’Oréal Paris Glycolic Gloss, traz fórmula inovadora, composta por 6% do Complexo com Ácido Glicólico e pH ácido, realiza uma laminação nas cutículas e corrige as imperfeições na fibra capilar. O Shampoo Elseve L’Oréal Paris Glycolic Gloss, enriquecido com pH ácido e um Complexo contendo 3% de Ácido Glicólico, traz o cuidado específico que visa revelar um cabelo visivelmente saudável e perfeitamente alinhado, garantindo um brilho gloss impressionante. O Creme de Tratamento Elseve L’Oréal Paris Glycolic Gloss, traz fórmula condicionante antiporosidade, com pH ácido e um potente Complexo contendo 6% de Ácido Glicólico, que realiza uma restauração profunda dos fios. Ele preenche as imperfeições na fibra capilar e sela as cutículas, proporcionando uma transformação visível nos cabelos, que se tornam notavelmente mais macios, saudáveis e exibem um gloss espelhado. O Condicionador Elseve L’Oréal Paris Glycolic Gloss, traz fórmula com Acido Glicólico e pH ácido, sela de maneira vigorosa os fios, preenchendo as imperfeições presentes na fibra capilar. Na superfície, lamina a cutícula, alinhando-a estrategicamente para refletir a luz de forma brilhante.', 213.26, 213.26, NULL, 'Beauty > Hair Care > Hair and Scalp Conditioner', 'https://cf.shopee.com.br/file/sg-11134201-7rcdb-ltxubqm4co36ff', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F23792946114', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
