INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250385517', 'Kit Meráki Matizador Shampoo + Condcionador + Máscara', '#html-body [data-pb-style=W2194F7]{justify-content:Flex-start;display:Flex;flex-direction:Column;background-position:Left top;background-size:Cover;background-repeat:No-repeat;background-attachment:Scroll}O Kit Meráki Matizador Shampoo + Condicionador + Máscara Capilar foi desenvolvido especialmente para cabelos loiros, descoloridos, grisalhos ou com luzes, que precisam de cuidado intensivo e correção da cor. Sua fórmula contém pigmentos violetas, que neutralizam os reflexos amarelados indesejados, enquanto os ativos hidratantes e nutritivos restauram a saúde dos fios, deixando-os sedosos, brilhantes e com toque suave. O uso combinado dos três produtos potencializa o resultado, promovendo luminosidade, proteção e manutenção do tom ideal. Modo de Uso: Shampoo: Aplique nos cabelos úmidos, massageie suavemente até formar espuma e deixe agir por 2 a 3 minutos. Enxágue bem. Condicionador: Após o shampoo, aplique no comprimento e pontas. Deixe agir por alguns minutos e enxágue. Máscara: Utilize de 1 a 2 vezes por semana. Aplique nos fios limpos e úmidos, deixe agir por 5 a 10 minutos e enxágue completamente.', 114.01, 114.01, NULL, 'Beauty > Hair Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-821eb-mgqi6ajrt3wq6d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F58250385517', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18873140158', '10 CAIXA PARA 4/6/8 DOCES LINHA DIA DAS MÃES MÃE GATA ( DIA DAS MÃES IDEIA ) OUTLET (CHOCO)', '10 caixas para 4/6/8 doces linha Dia das Mães Mãe Gata á escolha (ideia) Lindas embalagens para impulsionar suas vendas. Confeccionada em papel tríplex Premium. As caixas possuem um designe único e de fácil montagem, que pode ser utilizadas para embalagem de ovos de páscoa, doces e chocolates. ATENÇÃO: - Quantidade no título do anúncio - Não inclui ovos de chocolate, doces e chocolate (apenas embalagem) - Não personalizamos, cores e temas apenas como está na foto. - Confira o prazo de envio no ato da compra - A caixa é enviada desmontada para a preservação do produto e otimização e de custo de frete', 23.85, 23.85, NULL, 'Stationery > Gift & Wrapping > Gift Boxes', 'https://cf.shopee.com.br/file/br-11134207-23020-l28x9hwljhnv45', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F455834389%2F18873140158', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20498988983', 'Máscara De Tratamento Novex Repositor De Massa 400g', 'A MaxLanolina, presente em sua fórmula, é um poderoso agente amaciante que combate o ressecamento dos cabelos, penetrando na fibra capilar e restaurando o seu teor de hidratação natural. Modo de Usar: Aplique o Reparação Total nos cabelos úmidos. Deixe agir por 15 minutos. Enxágue bem. Aplique o Novex Blindagem Capilar e prossiga com a escova e prancha. Para finalizar, use o Nutrire Reparador de Pontas Queratina Absoluta. #html-body [data-pb-style="646BA64929353"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-position: Left top; background-size: Cover; background-repeat: No-repeat; background-attachment: Scroll; border-style: None; border-width: 1px; border-radius: 0px; margin: 0px 0px 10px; padding: 10px;}#html-body [data-pb-style="646BA64929367"]{border-style: None; border-width: 1px; border-radius: 0px; margin: 0px; padding: 0px;}', 24.67, 24.67, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lmx86dhffzcsba', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F20498988983', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
