INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43120803699', 'Formando Homens de Honra | Max Souza', 'Formando Homens de Honra | Max Souza Este livro é um chamado urgente para pastores, líderes e igrejas que desejam investir no coração masculino com intencionalidade, visão e fundamento bíblico. Aqui, você e seu ministério encontrarão direção e inspiração para cultivar um trabalho que forma homens com a força do leão e a mansidão do cordeiro, capazes de proteger, cuidar, liderar, servir e amar. Não é uma leitura qualquer, mas uma jornada para ser vivida, Quando uma igreja decide investir na formação de homens segundo o coração de Deus, ela fortalece o presente, molda o futuro e constrói um legado que atravessa gerações. Homens de honra não surgem por acaso. Eles são forjados no contexto de uma comunidade que ama, investe e acredita no que Deus pode fazer por meio deles. Título: Formando Homens de Honra Autor: Max Souza Número de páginas: 113 Acabamento: Brochura Dimensões: 14 cm larg. x 21 cm alt. Editora: Inspire', 35.9, 35.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-824gc-mf04vc8kgm4uad', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F43120803699', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
