INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58256601767', 'Garnier SkinActive Vitamina C Antioleosidade - Água Micelar 400ml', 'Água micelar para pele oleosa. Garnier SkinActive Vitaminca C Antioleosidade higieniza a pele, removendo impurezas e maquiagem, enquanto promove ação antioxidante. A Água Micelar Garnier SkinActive Vitaminca C Antioleosidade combina tecnologia micelar em uma loção de limpeza antioleosidade que cuida da pele. Sua fórmula adstringente ajuda a remover impurezas e maquiagem do rosto, com ação hidratante, tonificante e toque oil free. Produto cruelty free. Como usar: Aplique no rosto com a ajuda de um algodão ou uma toalha para remover as impurezas ou a maquiagem. Não é necessário enxágue. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 60.9, 60.9, NULL, 'Beauty > Skincare > Facial Cleanser', 'https://cf.shopee.com.br/file/sg-11134201-82600-mlmhwe9jeo0274', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58256601767', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49805162607', 'Kit inicial para guitarra elétrica de 39 polegadas com corpo em maple, afinador, bolsa para amplificador de guitarra', 'Guitarra elétrica modelo Telecaster de 39 polegadas: O corpo leve em yangmu, revestimento mate totalmente fechado, braço confortável em forma de C e design exclusivo da cabeça e da proteção tornam a guitarra elétrica mais reconhecível. A guitarra elétrica yangmuqin de tamanho normal tem uma ressonância excelente e um som clássico e retro, proporcionando-lhe a melhor experiência musical. Ponte exclusiva: A ponte fixa exclusiva é fácil de ajustar as cordas, com precisão de afinação estável, perda mínima de afinação e ressonância do corpo aprimorada. A guitarra elétrica Asmuse usa uma versão aprimorada dos botões padrão para uma afinação e troca de cordas mais convenientes, bem como uma afinação mais estável. Captador SS: O captador da guitarra elétrica modelo Telecaster é feito de bobina única Alnico personalizada, que tem menos ruído de corrente, frequência mais alta e som mais penetrante. Conjunto para principiantes: O conjunto de guitarra elétrica modelo Telecaster inclui os conjuntos básicos necessários: mochila, alça de ombro, cabo de conexão de 3 m, palhetas, pano de fricção, clipe de afinação, amplificador e afinador. Este é um ótimo presente para principiantes.', 2615.62, 993.94, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > String Instruments', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjtd7fnx5e6af3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1281436474%2F49805162607', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
