INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998981347', 'Duo Mystic Bloom - Body Splash 100ml e Hidratante Corporal 200g - Skelt', 'O Duo Mystic Bloom é um convite a se deixar levar pelos sentidos. No início, um sopro vibrante de groselha negra, morango e tangerina. Depois, as pétalas da plumeria se abrem ao lado da delicadeza da flor de maçã e do toque etéreo da flor de violeta, criando uma névoa floral que encanta. Neste jardim em que o místico se revela nos detalhes, o musk aveludado se une ao cashmeran, ao âmbar dourado e à doçura reconfortante do marshmallow. A fragrância foi desenvolvida pelos melhores perfumistas do mundo para reinventar o romantismo do jeito Skelt — ousado, confiante e extraordinário. Com alta fixação e projeção prolongada, projeta sua versão mais sofisticada e encantadora. Secret Garden Collection é um convite a olhar para si mesma e vestir a sua essência com atitude. PIRÂMIDE OLFATIVA: Notas de topo: groselha negra, morango, tangerina Notas de meio: plumeria, flor de maçã, flor de violeta Notas de fundo: musk, cashmeran, âmbar, marshmallow', 245.0, 220.5, NULL, 'Beauty > Bath & Body Care > Body Cream, Lotion & Butter', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mf8nkrdq54hxc8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1542778484%2F23998981347', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8427720685', 'Frigideira 2 Litros Profissional Com Revestimento Tramontina', 'O anúncio contém: 01 Frigideira. A Frigideira Tramontina Profissional em Alumínio Acabamento Externo Lixado com Revestimento Interno Antiaderente Starflon T3 Cabo Baquelite 28 cm de diâmetro 2 L foi produzida pensada na rotina de uma cozinha profissional e no cozinheiro que irá manuseá-la. Ela oferece praticidade nos preparos, tornando os cozimentos mais ágeis. Em alumínio de qualidade com acabamento externo lixado, proporciona também beleza e modernidade para o ambiente. Seu revestimento interno antiaderente Starflon T3 com maior poder de antiaderência, maior resistência a abrasão, maior durabilidade, maior facilidade na limpeza e livre de PFOA. O cabo de baquelite antitérmico evita possíveis queimaduras, além de tornar o manuseio da frigideira mais confortável e seguro. A linha de Frigideiras Profissionais é a escolha ideal para todos que pensam nos processos realizados em uma cozinha. Benefícios: -Corpo de alumínio com acabamento externo lixado. -Espessura da peça de 3 mm: distribuição uniforme do calor. -Revestimento interno de antiaderente Starflon T3. -O único com a tecnologia T: maior poder de antiaderência -Maior resistência à abrasão -Maior durabilidade -Mais fácil para limpar -Livre de PFOA, garantindo uma resistência à abrasão mais de 15.000 ciclos baseado na Norma ABNT NBR 15321:2013. -Cabo de aço inox e baquelite. Informações: Dimensões Aproximadas da Embalagem (AxLxC): 10cm x 35cm x 54cm Diâmetro da frigideira: 28cm Capacidade: 2L Material: Alumínio Antiaderente: Sim Tampa: Não Peso: 0,864g Fabricante: Tramontina -Produto novo e em estoque. -As cores do tecido ou desenhos do produto podem variar de acordo com o lote de fabricação. -Todos os produtos têm seguro contra extravio.', 229.9, 229.9, NULL, 'Home & Living > Kitchenware > Pans', 'https://cf.shopee.com.br/file/sg-11134201-22100-pbjjedauxniv85', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F365257077%2F8427720685', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13767822795', 'Tonalizante sem Amônia Burguesinha Probelle 6.0 Louro Escuro 50g probelle', 'TONALIZANTE BURGUESINHA ,DESCUBRA AS CORES VIBRANTES PROBELLE: Com 6 óleos essenciais e sem amônia, a burguesinha possui uma fórmula luxuosa e sofisticada, com altíssimo poder colorante. Enquanto você consegue a tonalidade dos seus sonhos,a burguesinha irá regenerar os fios, nutrindo-os em profundidade e devolvendo o movimento natural dos mesmos, além de prevenir o surgimento das pontas duplas e de fios ressecados e quebradiços. Cor muito mais viva, intensa e de longa duração. Cabelos ainda mais saudáveis e com um brilho impecável. ATIVOS; Tonalizante sem amônia e com óleos de Argan, Linhaça,Castanha,Lótus,Girassol e Semente de Uva', 16.45, 16.45, NULL, 'Beauty > Hair Care > Hair Colour', 'https://cf.shopee.com.br/file/sg-11134201-22120-pu3wusdssmlv19', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F648982173%2F13767822795', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
