INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23197500909', 'Guitarra Jackson JS20 Series Dinky', 'Somos a RCK AUDIO, sua loja virtual de Instrumentos Musicais e Áudio Profissional - Há mais de 10 anos no mercado - Mais de 150.000 clientes atendidos - Todos os produtos com Nota Fiscal - Revenda autorizada oficial do produto - Criterioso processo de embalagem e expedição ; Guitarra Jackson JS20 Series Dinky Rápidas, letais e acessíveis, as guitarras da série Jackson JS dão um salto épico, tornando mais fácil do que nunca obter o timbre, a aparência e a jogabilidade clássicos de Jackson sem gastar muito. O JS Series Dinky® JS20 DKAQ 2PT tem um corpo de maple, braço rápido de maple aparafusado com reforço de grafite e uma escala de amaranto com raio composto de 12 "-16" com 24 trastes jumbo e incrustações de barbatana de tubarão peroladas. Um par de captadores humbucking Jackson de alta saída com ímãs de cerâmica produz um tom claro com bastante circunferência e pode ser moldado com um seletor de lâmina de três vias e controles únicos de volume e tom. Este modelo também possui hardware totalmente preto, incluindo uma ponte tremolo de fulcro sincronizada, botões de alça padrão e afinadores fundidos. CARACTERÍSTICAS: Corpo de Poplar; Braço de bordo aparafusado com junta de lenço e reforço de grafite; Escala de amaranto com raio composto de 12"-16"; Incrustações Pearloid Sharkfin; Captadores Jackson de alto rendimento; 24 trastes jumbo; Sistema tremolo de fulcro de 2 pontos. Especificações: Neck: Headstock: Jackson® Pointed 6-In-Line; Headstock Binding: White; Neck Material: Maple; Neck Finish: Satin; Escala: Amaranth; Trastes: 24 Jumbo; Incrustação da Escala: Barbatana de tubarão perolada. Body: Corpo: Poplar; Finalização do Corpo: Gloss; Formato: Dinky; Body Top: Quilted Maple Art Grain; Material: Poplar. Hardware: Bridge: 2-Point Fulcrum Tremolo; Cordas: Nickel Plated Steel(.009 - 042); Placa do Braço: Jackson; Strap: Standard. Electronics: Captador da Ponte: Jackson® High-Output Humbucking; Captador de Braço: Jackson® High-Output Humbucking; Switching: 3-Position Toggle: Position 1. Bridge Pickup, Position 2. Bridge and Neck Pickups, Position 3. Neck Pickup; Controles: Volume and Tone.', 3044.81, 3044.81, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > String Instruments', 'https://cf.shopee.com.br/file/sg-11134201-7rdy1-m0ndnydho1h615', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F313967528%2F23197500909', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23898722151', 'Lubrificante Vandoren Para Cortiças Cork Grease para Instrumentos De Sopro', 'Somos a RCK AUDIO, sua loja virtual de Instrumentos Musicais e Áudio Profissional - Há mais de 10 anos no mercado - Mais de 150.000 clientes atendidos - Todos os produtos com Nota Fiscal - Revenda autorizada oficial do produto - Criterioso processo de embalagem e expedição ; Lubrificante Vandoren Para Cortiças Cork Grease para Instrumentos De Sopro Um acessório essencial para o cuidado de cortiças de clarinete e saxofone Esse lubrificante da Vandoren é produzido com as matérias primas da melhor qualidade. A leve fragrância de flor de macieira é suave e agradável. O recipiente em formato de tubo tem fundo rosqueável que facilita o uso, além de ser fácil de transportar, medindo 7cm x 2cm x 2cm. A marca Vandoren confere a esse produto toda a confiabilidade da fábrica, reconhecida internacionalmente. Com essa graxa, o músico mantém a "vida" da cortiça por muito mais tempo, sempre flexível e sedosa. Além disso, o lubrificante ajuda a selar a cortiça, evitando assim os vazamentos de ar durante a execução. Serve tanto para boquilhas de clarinetas e saxofones, assim como para as demais cortiças das junções da clarineta. Esse produto também pode ser utilizado para lubrificar conexões de flautas transversais e flautas doce, bocal de fagote, palhetas de oboé e corne inglês', 84.2, 84.2, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Music Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7rdy8-mccaidr8u0kxf7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F313967528%2F23898722151', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21599255770', 'Shampoo Pantene Pro-V Hidratacao 750ml', 'A estrutura do cabelo tende a se desidratar, ficando com aparência seca, maltratada e sem brilho. O sistema exclusivo Pantene Pro-V Hidratação nutre e hidrata profundamente cada fio, evitando cabelos rebeldes e dando brilho intenso. O shampoo Pantene Pro-V foi modernizado com novo sistema que proporciona uma sensação de limpeza mais duradoura. A fórmula também inclui um novo e exclusivo ingrediente condicionante que protege os cabelos quando estão mais vulneráveis, ou seja, durante a lavagem, prevenindo os danos que poderiam obrigar as mulheres a cortá-los. Limpeza eficaz, delicada e com mais espuma.', 65.82, 65.82, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-7rd6d-lvay7t6y8qk532', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050887704%2F21599255770', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
