INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22397505875', 'Desodorante Aerosol Rexona Men Antibacterial + Invisible 150ml', 'Quanto mais você se movimenta, mais fica protegido: Assim age o Desodorante Masculino Rexona Motion Sense. Ele possui tecnologia patenteada inovadora, que contém cápsulas inteligentes que se quebram conforme o movimento. Fornece evita a transpiração e o mau odor por até 48 horas, garantindo 10 vezes mais proteção. Ele ainda é dermatologicamente testado e não possui álcool na fórmula, assim proporciona todo a proteção e cuidado que suas axilas merecem.', 20.15, 20.15, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/sg-11134201-7rd5d-lvavewh2ac06ef', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050887704%2F22397505875', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
