INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8580188676', 'Touca de Natação Afro M Daminhacor Rosa', 'Modelo: Touca para Natação e Banho M - Adulto DaMinhaCor - Modelo: Unissex - Material: Silicone (Composição: 100%) - Origem: Produto Importado - Dimensões: 25.5cm altura, 29.5cm largura, 20cm abertura para cabeça. Recomendada para adultos com cabelos volumosos Obs.: As recomendações acima são apenas referenciais. Recomenda-se que você avalie o tamanho do seu cabelo, comparando-o com as dimensões de cada tamanho, antes da tomada de decisão MANUSEIO: - Ao colocar ou retirar a Touca utilize as pontas dos dedos, nunca use as unhas - Nunca puxar a Touca por sobre os Olhos, Nariz e Boca - Ao usar a Touca, não use Grampos, Presilhas e Similares no Cabelo - Após vestir a touca, pressione com as mãos para RETIRAR O AR de dentro, deixando a touca rente aos seus cabelos - Após o uso, lave em água corrente, secando com pano seco e limpo - Evite guardar o produto molhado - Guardar em lugar fresco e arejado e longe de fontes de calor - Evite contato com objetos pontiagudos - Nunca cortar ou alterar o formato original do Produto PRECAUÇÕES: - Caso ocorra irritação na pele ou couro cabeludo, suspenda o uso imediatamente. - Crianças não devem utilizar o produto sem supervisão de um adulto. Conteúdo da Embalagem: 01 un. Afro Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Imagem meramente ilustrativa.', 119.0, 119.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Swimming & Diving', 'https://cf.shopee.com.br/file/a274724045080b20487474c7f9fa1293', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F429366971%2F8580188676', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
