INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19198090028', '200 GANCHOS PARA OVO DE PÁSCOA P- CABIDE AZUL 50/250 (SAN FELIPO)', 'Ganchos (P) Para Ovo De Páscoa - Cabide AZUL IDEAL PARA OVOS DE 50/100/150/200/250 GRAMAS Ganchos de ovos de plástico, moldado em um design intrincado e funcional. Ele é feito de um material plástico azul, com uma superfície lisa e um leve brilho. O design consiste em duas metades simétricas, unidas por uma fina faixa de plástico no centro. Cada metade possui uma forma curva, com uma série de dentes internos que se projetam para dentro. Esses dentes são projetados para segurar o ovo com segurança, evitando que ele escorregue ou quebre. *Demonstração e explicação "Observe que esta unidade possui dois ganchos de ovos tamanho P, conectados. Para separá-los, basta cortar com cuidado a área de conexão até que se soltem. Assim, você terá dois suportes individuais prontos para uso." QUANTIDADE NO TITULO DO ANUNCIO MATERIAL PLASTICO', 56.85, 56.85, NULL, 'Home & Living > Kitchenware > Bakewares & Decorations', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m6zh9nrqasefc3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F455834389%2F19198090028', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
